quests[30595] = { id = 30595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Historische Geschäfte", description = "Lasst mich raten: Ihr seid hier, um Euch um die Mogustatuen zu kümmern, die zu Leben erwacht sind. Was für ein Zufall, denn ich bin hierher gekommen, um... öh... die Mogu zu erforschen.\n\nIch mache Euch einen Vorschlag: Wenn Ihr mir so viele Relikte der Mogu von da drinnen bringt, wie Ihr tragen könnt, bekommt Ihr einen Anteil. Von den... Forschungsgeldern.", sourceObjective = "Sammelt 12 Relikte der Mogu.", progress = "Wo soll ich nur all diese Relikte unterbringen?", completion = "Du meine Güte! Also wirklich! Ich danke Euch, {name}!\n\n\n\nJetzt wo Ihr den Weg geebnet habt, ziehe ich vielleicht selbst los. Nur noch ein paar Relikte aus den Außenbereichen. Nichts Gefährliches.", sourceObjectiveStatus = "unverified-source-field" }
quests[30596] = { id = 30596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Zandalari-Troll?", description = "Während Ihr die erweckten Mogustatuen zerstört habt, hat Euch ein Troll mit dem unverwechselbaren Akzent der Zandalari verspottet.\n\nMit anderen Worten: Die Gefahr für die Westwindruhestätte ist nicht vorüber, bis er erledigt ist.", sourceObjective = "Tötet den Seelenerwecker der Zandalari.", sourceObjectiveStatus = "unverified-source-field" }
quests[30597] = { id = 30597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsamer runder Stein", description = "Dieser wunderschöne Stein verfügt eindeutig über magisches Potenzial... zumindest für jemanden, der Erfahrung in Alchemie hat. Ihr seid Euch sicher, dass dieser Stein mit den richtigen, in Pandaria heimischen Kräutern äußerst nützlich werden könnte.", sourceObjective = "Durchtränkt den Stein mit mehreren Goldlotus.", sourceObjectiveStatus = "unverified-source-field" }
quests[30598] = { id = 30598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer hätte gedacht, dass Fische Eier mögen?", description = "Große Kraniche haben über Generationen hinweg in dieser Gegend genistet. Die Narsongtürme bieten eine geschützte Umgebung, in der sie ihre Jungen großziehen können.\n\nIhre makellosen Eier sind bekannt dafür, einen exzellenten Köder für Silbergrundeln abzugeben. Beschafft ein Kranichei und findet heraus, ob auch Ihr eine Grundel fangen könnt!", sourceObjective = "Besorgt ein makelloses Kranichei von den Narsongtürmen und fangt damit eine Silbergrundel.", progress = "Habt Ihr eine Silbergrundel gefangen?", completion = "Unglaublich, eine Silbergrundel! Ihr werdet wahrlich ein Angler, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[30599] = { id = 30599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Affengötze", description = "Früher hielten die Grummel die Ho-zen davon ab, alles zu verwüsten. Sie bestachen sie einfach mit Essen.\n\nAber jetzt haben die Bruchzahn-Ho-zen südlich von hier große, magische Götzenbilder. Der Uuk von Knatz hat ihnen beigebracht, wie sie durch Opfergaben Macht aus diesen Götzen ziehen.\n\nSie nutzen diese Magie, um Grummel zu töten!\n\nIhr müsst diese Götzen zerstören!\n\nZu jedem Götzen gehört ein Häuptling. Tötet den Häuptling und werft seinen Leichnam auf ihren Altar.", sourceObjective = "Werft die Leichname von Tak Tak, Dak Dak und Ko Ko auf ihren jeweiligen Altar.", progress = "Ist Unglück, auf eigenem Altar geopfert zu werden.", completion = "Ein selbstbewusster Ho-zen ist ein gefährlicher Ho-zen.\n\nDanke für Eure Hilfe, Freund der Grummel.", sourceObjectiveStatus = "unverified-source-field" }
quests[30600] = { id = 30600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es bleibt kein Paket zurück", description = "Die Ho-zen der Bruchzahn südlich von hier haben alle meine Grummel getötet. Was noch schlimmer ist, ihre Pakete wurden nicht abgeliefert.\n\nDem Glück missfällt ein Grummelpaket, das nicht ausgeliefert wird.\n\nBitte, gebt meinen Grummel Frieden auf dem langen Weg ins Jenseits und bringt mir ihre Grummelpakete.\n\nIch werde dafür sorgen, dass sie ausgeliefert werden.", sourceObjective = "Bergt 8 Grummelranzen aus dem Bruchzahnlager oder Der Tieferen.", progress = "Grummel sind einfach Leute. Wir geschaffen für erkunden und tragen.", completion = "Ihr bringt Grummel Glück.\n\nWenn wir wieder im Hauptlager sind, muss ich Euch das geruchsintensivste, glückbringendste Räucherstäbchen kaufen, das ich finden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[30601] = { id = 30601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mut auf Bestellung", description = "Es ist größtes Unglück, Bergpfade ohne guten Führer zu passieren. Wir Grummel haben die besten Führer, aber viele weggerannt. Sie fürchten sich jetzt vor dem Bergpass. Viele gute Grummel dort oben verschwunden.\n\nGrummel gut bei vielen Dingen, aber nicht sehr tapfer. Vielleicht Ihr könnt sie mit Feuerlotusräucherwerk tapfer machen. Dann führen sie Euch.", sourceObjective = "Veranlasst 3 versteckte Bergführer in der Höhle der heulenden Winde Euch zu helfen.", completion = "Räucherkrams wirkt wie Zauber! Aber Wirkung ist nicht lang. Ihr müsst Euch beeilen!", sourceObjectiveStatus = "unverified-source-field" }
quests[30602] = { id = 30602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hasenpfote", description = "Die Bruchzahn-Ho-zen haben unseren Hasenpfote gestohlen! Er war der Grummel mit dem größten Glücksbringer.\n\nDas ist großes Pech. Bitte, {race}, bringt uns Hasenpfote zurück. Wir brauchen sein Glück.\n\nWürdet Ihr im Bruchzahnaußenposten nach ihm suchen?", sourceObjective = "Rettet Bruder Hasenpfote aus dem Bruchzahnaußenposten.", completion = "Seht nur, was Bruchzahns und Faustkloppers mit Grummel-Wegstation gemacht haben. Kaum noch Glücksbringer zu finden.\n\nGrummel hatten Vereinbarung mit Ho-zen. Wir geben Nahrung, sie nicht plündern. Immer wenn sie plündern wollen, erinnern Shado-Pan sie, nicht zu plündern.\n\nAber jetzt alle Shado-Pan weg, die Mauer verteidigen. Und Ho-zen wollen mehr Nahrung, als Grummel haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[30603] = { id = 30603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bruchzahn-Plot", description = "Sie stehlen meinen Glücksbringer! Ihr Ho-zen-Anführer hier, Mo Mo, stiehlt meine Hasenpfote.\n\nDas ist großes Unglück für Grummel. Meine Hasenpfote ist großes Glücksbringer für Grummel überall. Wenn die Ho-zen lernen, wie Hasenpfote Glück bringt, ist alles verloren.\n\nBitte, könnt Ihr sie zurückholen?", sourceObjective = "Nehmt Mo Mo Hasenpfotes Glücksbringer wieder ab.", progress = "Grummel erhalten Namen von Glücksbringer, das diese Grummel am meisten Glück bringt. Ho-zen dürfen niemals stehlen Glück.", completion = "Mein Glücksbringer! O, dies ist ein Glückstag! Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[30604] = { id = 30604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruchzähne brechen", description = "Ho-zen plündern nur, wenn sie denken, Essen ist wenig für ihre Münder.\n\nAber bei den Ho-zen sind immer mehr Münder als Essen.\n\nJetzt gibt es nur noch sehr wenige Grummel.\n\nEs ist viel verlangt, aber könnt ihr <ein Freund/eine Freundin> der Grummel sein und einige der Bruchzahn-Ho-zen südlich von hier beseitigen? Nur so können wir sie abhalten, die Landschaft zu zerstören.", sourceObjective = "Tötet 8 Bruchzahnstürmer und 6 Bruchzahnwerfer.", completion = "Danke, {name}! Hoffentlich jetzt weniger Bruchzahn-Plündereien.", sourceObjectiveStatus = "unverified-source-field" }
quests[30605] = { id = 30605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glückbringendes Yakhufeisen", sourceObjective = "Rettet Bruder Yakschuh.", completion = "Glück, dass ein Glücksbringer wie Ihr mich rettet.\n\nUnd Bruder Hasenpfote sagt immer, ich hab' kein Glück. Pah!", sourceObjectiveStatus = "unverified-source-field" }
quests[30606] = { id = 30606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faustklopper kloppen", description = "Die Faustklopp-Ho-zen haben neuen Häuptling, den Uuk von Knatz.\n\nEr sieht Angst im Westen, Zorn im Süden, Hass im Norden und Yaungol im Osten.\n\nAlso sorgt er dafür, dass seine Ho-zen plündern, um Nahrung und Vorräte für die kommende Dürre zu sammeln.\n\nEs sind viele Faustklopper und sie sind gefährlich.\n\nBitte, Glücksbringer, könnt Ihr ihre Kämpfer besiegen?", sourceObjective = "Tötet 8 Faustkloppzerkracher oder Faustkloppaufspieker im Faustklopploch.", completion = "Ihr seid wahrer Glücksbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[30607] = { id = 30607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entfesselte Kräfte", description = "Die Ho-zen haben einen Yeti! Sie nennen ihn Alter Müffel und halten ihn tief in ihrer Höhle.\n\nEigentlich haben die Ho-zen Angst vor Yetis, aber jetzt füttern sie ihn mit Grummeln.\n\nSie haben einen Jagdhäuptling, Cho Cho der Verruchte. Könnt Ihr nachsehen, ob er einen Schlüssel für die Fesseln des Yetis bei sich hat?\n\nPech für die Ho-zen, wenn ein Yeti frei in ihrer Festung herumläuft.", sourceObjective = "Holt den Schlüssel für Yetifesseln von Cho Cho dem Verruchten und lasst den Alten Müffel frei.", progress = "Glücksbringer sollte nicht auf dreckige Yak zu Yeti reiten.", completion = "Oh! War wilde Ritt, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[30608] = { id = 30608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yetisnacks", description = "Sie haben meine Grummel mitgenommen! Ho-zen essen keine Grummel... Aber Yetis. Und Faustklopper haben Yeti.\n\nBitte rettet meine Grummel. Schneidet sie los. Oder befreit sie aus Käfig. Rettet so viele wie möglich.\n\nWenn gelingen, warten Glück und Belohnung auf Euch.", sourceObjective = "Rettet 5 eingesperrte Grummel, indem Ihr sie losschneidet oder aus den Käfigen befreit.", completion = "Heute ist ein Tag von gutem Glück und nicht so gutem Glück. Nicht so gutes Glück, dass Ho-zen meine Grummel geklaut haben. Gutes Glück, dass {race} meine Grummel gerettet hat. Nicht so gutes Glück, dass so viele Ho-zen sterben mussten, um Lektion zu lernen. Gutes Glück, dass {race} Glücksbringer ist und weiß, wie man kämpft.\n\nGrummel sind keine Kämpfer. Wir tragen, wir erkunden, wir sind zufrieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[30610] = { id = 30610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grummel! Grummel! Grummel!", description = "Jetzt, wo Grummel gerettet sind, müssen wir unsere Vorräte retten.\n\nDer Uuk von Knatz ist nur Häuptling, weil er Vorräte hat.\n\nGeht zur Knatzelkuppel im Nordwesten. Nehmt ein paar Grummel mit. Beschützt sie und bringt sie in die Nähe der Vorratskisten.\n\nAb da wissen Grummel, was zu tun ist.\n\nHasenpfote und ich treffen Euch dort.", sourceObjective = "Führt 5 unbeladene Grummel zu den Vorratskisten bei der Knatzelkuppe.", progress = "Grummel können gut Sachen tragen.", completion = "Jetzt wird dieser König der Ho-zen herausfinden, warum es Pech bringt, Grummel zu betrügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30611] = { id = 30611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheit für den Yeti!", description = "Euer Yeti-Ritt bringt mich auf eine Idee. Der Uuk von Knatz hat einen Yeti als Haustier, heißt Mampf Mampf.\n\nMit Yeti schüchtert er andere Ho-zen ein, damit sie ihn zum Anführer von Ho-zen machen. Wir müssen Yeti loswerden.\n\nGeht zum Uuk von Knatz und besiegt ein paar Käfigmeister, damit Mampf Mampf nicht so fest angebunden ist.\n\nHufeisen und ich treffen Euch dort mit viel Räucherwerk und schmutzigem Yak.", sourceObjective = "Tötet 4 Käfigmeister.", progress = "Wir haben Yak gefunden. Habt Ihr Ho-zen ausgeschaltet?", completion = "Bereit für Yeti?", sourceObjectiveStatus = "unverified-source-field" }
quests[30612] = { id = 30612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Anführer der Ho-zen", description = "Die Zeit ist gekommen, uns Uuk von Knatz zu stellen. Wir schlagen ihn, und die Ho-zen haben keinen mehr, der ihnen sagt, sie sollen plündern.\n\nDas ist der Plan: Hufeisen führt Quastel in die Arena und macht Mampf Mampf Angst, bis er fortläuft.\n\nDann schleicht Ihr hinein und kämpft gegen den Uuk von Knatz, während seine Ho-zen vom Yeti abgelenkt sind, der in ihrem Zuhause wütet.\n\nWir treffen Euch im Basislager am Kota mit einer großen Belohnung. Viel Glück für Euch, <Freund/Freundin> der Grummel.", sourceObjective = "Provoziert Mampf Mampf und besiegt dann den Uuk von Knatz.", completion = "Der Uuk von Knatz ist tot! Hurra!", sourceObjectiveStatus = "unverified-source-field" }
quests[30613] = { id = 30613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gepanzerter Karpfen", description = "Gepanzerte Karpfen gelten in dieser Gegend als eine Delikatesse.\n\nLeider können wir sie nicht angeln, da ihre gewaltigen Kiefer kurzen Prozess mit unseren Haken machen. Nehmt diesen Fischspeer und versucht, einige für uns zu fangen.", sourceObjective = "Benutzt den Fischspeer, um 5 gepanzerte Karpfen in den Gewässern südlich der Anlegestelle der Angler zu fangen.", progress = "Hattet Ihr Glück mit diesem Fischspeer?", completion = "Passt mit diesen Karpfen auf, {name}. Die haben schon Leuten Finger abgebissen!", sourceObjectiveStatus = "unverified-source-field" }
quests[30614] = { id = 30614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ölprobe", description = "Als die Yaungol herkamen, begannen sie, nach Öl zu graben. Ich frage mich, was dieses \"Öl\" ist? Vielleicht ist es ein Ding von viel unentdecktem Glück. Das muss ich wissen.\n\nHier, nehmt diese Phiole und füllt sie mit Yaungolöl von einer der Windmühlen. Ich werde Euch Reichtümer geben, wenn Ihr mir etwas davon bringt.", sourceObjective = "Füllt die leere Ölphiole an einem Yaungolbohrturm.", progress = "Yaungol sind ganz gruselig. Yaungol mit einem Glücksbringer wie diesem \"Öl\" sind nur noch mehr ganz gruselig.", completion = "Glückstag! Eure Belohnung. Mögen Euch diese Münzen viel Glück bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30615] = { id = 30615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Zandalari-Troll?", description = "Während Ihr die erweckten Mogustatuen zerstört habt, hat Euch ein Troll mit dem unverwechselbaren Akzent der Zandalari verspottet.\n\nMit anderen Worten: Die Gefahr für die Westwindruhestätte ist nicht vorüber, bis er erledigt ist.", sourceObjective = "Tötet den Seelenerwecker der Zandalari.", sourceObjectiveStatus = "unverified-source-field" }
quests[30616] = { id = 30616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verkehrsprobleme", description = "Yaungol greifen unseren Jutepfad an. Das ist großes Unglück für Grummel.\n\nWir nutzen diesen Pfad, um Vorräte zum Schlangenrücken zu bringen. Ohne Vorräte sind die Verteidiger der Mauer in Gefahr.\n\nGrummel sind Träger und Forscher, nicht Kämpfer. Könnt Ihr unser Glücksbringer sein und die Yaungolblockade beenden?", sourceObjective = "Besiegt 8 Yaungol des Streitlagers Ruqin.", completion = "Großes Glück, dass {race} Grummel hilft. Auch großes Glück für Freund der Grummel.", sourceObjectiveStatus = "unverified-source-field" }
quests[30617] = { id = 30617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützung am Straßenrand", description = "Ein Glückspilz denkt daran, Räucherwerk auf einer Reise durch die Berge mitzunehmen. Je stärker der Glücksgeruch, desto besser.\n\nKönnt Ihr der Straße hinaus nach Einfass folgen und das Räucherwerk, das Ihr entlang des Wegs findet, entzünden?\n\nDas wird den Grummel, die die Straße entlangreisen, viel Glück bringen.\n\nBruder Flusenbeutel kann Euch viele Belohnungen geben. Sprecht mit ihm, wenn Ihr ankommt.", sourceObjective = "Entzündet acht Mal glückbringendes Juteräucherwerk entlang der Straße nach Einfass.", completion = "Willkommen in Einfass! Zugang zum Jutepfad und zum Nimmerlaya.", sourceObjectiveStatus = "unverified-source-field" }
quests[30618] = { id = 30618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Ware für Einfass", description = "Wenn Ihr nach den besten Vorräten am Kun-Lai sucht, seid Ihr hier genau richtig! Oh sicher, es sieht etwas leer aus. Doch lasst Euch nicht von Äußerlichkeiten täuschen...\n\nAch, wem will ich denn etwas vormachen?! Die Angriffe der Ho-zen sowie die Tatsache, dass die wenigen Vorräte, die wir bekommen, von den Geistern gestohlen werden, haben meinen Bestand besorgniserregend verringert.\n\nWenn Ihr mir helfen könntet, einige meiner Vorräte zurückzubekommen, dann habe ich wahrscheinlich genug, um etwas zu Eurer Reise beizusteuern.", sourceObjective = "Bergt 8 gestohlene Vorräte aus der Heulwindhöhle.", progress = "Habt Ihr einige meiner Waren wiedergefunden?", completion = "Oh, ich danke Euch, {name}! Wenn ich jetzt die angenagten Stücke abschneide und die kleinen Schäden beseitige, kann ich die vielleicht noch verkaufen.\n\nWenn Euer Wagen bereit zur Abreise ist, werde ich die versprochenen Vorräte aufladen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30619] = { id = 30619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogulasch", description = "Ich weiß, Eure Freunde machen sich Sorgen um die belebten Statuen drüben in Mogujia, aber ich sage Euch, um was Ihr Euch wirklich Sorgen machen solltet.\n\nWo es belebte Statuen gibt, gibt es auch Mogu. Ich weiß zwar nicht, ob Ihr schon einmal einen gesehen habt, aber falls nicht...\n\nNun, es reicht zu sagen, dass Mogu üble, üble Nachrichten bedeuten.\n\nWenn man sich um ein Problem kümmert, muss man den Mogu finden, der dahinter steckt!", sourceObjective = "Tötet den Seelenerwecker der Mogujia.", completion = "Das sind gute Nachrichten! Ihr habt unser aller Leben gerettet.\n\nIhr könnt Euch gar nicht vorstellen, wie viel Ärger die verursachen können.\n\nOder, na ja, jetzt könnt Ihr es Euch vielleicht doch vorstellen. So ungefähr. Fast.\n\nStellt Euch genau das vor, was Ihr Euch vorstellen würdet, und dann wäre es noch viel schlimmer und würde tausende Jahre lang andauern.", sourceObjectiveStatus = "unverified-source-field" }
quests[30620] = { id = 30620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogulasch", description = "Ich weiß, Eure Freunde machen sich Sorgen um die belebten Statuen drüben in Mogujia, aber ich sage Euch, um was Ihr Euch wirklich Sorgen machen solltet.\n\nWo es belebte Statuen gibt, gibt es auch Mogu. Ich weiß zwar nicht, ob Ihr schon einmal einen gesehen habt, aber falls nicht...\n\nNun, es reicht zu sagen, dass Mogu üble, üble Nachrichten bedeuten.\n\nWenn man sich um ein Problem kümmert, muss man den Mogu finden, der dahinter steckt!", sourceObjective = "Tötet den Seelenerwecker der Mogujia.", progress = "Habt Ihr ihn gefunden? Ist er tot? Nein? Oh oh. Macht mir doch keine Angst!", completion = "Das sind gute Nachrichten! Ihr habt unser aller Leben gerettet.\n\nIhr könnt Euch gar nicht vorstellen, wie viel Ärger die verursachen können.\n\nOder, na ja, jetzt könnt Ihr es Euch vielleicht doch vorstellen. So ungefähr. Fast.\n\nStellt Euch genau das vor, was Ihr Euch vorstellen würdet, und dann wäre es noch viel schlimmer und würde tausende Jahre lang andauern.", sourceObjectiveStatus = "unverified-source-field" }
quests[30621] = { id = 30621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glücksbringer vermisst", description = "Meine Reisen durch Kun-Lai haben mich zwei Dinge gelehrt: Erstens, sich niemals an einen schlafenden Yak heranzuschleichen, und zweitens, das Glück auf seiner Seite zu haben ist ein Muss, aber gar nicht so einfach.\n\nDie Grummel tragen stets einen Glücksbringer bei sich. Tja, und wenn ein einzelner Glücksbringer einem manchmal Glück bringt, dann müssen viele Glücksbringer das Glück doch garantieren!\n\nNach meiner Ankunft in Einfass sind mir meine Glücksbringer von diesen lästigen kleinen Geistern gestohlen worden. Ich wäre wirklich dankbar, wenn Ihr sie mir zurückholen würdet.", sourceObjective = "Bringt Ji-Lu seinen Shed-Ling-Glücksfuß, sein Yakhufeisen, das vierblättrige Glückskleeblatt und die Goldmünze.", progress = "Habt Ihr meine Glücksbringer finden können? Glück kann man nämlich nie genug haben.", completion = "Danke! Anscheinend haben meine Glücksbringer Euch auch geholfen, {class}. Während Ihr unterwegs wart, habe ich nicht gespielt und auch nicht meinen Karren verloren.\n\nIch würde ihn Euch gern für Eure Reise leihen. Außerdem muss ich einiges von diesem zwielichtigen Grummel zurückgewinnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[30622] = { id = 30622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es wird ausgeschwärmt", description = "Ohne die Mauer als Schutz haben wir keine Chance. Hättet Ihr nicht so viele Leute zusammenbekommen, stünde es schlecht um uns.\n\nMeldet Euch bei Wachkapitän Eichenschild - er sollte sich in der Nähe des Mauerdurchbruchs befinden. Tötet unterwegs so viele Mantis, wie Ihr könnt.\n\nWenn wir gewinnen, gewinnen wir. Falls wir verlieren, tun wir das nicht kampflos. Für Pandaria!", sourceObjective = "Tötet 15 Krieger der Ik'thik oder Verseucher der Ik'thik.", completion = "Meine Mauer... Ich habe mein ganzes Leben darauf verbracht...", sourceObjectiveStatus = "unverified-source-field" }
quests[30623] = { id = 30623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Sha-mützel", description = "<Mei zeigt zum Schlachtfeld.>\n\nSeht Ihr diese riesigen Mantiskommandanten dort draußen auf den Feldern? Sie haben eine seltsame Aura, die mich an die Traurigkeit erinnert, die wir in Zhus Wacht gesehen haben.\n\nVielleicht... stehen auch sie unter dem Einfluss des Sha?\n\nIch habe Ken-Kens Maske behalten - mit der hat er Yi-Mo das Sha ausgetrieben. Ich glaube, wenn wir sie den Mantis aufsetzen, können wir sie davon überzeugen, umzukehren.", sourceObjective = "Setzt Ken-Kens Maske 5 Schwadronskommandanten der Ik'thik auf und besiegt dann die Manifestationen der Angst, die herauskommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30624] = { id = 30624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Bierchen in Ehren", description = "Ich hab' nachgedacht.\n\nWir haben ja das ganze Bier, das Chen gebraut hat, und die vielen Leute, die Ihr zusammengetrommelt habt. Wir sollten die beiden zusammenbringen.\n\nDa sind Leute auf den Feldern, die ihr Leben für Pandaria riskieren. Wir beide sollten denen zumindest ein, zwei Fässchen vorbeibringen.\n\nDann können sie mit ihren Krügen auf den Sieg anstoßen. Oder sie haben sich ein letztes Bierchen hinter die Binde gekippt, bevor sie von einem Mantis niedergemetzelt werden. Wie auch immer - ich will nicht, dass sie ohne ein gutes Bierchen im Bauch in den Kampf ziehen.", sourceObjective = "Bringt etwas Bier zu den Wächtern von Zhu, den Priestern der Kranichschwingen, den Shado-Pan und den Nachtelfensiedlern.", sourceObjectiveStatus = "unverified-source-field" }
quests[30625] = { id = 30625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Schüler mehr", description = "Diese fünf Schüler - diejenigen, die den verborgenen Meister gesucht haben - sind ganz alleine an die Front gegangen. Ich würde ihnen ja Shado-Pan als Unterstützung schicken, wenn ich noch welche erübrigen könnte.\n\nDa sind gefährliche Wesen in der Nähe der Mauer. Wenn Ihr diese Schüler findet, sorgt dafür, dass sie ihnen nicht zum Opfer fallen.", sourceObjective = "Findet die Kampfkunstschüler und helft ihnen dann, einen Blutwüter, eine Eier-Matrone, einen Sehnenreißer und einen Furchtschürer der Ik'thik zu erledigen.", completion = "Die können so nicht mehr ewig weiterkämpfen. Sie sind zweifelsohne heldenhaft, aber ich will nicht, dass sie als Helden ihr Leben lassen müssen.\n\nEs ist an der Zeit, das Handtuch zu werfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30626] = { id = 30626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückzug!", description = "Ich ziehe die wenigen Truppen, die ich noch habe, zurück. Wir müssen uns bis zur Brauerei Sturmbräu oder sogar bis nach Halbhügel zurückziehen. Diese Entscheidung überlasse ich Wachkommandant Lun Mai.\n\nGeht Ihr voraus. Informiert den Kommandanten. Meine Shado-Pan werden kurz darauf folgen.", sourceObjective = "Meldet Euch bei Lun Mai in Steinpflug im Tal der Vier Winde.", completion = "Ich verstehe.\n\nNun, wir haben alles gegeben. Es ist Zeit für eine Evakuierung, Leben zu retten und unsere Strategie zu überdenken, bevor diese Mantis das komplette Tal übernehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30627] = { id = 30627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retter von Steinpflug", description = "Dieser Kommandant spricht hastig. Er hat die Waffe, die er braucht, um diese Schlacht zu gewinnen. Er hat EUCH.\n\n\"Aber das ist unmöglich\", sagt Ihr vielleicht.\n\nDas stimmt aber nicht. Es ist nicht unmöglich. NICHTS IST UNMÖGLICH.\n\nGeht jetzt, {name}. Geht und rettet Steinpflug!", sourceObjective = "Redet mit Fräulein Fanny in Steinpflug. Tötet dann mit ihrer Hilfe den Mantis-Koloss.", progress = "Es ist alles verloren, {name}. Packt Eure Sachen. Wir machen uns auf nach Halbhügel.", completion = "Ich kann es nicht glauben! Ihr - ein fremder {race} - habt das geschafft, an dem die Shado-Pan bisher gescheitert waren. Ihr hattet Erfolg, als die MAUER versagte.\n\nVielleicht können wir dieses Dorf ja doch noch halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[30628] = { id = 30628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinpflugs Dankbarkeit", description = "Noch eine letzte Sache, {name}. Keine Sorge, es handelt sich nicht um einen weiteren Gefallen. Ihr habt heute schon genug Mantis getötet.\n\nWir haben kürzlich eine Lieferung hochqualitativer Rüstung vom Kun-Lai-Gipfel erhalten. Ich wollte das eigentlich für meine Leute aufheben... aber ich denke, niemand hat das mehr verdient als Ihr. Geht einfach in den zweiten Stock des Gasthauses hier in der Stadt.", sourceObjective = "Sucht die Truhe des Kommandanten und holt Euch Eure Belohnung.", completion = "Ihr seht hinein und findet dort...", sourceObjectiveStatus = "unverified-source-field" }
quests[30630] = { id = 30630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In das Tal", description = "Ah, ich habe auf Eure Ankunft gewartet, <Reisender/Reisende>.\n\nIch wünschte, wir könnten uns unter besseren Umständen treffen, aber leider ist die derzeitige Situation im Tal alles andere als erfreulich.\n\nAber lasst uns im Moment nicht darüber sprechen. Besucht Matrone Vi Vinh im Schrein der Sieben Sterne.\n\nSie wird Euch dabei helfen, Euch einzuleben.", sourceObjective = "Sprecht mit Matrone Vi Vinh im Schrein der Sieben Sterne im Tal der Ewigen Blüten.", sourceObjectiveStatus = "unverified-source-field" }
quests[30631] = { id = 30631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schrein der Sieben Sterne", description = "Schaut Euch diese Kreatur an. Direkt als wir ankamen, hat uns der Moguattentäter ohne jede Vorwarnung angegriffen.\n\nSein Klingenstreich galt dem Anführer des Goldenen Lotus. Es war ein sehr glücklicher Umstand, dass wir hier waren und den Angriff vereiteln konnten.\n\nNach diesem Angriff auf Zhi fürchte ich auch um die Leben derer, die das Tal bereits betreten haben.\n\nDie Verwalter bringen Eure Leute in der Stadt im Südosten unter. Geht und sprecht mit den Anführern. Sorgt für ihre Sicherheit.", sourceObjective = "Sprecht mit Jaluu dem Spendablen, Kuru dem Gutgelaunten, der Ältesten Lin und Matrone Vi Vinh im Tal der Ewigen Blüten.", progress = "Die Städte erwachen zu neuem Leben.", completion = "Gute Arbeit, {name}. Willkommen in der Stadt.\n\nDennoch müssen wir wachsamer sein als zuvor, wenn wir für jedermanns Sicherheit sorgen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30632] = { id = 30632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Guo-Lai-Ruinen", description = "Laut Zhi dem Harmonischen bewegen sich die Mogu aus Richtung der Guo-Lai-Ruinen im Westen in das Tal.\n\nIch habe Anji und Kun zum Erkunden der Situation ausgesandt, aber bis jetzt sind sie noch nicht zurückgekehrt.\n\nIch brauche jemanden, der so tapfer ist wie Ihr, {class}, um nach ihnen zu suchen.", sourceObjective = "Sprecht mit Anji Herbstlicht bei den Guo-Lai-Ruinen im Tal der Ewigen Blüten.", completion = "Leven schickt Euch? Ich hoffe, Ihr seid bereit für einen Kampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[30633] = { id = 30633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nieder mit den Spähern", description = "Uns wurde von Mogusichtungen im Tal berichtet, aber die Situation ist viel schlimmer als wir angenommen hatten.\n\nDie Ruinen im Nordwesten wimmeln von Spähern. Sie sammeln Informationen und stehlen Schätze.\n\nEuer Auftrag ist eindeutig: Erledigt alle Späher, denen Ihr begegnet. Ohne ihre Augen lässt sich eine Armee nicht bewegen.", sourceObjective = "Tötet 8 Vorläufer der Shao-Tien.", completion = "Gut gemacht, {race}. Das sollte den Mogu verdeutlicht haben, dass mit uns nicht zu spaßen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[30634] = { id = 30634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnernder Empfang", description = "Lao Samtfuß und ich haben die Ruinen im Norden ausgekundschaftet.\n\nOffensichtlich dringen die Mogu durch eine Höhle gleich da oben in den Bergen in das Tal ein. Und sie schicken auch bereits Verstärkungen auf diesem Wege durch.\n\nEs sind zu viele, um sie frontal zu bekämpfen, deshalb müsst Ihr Euch mit Lao Samtfuß am Eingang der Ruinen treffen.\n\nEr wird Euch helfen, dort unbemerkt hinein zu gelangen. Dann könnt Ihr dieses Sprengstofffass am Eingang der Höhle deponieren.\n\nDer Rest sollte sich dann von selbst erledigen.", sourceObjective = "Sprecht mit Lao Samtfuß am Fuß des Ruinenberges und folgt ihm dann den Pfad hinauf. Deponiert dann das explosive Fässchen am Höhleneingang des Ruinenberges.", progress = "Ist die Höhle etwa geschlossen?", completion = "Wunderbar, {name}!\n\nIhr und Lao habt ganz allein den Moguvorstoß zunichtegemacht.\n\nSo geht man klug vor und macht sich die Arbeit leichter.", sourceObjectiveStatus = "unverified-source-field" }
quests[30635] = { id = 30635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod den Qilen", description = "Wir haben das Problem mit den Spähern vorerst gelöst, aber unten am Fuße der Berge, in den Guo-Lai-Hallen, treiben sich immer noch Vorstoßtruppen der Mogu herum.\n\nUnd leider werden ihre Operationen tiefer in den Ruinen von wilden und bösartigen Hunden bewacht.\n\nIch möchte, dass Ihr diese Bestien erledigt. Aber seid auf der Hut: Sie verstehen es, sich gut ihrer Umgebung anzupassen und sich zu verstecken.", sourceObjective = "Tötet 9 Steinwächter.", completion = "Sehr gut. Diese Hunde kennen keine Gnade. Umso besser also, dass Ihr ihnen auch keine gewährt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30636] = { id = 30636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steine der Macht", description = "Vor vielen Tausend Jahren haben die Herrscher des Tals einen Kristall namens Jubelit als Energiequelle genutzt.\n\nMit seiner Hilfe konnten sie ganze Städte, Fabriken und ihre Kriegsmaschinerie mit Energie versorgen.\n\nZhi der Harmonische hat uns gebeten, einige Kristalle zu sammeln und in die Stadt zurück zu bringen.\n\nHaltet Ausschau nach ihnen, während Ihr in den Ruinen unterwegs seid.", sourceObjective = "Sammelt 7 Jubelitkristalle ein.", progress = "Habt Ihr die Kristalle gefunden?", completion = "Ja, damit lässt sich etwas anfangen.\n\nIch werde sie sofort in das Lager bringen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30637] = { id = 30637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Guo-Lai-Hallen", description = "Als Ihr die große Tür durchquert, vernehmt Ihr Geräusche aus dem Inneren.\n\nAnji hatte erwähnt, dass in dieser Gegend Späher der Mogu gesichtet wurden. Vielleicht sind sie bis in die Tiefen vor Euch eingedrungen.\n\nIhr seid alarmiert und entscheidet, die Sache näher zu untersuchen.", sourceObjective = "Untersucht die Anwesenheit der Mogu in den Guo-Lai-Hallen.", progress = "Was habt Ihr in den Hallen entdeckt?", completion = "Eure Instinkte haben Euch nicht getäuscht, {name}.\n\nIn längst vergangenen Zeiten befanden sich mächtige Schätze in den Guo-Lai-Hallen.\n\nWir müssen den Mogukriegsfürsten um jeden Preis davon abhalten, in die versiegelten Gruften einzudringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30638] = { id = 30638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Passage schaffen", description = "Die Lage ist ernst.\n\nKun und ich werden die Situation hier im Auge behalten, aber Ihr solltet Euch zur Goldenen Pagode begeben.\n\nAlso los, beeilt Euch!", sourceObjective = "Sprecht mit Leven Morgenklinge an der Goldenen Pagode im Tal der Ewigen Blüten.", completion = "Greift Eure Waffen, {name}! Ich dachte, wir würden mehr Zeit für die Vorbereitung der Verteidigung haben, aber die Mogu erweisen sich als ebenso tödliche wie intelligente Feinde.\n\nWir haben die Flüchtlinge und die Vorräte in die Stadt hinter uns geschafft.\n\nJetzt ist es unsere Pflicht, die Front zu verteidigen. Wir dürfen nicht zulassen, dass die Mogu auch nur einen einzigen Brückenkopf hier im Tal erobern.", sourceObjectiveStatus = "unverified-source-field" }
quests[30639] = { id = 30639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse von Guo-Lai", description = "Ich habe gerade Informationen von einer Wache erhalten, die bei den Guo-Lai-Ruinen stationiert ist, dass der Anführer der Shao-Tien in die Hallen eingedrungen ist und dabei zwei meiner Leute getötet hat. Sie haben etwas im Inneren vor und wir müssen sie aufhalten.\n\nHee Samtfuß ist ihnen bereits hinein gefolgt. Er sollte Euch am Eingang der westlichen Gemächer erwarten.\n\nSchnell, {name}. Mir gefällt der Gedanke nicht, dass die Mogu uns einen Schritt voraus sein könnten.", sourceObjective = "Trefft Hee Samtfuß in den Guo-Lai-Hallen und offenbart das Vorhaben der Mogu in der westlichen Kammer.", progress = "Worauf wartet Ihr noch? Findet Hee. Haltet die Shao-Tien auf!", completion = "Die Shao-Tien sind dabei beobachtet worden, wie sie mit hundert Jadestatuen die Hallen verlassen haben. Die Mogu verfügen nun über eine gewaltige Jadearmee, die sie gegen uns einsetzen können, und wir müssen noch immer herausfinden, was sie im Tal vorhaben. Wir sind alle in Gefahr.\n\nIch hatte Euch und Hee für tot gehalten. Gut, dass ich zumindest hier falsch lag. Ruht Euch aus, erholt Euch. Vor uns liegen noch viele Kämpfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[30640] = { id = 30640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegsspeer des Donnerkönigs", description = "Ich habe beunruhigende Nachrichten erhalten, {name}.\n\nDie Mogu planen, drei mächtige Artefakte aus dem Tal zu stehlen.\n\nWir müssen diese Artefakte sofort bergen und sicher vor ihnen verwahren.\n\nDas erste Artefakt ist der Kriegsspeer des Donnerkönigs.\n\nSeit dem Tod von Kaiser Lei Shen wird der Speer in einem uralten Schrein im Nordwesten verwahrt.\n\nBringt mir diesen Speer zurück.", sourceObjective = "Sichert den Kriegsspeer des Donnerkönigs.", progress = "Man sagt, dass die mächtigsten der uralten Mogu in der Lage waren, die Kräfte der Elemente zu beschwören.\n\nDer Donnerkönig selbst konnte die Kräfte des Blitzes auf seinen Speer übertragen.", completion = "Gut gemacht, {name} - auch wenn es mich fast körperlich schmerzt, diesen verfluchten Speer anschauen zu müssen.\n\nDiese grauenvolle Waffe hat Tausenden Unschuldigen das Leben genommen.\n\nSo lange ich lebe, werden die Mogu nie wieder in seinen Besitz kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30641] = { id = 30641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegshelm des Donnerkönigs", description = "Das zweite Artefakt ist der Kriegshelm des Donnerkönigs.\n\nDer Kaiser Lei Shen hat diesen Helm in jeder Schlacht getragen. Der Helm wurde so berühmt, dass die Feinde schon allein bei seinem Anblick geflohen sind.\n\nAls der Kaiser starb, wurde der Helm in die unterste Ebene der Guo-Lai-Hallen im Westen gebracht - bewacht von Tausenden Terrakotta-Soldaten.\n\nAuf diese Weise konnten sie zu ihrem Anführer aufschauen und ihm in den Tod folgen.", sourceObjective = "Sichert den Kriegshelm des Donnerkönigs.", progress = "Die Legende besagt, dass Lei Shen nur einen einzigen Feind fürchtete. Und schließlich war es der Tod, der ihn besiegte.", completion = "Ich danke Euch, {name}.\n\nWährend unsere Soldaten die Mogu auf dem Schlachtfeld bekämpfen, arbeite ich daran, ihnen den Glanz ihrer Legenden zu nehmen.\n\nSchon bald wird Lei Shen nicht mehr als ein Schatten im Lauf der Geschichte sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[30642] = { id = 30642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kriegsaxt des Donnerkönigs", description = "Das letzte Artefakt ist die Kriegsaxt des Donnerkönigs.\n\nLei Shen hat sich mit dem Speer in der einen und seiner Axt in der anderen Hand in die Schlachten gestürzt.\n\nMan sagt, dass er die Axt mit brutaler Genauigkeit werfen konnte und sie beim Aufprall auf das Ziel ein Geräusch wie einen Donnerschlag auslöste.\n\nNach seinem Tod wurde die Axt in einer Zeremonienkammer im Südwesten verwahrt.\n\nEs dürfte klar sein, dass sie nicht in die Hände der Mogu fallen darf.", sourceObjective = "Sichert die Kriegsaxt des Donnerkönigs.", progress = "Habt Ihr die Axt gefunden?", completion = "Eure Bescheidenheit ehrt Euch, {name}. Ich habe bereits gesehen, dass Ihr die Axt sichern konntet. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[30643] = { id = 30643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die bittere Botschaft der Mogu", description = "Der brutale Kampf gegen die Mogu dauert nun schon eine ganze Weile. Und keine Seite weicht zurück.\n\nWir werden unsere Position nicht ewig halten können. Wir müssen den Mogu einen entscheidenden Schlag versetzen, von dem sie sich nicht wieder erholen.\n\nGeht und sprecht mit Zhi dem Harmonischen im Stillen Sanktum. Ich möchte seine Meinung in dieser Angelegenheit erfahren.", sourceObjective = "Sprecht mit Zhi dem Harmonischen im Stillen Sanktum im Tal der Ewigen Blüten.", completion = "Zhi der Harmonische und die anderen Verteidiger wurden gnadenlos abgeschlachtet.\n\nIhr verspürt ohnmächtige Fassungslosigkeit, als Ihr realisiert, dass die Schätze des Donnerkönigs verloren sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[30644] = { id = 30644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tragische Entwicklungen", description = "Ihr solltet Euch besser umgehend bei der Goldenen Pagode melden.", sourceObjective = "Sprecht mit Sun Zartherz an der Goldenen Pagode im Tal der Ewigen Blüten.", completion = "Was?! Zhi der Harmonische... ist tot? Oh...\n\nIhr habt Euch angesichts der Umstände gut geschlagen. Ich bin mir sicher, dass ein weniger fähiger {class} diesen Mördern unterlegen gewesen wäre.\n\nDie Dinge geschehen... so schnell. Wir alle müssen auf der Hut bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[30645] = { id = 30645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Drei", description = "Das war's, {name}. Das ist das Ende.\n\nWenn wir die Mogu nicht aus dem Tal drängen können, werden sie die Artefakte ihrer uralten Macht erobern und mit ihrer Hilfe ganz Pandaria unterwerfen.\n\nAber unsere Streitmacht ist klein und die Kämpfer sind müde. Wir bluten, aber ihre Krieger sind aus Stein.\n\n{name}, unsere Siegchancen sind äußerst gering, aber dennoch möchte ich Euch bitten, unseren Kämpfern zu helfen, die Mogu zurückzuschlagen.\n\nIch habe bereits zu den Himmlischen gebetet und um Hilfe gefleht. Ich hoffe nur, dass sie es auch vernommen haben.", sourceObjective = "Tötet 100 Mogueindringlinge auf den Sommerfeldern im Tal der Ewigen Blüten.", progress = "Ich kann von hier aus nicht viel von der Schlacht sehen. Wie läuft der Kampf?", completion = "Was? Wie viele Mogu habt Ihr getötet?\n\nDas ist wirklich bemerkenswert! Wenn wir das überleben sollten, müsst Ihr mir alles erzählen, was geschehen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[30646] = { id = 30646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Gefecht", description = "Ich hätte nie gedacht, dass es so weit kommen würde!\n\nLeven hat sich dem Kriegsfürsten Zhao-Jin, dem Blutvergießer, auf dem oberen Abschnitt der Palasttreppe zum Kampf gestellt, aber unsere Verstärkungen kommen nicht durch!\n\nWir sind die einzigen, die zwischen ihm und den größten... und tödlichsten... Mächten des Tales stehen.\n\nBitte, {name}, Ihr müsst einen Weg finden, ihn aufzuhalten!", sourceObjective = "Tötet den Kriegsfürsten Zhao-Jin den Blutvergießer.", completion = "Was Ihr heute erreicht habt, wird noch lange Zeit in den Geschichten fortleben.\n\nDank Eurer Hilfe konnten wir das Tal vor einem schrecklichen Feind beschützen.\n\nHeute haben wir den Mogu einen schmerzhaften Schlag verpasst. Ihre Versuche, das Tal zu erobern, werden nie aufhören. Aber es wird lange dauern, bis sie wieder einen groß angelegten Angriff starten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[30648] = { id = 30648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es geht voran", description = "Eure Reise in dieses Land hat sich bereits als sehr ereignisreich erwiesen, <Reisender/Reisende>. Und die meine, so scheint es, ist bestimmt, noch ein wenig weiterzugehen.\n\nEine Kette von Ereignissen wurde in Gang gesetzt, als die Euren hier ankamen und auch wenn einige von ihnen traumatisch wirken, so fühle ich doch, dass es einen größeren Sinn hinter Eurer Anwesenheit geben muss.\n\nFür den Moment ist es am weisesten, wenn Ihr diesen Ort verlasst und Pandaria weiter erforscht.\n\nSprecht mich an, wenn Ihr bereit seid, weiterzuziehen.", sourceObjective = "Sprecht mit Fei und reist ins Tal der Vier Winde.", sourceObjectiveStatus = "unverified-source-field" }
quests[30649] = { id = 30649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schrein der Zwei Monde", description = "Schaut Euch diese Kreatur an. Direkt als wir ankamen, hat uns der Moguattentäter ohne jede Vorwarnung angegriffen.\n\nSein Klingenstreich galt dem Anführer des Goldenen Lotus. Es war ein sehr glücklicher Umstand, dass wir hier waren und den Angriff vereiteln konnten.\n\nNach diesem Angriff auf Zhi fürchte ich auch um die Leben derer, die das Tal bereits betreten haben.\n\nDie Verwalter bringen Eure Leute in der Stadt im Südosten unter. Geht und sprecht mit den Anführern. Sorgt für ihre Sicherheit.", sourceObjective = "Sprecht mit Jaluu dem Spendablen, Mokimo dem Starken, dem Ältesten Liao und Madame Vee Luo im Tal der Ewigen Blüten.", progress = "Die Städte erwachen zu neuem Leben.", completion = "Gute Arbeit, {name}. Die Stadt sollte jetzt sicher sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[30650] = { id = 30650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene Pandaren", description = "Seht, ich weiß ja, dass die Allianz Rekruten braucht und momentan nicht genug von uns in dieser Stadt sind, um sie kampfbereit zu machen.\n\nIch weiß aber, dass die Yaungol drüben im Streitlager Ordo im Nordwesten viele meiner Leute gefangen halten. Und ich weiß auch, dass sie höchstwahrscheinlich dazu bereit wären, sich der Allianz anzuschließen, wenn Ihr sie befreien könntet.\n\nWas meint Ihr, {name}?", sourceObjective = "Befreit 8 Pandarengefangene.", completion = "Das war wirklich heldenhaft, {name}.\n\nIch war mir wirklich nicht sicher, ob wir bei einem Kampf hier draußen eine Chance gehabt hätten, wisst Ihr?\n\nDiese Leute mögen vielleicht noch etwas ungehobelt sein, aber wir werden sie schon in Form bringen. Und wenn wir damit fertig sind, haben wir eine echte Chance, wenn es darum geht, uns hier am Kun-Lai zu behaupten.\n\nGute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[30651] = { id = 30651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fässerweise Spaß", description = "Ach, jetzt wollen wir erst einmal etwas Spaß haben, <mein Junge/Mädchen>!\n\nDiese Ordo-Yaungol im Nordwesten haben uns die Arbeit abgenommen, Bomben zu bauen. Sie haben sie nämlich schon dort.\n\nAlso, nehmen wir doch die Einladung an und zerstören ihre Ölförderpumpen mit ihren eigenen Sprengstofffässern. Was meint Ihr?", sourceObjective = "Verwendet die Sprengstofffässer im Streitlager Ordo, um die westlichen, südlichen und östlichen Bohrtürme zu zerstören.", completion = "Ah, was für ein schöner Anblick das war. Ich hätte doch besser mit Euch dort hochgehen sollen, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[30652] = { id = 30652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meditationen im Zelt", description = "Die Yaungol des Streitlagers Ordo sind eine echte Bedrohung. Ich möchte, dass Ihr Euch nach Nordwesten begebt und ihren Anführer ausschaltet.\n\nLeider halten uns seine vier Untergebenen mit einer Feuerbarriere davon ab, ihn in der angrenzenden Höhle zu stellen.\n\nErledigt sie, um diesen Schutzschild auszuschalten. Ihr findet sie in den Zelten mit ihren Ritualen beschäftigt.", sourceObjective = "Tötet den Glutrufer, den Pyromanten, den Feuersprecher und den Flammenwirker von Ordo.", sourceObjectiveStatus = "unverified-source-field" }
quests[30653] = { id = 30653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Bierchen in Ehren", description = "Ich hab' nachgedacht.\n\nWir haben ja das ganze Bier, das Chen gebraut hat, und die vielen Leute, die Ihr zusammengetrommelt habt. Wir sollten die beiden zusammenbringen.\n\nDa sind Leute auf den Feldern, die ihr Leben für Pandaria riskieren. Wir beide sollten denen zumindest ein, zwei Fässchen vorbeibringen.\n\nDann können sie mit ihren Krügen auf den Sieg anstoßen. Oder sie haben sich ein letztes Bierchen hinter die Binde gekippt, bevor sie von einem Mantis niedergemetzelt werden. Wie auch immer - ich will nicht, dass sie ohne ein gutes Bierchen im Bauch in den Kampf ziehen.", sourceObjective = "Bringt etwas Bier zu den Wächtern von Zhu, den Priestern der Kranichschwingen, den Shado-Pan und den Taurensiedlern.", sourceObjectiveStatus = "unverified-source-field" }
quests[30654] = { id = 30654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Guo-Lai-Hallen", description = "Die Mogu haben irgendetwas vor. Das spüre ich.\n\nSie haben Späher in die Guo-Lai-Hallen entsandt.\n\nDie Verwalter haben gesagt, dass in den Tiefen uralte Schätze der alten Kaiser lagern. Es sind nicht nur sehr wertvolle, sondern auch sehr mächtige Artefakte.\n\nWir müssen die Mogu davon abhalten, sich diese Schätze anzueignen! Geht über die Rampe im Nordwesten herunter und haltet sie auf!", sourceObjective = "Untersucht die Anwesenheit der Mogu in den Guo-Lai-Hallen.", completion = "Ihr habt offensichtlich eine große Katastrophe verhindert, {name}.\n\nWenn dieser Mogukriegsfürst auf die Schätze in den Guo-Lai-Hallen aus ist, müssen wir ihn um jeden Preis aufhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[30655] = { id = 30655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pandarengefangene", description = "Seht, ich weiß ja, dass die Horde Rekruten braucht und momentan nicht genug von uns in dieser Stadt sind, um sie kampfbereit zu machen.\n\nIch weiß aber, dass die Yaungol drüben im Streitlager Ordo im Westen viele meiner Leute gefangen halten. Und ich weiß auch, dass sie höchstwahrscheinlich dazu bereit wären, sich der Horde anzuschließen, wenn Ihr sie befreien könntet.\n\nWas meint Ihr, {name}?", sourceObjective = "Befreit 8 Pandarengefangene.", completion = "Nun, wie es aussieht, haben wir eine kleine Armee beisammen - dank Euch.\n\nSie mögen zwar noch nicht besonders beeindruckend aussehen, aber mit ein wenig Hordendisziplin bekommen wir sie im Handumdrehen in Kampfform.\n\nÜbrigens, {name}... gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[30656] = { id = 30656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fässerweise Spaß", description = "Ich liebe es, Sachen in die Luft zu jagen! Das liegt mir im Blut!\n\nBei den Yaungol im Streitlager Ordo im Westen liegen tonnenweise Sprengstofffässer herum.\n\nIch schlage vor, dass wir sie dazu verwenden, ihre Ölförderpumpen hochzujagen und gleichzeitig jede Menge Spaß zu haben!", sourceObjective = "Verwendet die Sprengstofffässer im Streitlager Ordo, um die östlichen, südlichen und westlichen Bohrtürme zu zerstören.", completion = "Das war doch ein Riesenspaß, oder, {name}? Ich hätte mit Euch zusammen da rüber gehen sollen!", sourceObjectiveStatus = "unverified-source-field" }
quests[30657] = { id = 30657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konzeltration!", description = "Die Yaungol des Streitlagers Ordo sind momentan unsere größte Bedrohung. Ich möchte, dass Ihr Euch nach Westen begebt und ihren Anführer ausschaltet.\n\nDer Feigling versteckt sich in einer Höhle, die von seinen vier Untergebenen mit einer Feuerbarriere beschützt wird.\n\nErledigt sie, um diesen Schutzschild auszuschalten. Ihr findet sie in den Zelten, wo sie mit ihren Ritualen beschäftigt sind.", sourceObjective = "Tötet den Glutrufer, den Pyromanten, den Feuersprecher und den Flammenwirker von Ordo.", sourceObjectiveStatus = "unverified-source-field" }
quests[30658] = { id = 30658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine ruhige Kugel schieben", description = "Habt Ihr schon vom stacheligen Kugelfisch gehört, {name}? Natürlich habt Ihr das nicht, Ihr seid ja neu hier!\n\nSie können in den Sarjuntiefen westlich von hier gefunden werden. Nehmt diesen Fischspeer und versucht, mir ein paar ihrer giftgetränkten Stacheln zu besorgen.", sourceObjective = "Benutzt den Fischspeer, um 5 stachelige Kugelfische in den Sarjuntiefen zu töten, und kehrt mit ihren Stacheln zurück.", progress = "Passt mit dem Speer auf, {name}.", completion = "Ahh, wie ich sehe, habt Ihr ein paar Stacheln dabei, {name}. Die machen sich sicher gut auf meinen Speerspitzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[30660] = { id = 30660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegshetzer von Ordo", description = "<Der Schutzschild ist ausgeschaltet. Zeit, in die Höhle einzudringen und den Kriegshetzer der Yaungol von Ordo zu erledigen!>", sourceObjective = "Tötet den Kriegshetzer von Ordo.", completion = "Ihr habt es geschafft, {name}! Ich stehe in Eurer Schuld!\n\nWieder einmal!", sourceObjectiveStatus = "unverified-source-field" }
quests[30661] = { id = 30661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegshetzer von Ordo", description = "<Der Schutzschild ist ausgeschaltet. Zeit, in die Höhle einzudringen und den Kriegshetzer von Ordo zu erledigen!>", sourceObjective = "Tötet den Kriegshetzer von Ordo.", completion = "Wieder einmal habt Ihr geschafft, was sonst niemand vermocht hätte.\n\nAber wer hätte daran zweifeln wollen?", sourceObjectiveStatus = "unverified-source-field" }
quests[30662] = { id = 30662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegshetzer von Ordo", description = "Ihr habt den Schutzschild im Streitlager Ordo ausgeschaltet. Begebt Euch erneut dorthin, bevor er wieder aktiv ist.\n\nZeit, in die Höhle einzudringen und den Häuptling zu erledigen!", sourceObjective = "Tötet den Kriegshetzer von Ordo.", sourceObjectiveStatus = "unverified-source-field" }
quests[30663] = { id = 30663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegshetzer von Ordo", description = "Ihr habt den Schutzschild in Streitlager Ordo ausgeschaltet. Begebt Euch erneut dorthin, bevor er wieder aktiv ist.\n\nZeit, in die Höhle einzudringen und den Kriegshetzer von Ordo zu erledigen!", sourceObjective = "Tötet den Kriegshetzer von Ordo.", sourceObjectiveStatus = "unverified-source-field" }
quests[30665] = { id = 30665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung des Shado-Pan-Refugiums", description = "Ich habe Verstärkung aus dem Shado-Pan-Kloster angefordert, aber noch nichts von ihnen gehört. Wir haben die Stadt bereits verloren.\n\nEin paar Dorfbewohner sind vielleicht noch da, aber wir sind hier festgenagelt.\n\nUns bleibt keine Zeit für Unterhaltung. Wenn Ihr kämpfen könnt, helft meinen Männern, diesen Turm zu verteidigen. Wenn nicht, geht, denn Ihr werdet hier nicht lange überleben.", sourceObjective = "Tötet 15 Sha-verseuchte Yaungol.", completion = "Ihr habt uns etwas Zeit zum Atmen verschafft. Wir dürfen nicht verzweifeln - stattdessen müssen wir handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[30666] = { id = 30666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plötzliche, unerwartete Krokiliskenaggressivität", description = "Normalerweise besteht mein Tag aus dem Fangen von Fischen, dann dem Essen von Fischen, gefolgt von einem Schläfchen. Beachtet, dass ich \"Kämpfen mit einem Krokilisken\" in der Liste der Aktivitäten nicht aufgeführt habe.\n\nIhr seht wie <ein geschickter/eine geschickte:c> {class} aus. Könnt Ihr ein paar dieser Krokilisken beseitigen, damit ich meine normale Routine wieder aufnehmen kann? Die Krokilisken bleiben normalerweise für sich allein, oben bei Kea-Krak, im Nordwesten.", sourceObjective = "Erschlagt 8 Todesrachenkrokilisken bei Kea-Krak.", progress = "Was bringt die Kroks dazu, so anzugreifen?", completion = "Gestern haben wir noch fröhlich gefischt. Heute haben die Kroks einfach angefangen... zu versuchen, uns zu fressen.\n\nSeltsam.", sourceObjectiveStatus = "unverified-source-field" }
quests[30667] = { id = 30667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besonderes Gefieder", description = "Als die Kroks angefangen haben, anzugreifen, haben sie ein paar der Loris auf der Insel im Nordwesten aus den Nestern aufgescheucht.\n\nIch kann diese Lorifedern gebrauchen, um ein paar besondere Köder zu fertigen, die mir gelegen kommen, falls und wenn ich aufhören kann, meine Brüder gegen diese Reptilien zu verteidigen.\n\nHabt Ihr Lust auf eine kleine Federnjagd?", sourceObjective = "Besorgt 6 smaragdfarbene Schwanzfedern, 6 purpurrote Schwanzfedern und 6 dunkle Schwanzfedern.", progress = "<Ein Schweißtropfen glitzert im Fell über Tonys Braue.>", completion = "Danke, {name}. Ihr habt meinen Tag gerettet. Ich hasse es immer, wenn eine solch vorzügliche Gelegenheit zum Federnsammeln ungenutzt verstreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[30668] = { id = 30668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein eigenes Floß", description = "<Jay späht in Richtung Kea-Krak.>\n\nHmm. Sie scheinen sich nicht zu... beruhigen. Wir werden etwas anderes probieren müssen.\n\nIhr werdet ein Floß brauchen. Besorgt Euch ein paar Holzbretter und etwas Seetang und bringt alles zu mir rüber. Ich werde etwas für Euch zusammenschustern.", sourceObjective = "Besorgt 4 Holzbretter und etwas zähen Seetang.", progress = "Ihr habt alles? Ich werde Euch Euer Floß bauen, aber ich brauche die Materialien.", completion = "<Geschickt knüpft Jay die Bretter zu einem überraschend seetauglich aussehenden Gefährt zusammen und lässt dies dann ins Wasser.>", sourceObjectiveStatus = "unverified-source-field" }
quests[30669] = { id = 30669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lehrensucherin auf dem See", description = "Euer Floß ist unten im Wasser. Fahrt damit in die Mitte des Sees. Dort solltet Ihr eine Frau namens Ana Wu vorfinden.\n\nWenn ich eine Frage habe, die ich selbst nicht beantworten kann, frage ich immer sie. Sie sollte uns sagen können, warum diese Krokilisken nicht aufhören, anzugreifen.", sourceObjective = "Steigt auf Euer Floß und schildert der weisen Ana Wu in der Mitte der Nayelilagune das Problem.", completion = "Ihr wirkt beunruhigt, mein Kind.\n\nWie kann ich Euch als Lehrensucherin dienen? Was sucht Ihr zu erfahren?", sourceObjectiveStatus = "unverified-source-field" }
quests[30670] = { id = 30670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Disziplin!", description = "Unsere wahren Feinde sind nicht die Yaungol, sondern das Sha.\n\nEs ist die reine Manifestation von Emotionen. Und sehr zerstörerisch. Aber auch sehr undiszipliniert. Und undisziplinierte Macht muss scheitern. Wenn eine Flut geteilt wird, verliert sie ihre Macht. Und Buschbrände verbrennen ihren eigenen Treibstoff.\n\nUnd mit Disziplin und Weisheit lassen sich seine zerstörerischen Energien gegen es selbst wenden.\n\nBringt mir die Essenzen des Sha im Dorf - dann werde ich Euch mehr erklären.", sourceObjective = "Sammelt 5 Essenzen der blinden Wut von Exemplaren blinder Wut im Feuerzweigwinkel ein.", progress = "Habt Ihr die Essenzen sammeln können?", completion = "Sehr gut. Und jetzt werdet Ihr sehen, wie sich ungezügelter Zorn besiegen lässt.\n\nMithilfe dieser Essenzen werde ich Kobai, dem Anführer der Yaungol, eine Falle stellen. Aber auch wenn er dabei gefangen wird, ist er nicht unser Hauptziel...", sourceObjectiveStatus = "unverified-source-field" }
quests[30671] = { id = 30671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weisheit hat ihren Preis", description = "<Ana hört sich Eure Geschichte an und nickt.>\n\nKrokilisken greifen an? Ich kenne eine Geschichte darüber. Und ich werde sie mit Euch teilen, aber zuvor... Ich werde hungrig.\n\nHaifleisch sollte dagegen helfen. Ihr solltet genügend Haie im Wasser unter uns finden.", sourceObjective = "Besorgt 5 Haifilets.", progress = "Ich habe großen Hunger, {race}. Ich befinde mich nun mehrere Tage in dieser Lagune - ohne Nahrung.", completion = "Ihr habt mir mehr Fleisch gebracht, als ich jemals essen könnte!\n\nIch denke, ich schulde Euch jetzt eine Geschichte...", sourceObjectiveStatus = "unverified-source-field" }
quests[30672] = { id = 30672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gleichgewicht", description = "Die Geschichte nahm kein gutes Ende. Es gibt keine Narsong-Krokilisken mehr.\n\nDiesmal habt Ihr jedoch vielleicht eine Chance, das Ende zu beeinflussen.\n\nDie Ho-zen im Süden überfischen diese Gewässer. Ohne Fisch hungern die Krokilisken und sind daher verzweifelt - und greifen Marista an.\n\nGeht jetzt, {race}! Haltet die Ho-zen davon ab, so rücksichtslos zu fischen!", sourceObjective = "Erschlagt 10 Ungafischholer.", completion = "<Jay hört sich Euren Bericht über die Geschehnisse des Tages an.>\n\nVerstehe. Wir werden die Unga von hier aus im Auge behalten. Und wir werden unser Bestes geben, damit auch wir diese Gewässer nicht überfischen. Zweifellos sind auch wir ein Teil des Problems.\n\nBis zum nächsten Mal, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30673] = { id = 30673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Versteck", description = "Den Geistern des Himmels sei Dank, dass Ihr da seid, {class}! Ich weiß nicht, ob ich noch viel länger durchgehalten hätte.\n\nAber es gibt ganz sicher noch andere Überlebende in Feuerzweigwinkel. Würdet Ihr uns helfen, sie zu retten und sie in die Sicherheit des Shado-Pan-Refugiums zu führen?", sourceObjective = "Rettet Jin Warmfass, Ya Feuerzweig, die alte Dame Fung und Sya Zhong.", sourceObjectiveStatus = "unverified-source-field" }
quests[30674] = { id = 30674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewaltloses Gleichgewicht", description = "Einige der Fische, die die Unga-Ho-zen gesammelt haben, scheinen noch nicht tot zu sein. Es ist vielleicht noch Zeit, sie zurück ins Wasser zu werfen.", sourceObjective = "Werft 6 Zappelnde Karpfen in die Nayelilagune.", sourceObjectiveStatus = "unverified-source-field" }
quests[30675] = { id = 30675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergrabener Schatz der Ho-zen", description = "Die Karte in Euren Händen ist zerknittert, schmutzig und schlecht gezeichnet, aber Ihr könnt ein großes X am Strand sehen.\n\nGibt es irgendwo auf dieser Insel einen vergrabenen Schatz?", sourceObjective = "Sucht den vergrabenen Schatz der Ho-zen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30677] = { id = 30677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taxi" }
quests[30678] = { id = 30678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Bombenidee", description = "Diese Rochen sind wohl doch nicht so leicht zu fangen, wie ich dachte! Ihr scheint ja ziemlich schlau zu sein. Vielleicht könnt Ihr mir helfen?\n\nIch habe zwar Bomben gebaut, habe jedoch Schwierigkeiten mit dem Floß wegen meines verletzten Beins. Die Rochen findet man häufig in den seichten Gewässern westlich von hier. Nehmt diese Bomben und mein Floß und beschafft mir ihre Stacheln!\n\nAch ja, passt auf die Hammerhaie auf!", sourceObjective = "Setzt die Goblinangelbomben ein, um 3 Rochen zu töten und bringt ihre Stacheln zu Fiznix. Ihr findet die Rochen an der seichten Stelle westlich von der Anlegestelle der Angler.", progress = "Habt Ihr Rochen an der seichten Stelle gefunden?", completion = "Offensichtlich seid Ihr sehr geschickt mit diesen Bomben!", sourceObjectiveStatus = "unverified-source-field" }
quests[30680] = { id = 30680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Versteck", description = "Oh, danke. Ich danke Euch vielmals. Wenn Ihr nicht gekommen wäret, dann...\n\nAber Moment! Im Winkel muss es noch mehr Überlebende wie mich geben!\n\nIch bitte Euch, {class}: Rettet auch die anderen und bringt uns in Sicherheit im Shado-Pan-Refugium.", sourceObjective = "Rettet Jin Warmfass, Ya Feuerzweig, die alte Dame Fung und Sya Zhong.", sourceObjectiveStatus = "unverified-source-field" }
quests[30681] = { id = 30681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Versteck", description = "Oh, ich danke Euch! Ich hätte es niemals ganz allein zurück geschafft.\n\nAber ich glaube, es müsste noch andere Überlebende in Feuerzweigwinkel geben, die gerettet werden müssen. Sollen wir sie gemeinsam suchen und in die Sicherheit des Shado-Pan-Refugiums bringen?", sourceObjective = "Rettet Jin Warmfass, Ya Feuerzweig, die alte Dame Fung und Sya Zhong.", sourceObjectiveStatus = "unverified-source-field" }
quests[30682] = { id = 30682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Versteck", description = "Was für ein Glück, dass Ihr bis hierhin durchdringen konntet!\n\nIch weiß nicht, wie lange ich mich hier noch hätte verstecken können.\n\nAber ich bin mir sicher, dass es noch andere Überlebende gibt. {class}, wir müssen sie retten! Und dann können wir sie ins Shado-Pan-Refugium bringen. Die Meister dort werden wissen, was zu tun ist!", sourceObjective = "Rettet Jin Warmfass, Ya Feuerzweig, die alte Dame Fung und Sya Zhong.", progress = "Da draußen gibt es Überlebende? Dann gibt es sicher noch mehr, oder, {name}?", completion = "Wir wussten nicht, dass es da draußen Überlebende gab.\n\nDanke, dass Ihr sie in Sicherheit gebracht habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30683] = { id = 30683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des einen Reisenden Pech...", description = "Musstet Ihr ihnen unserer Vorräte an den Kopf werfen?! Warum nicht Eure Waffe? Vielleicht ein paar raffinierte Zauber oder Tritte? Warum die Vorräte?!\n\nJetzt haben wir nicht mehr genug, um über die Runden zu kommen, zumal Neffe Krummnagel hier ist. Sein Appetit kommt dem eines Yetis gleich!\n\nIhr habt sie geworfen, Ihr holt uns mehr. Den Weg hinunter befindet sich ein Wrack. Vielleicht findet Ihr dort Vorräte.", sourceObjective = "Durchsucht das verlassene Wrack nach Vorräten.", progress = "Neffe Krummnagel hat sich bereits die Nahrung für zwei Tage einverleibt. Ich hoffe, Ihr habt mehr gefunden!", completion = "Die Mogu haben Euch angegriffen? Das klingt furchtbar!\n\nIch frage ja nicht gern, aber habt Ihr Vorräte für uns gefunden, als Ihr um Euer Leben gekämpft habt?\n\nNein?! Das ist sehr großes Pech.", sourceObjectiveStatus = "unverified-source-field" }
quests[30684] = { id = 30684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Unwissenden", description = "Ich bin mir ziemlich sicher, dass Euer Pandaren-Freund eine Ahnung hat, wonach die Mogu eigentlich suchen.\n\nEr hat sich vor ein paar Tagen ohne Bergführer ins Gebirge aufgemacht und gesagt, dass nur Ihr ihm folgen sollt. Er hatte sich sehr klar ausgedrückt:\n\n\"<Der/Die:c> {class} muss diesen Pfad allein beschreiten, vollkommen konzentriert auf <seine/ihre> eigenen Gedanken. <Er/Sie> soll jedem Schrein die Ehre erweisen, bevor wir uns am Gipfel wiedersehen.\"\n\nDer Pfad beginnt gleich nordwestlich des Lagers und ist durch Flaggen gekennzeichnet. Aber passt gut auf Euch auf! Der Pfad des Unwissenden ist selbst an den harmlosesten Tagen noch gefährlich.", sourceObjective = "Bewältigt den Pfad des Unwissenden, um Euch mit dem Lehrensucher Cho zu treffen. Macht an allen Schreinen entlang des Weges Halt, um Euch dort auf Eure Gedanken zu konzentrieren.", progress = "Es gibt zwei Schreine auf dem Pfad unter uns und noch einen gleich hinter uns.", completion = "Ah, Ihr habt es geschafft und den Schreinen Ehre erwiesen.\n\nIch wusste, dass Ihr dazu fähig sein würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[30690] = { id = 30690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demaskierung der Yaungol", description = "Kobai Khan einfach zu töten, wird zu nichts führen, da er von besonders mächtigem und zerstörerischem Sha besessen ist - der bösartigen Wut.\n\nIhr werdet die Falle verwenden, die ich aus den Essenzen der blendenden Wut hergestellt habe, die Ihr gebracht habt. Lockt ihn in die Falle und stehlt dann seine Maske. Sobald Ihr sie aufgesetzt habt, erscheint Euch die bösartige Wut und versucht, Kontrolle über Euch zu erlangen.\n\nBesiegt sie und wir werden diese tragische Situation in einen Sieg verwandelt haben. Ihr findet sie nördlich des Refugiums, wo sie uns mit wahnsinnigem Zorn foltert.", sourceObjective = "Lockt Kobai in die Falle der blendenden Wut, stehlt ihm die Maske der bösartigen Wut und besiegt dann die bösartige Wut.", progress = "Ist die bösartige Wut verschwunden?", completion = "Ich sollte über den Verlust des Dorfs Scham empfinden. Ich sollte angesichts Eures Erfolgs großen Stolz empfinden.\n\nIch sollte viele Dinge empfinden, aber ich darf es mir nicht erlauben. Wir müssen die vollständige Kontrolle über unsere Emotionen behalten, bis unser Ringen mit dem Sha beendet ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[30691] = { id = 30691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elend", description = "Wenn Ihr schon unten im Wasser seid, solltet Ihr Nahassa, den Patriarchen der Todesrachen, erschlagen. Er leidet. Ich kann seine Todesschreie bis an die Oberfläche der Lagune fühlen.\n\nSucht seine Höhle und erlöst ihn von seinem Elend. Das hat nichts mit Maristas Krokiliskenproblem zu tun. Macht es einfach aus Gnade.", sourceObjective = "Erlöst Nahassa von seinem Elend.", completion = "Nahassas fiebriges Leiden hat ein Ende gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[30692] = { id = 30692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Jutepfad: Zum Basislager am Kota", description = "Wir sind im Land der Ho-zen. Sehr gefährlich. Aber Grummel müssen hier durch. Schlangenrücken muss versorgt werden.\n\nGeht und beschützt die nächste Gruppe Grummel auf ihrer Reise zum Basislager am Kota.\n\nWenn auch nur einer überlebt, wird das Glück Euch bald finden.", sourceObjective = "Beschützt eine Gruppe Grummel auf dem Weg von der Zwischenstation des Jutepfads zum Basislager am Kota. Mindestens ein Grummel muss überleben.\n\nWenn Ihr die Grummel verliert, könnt Ihr den Jutepfad absuchen oder zur Zwischenstation des Jutepfads zurückkehren und warten, bis die nächste Gruppe aufbricht.", progress = "Willkommen in der Zwischenstation des Jutepfads, Freund der Grummel.", completion = "Ha ha! Held der Grummel. Willkommen im Basislager am Kota. Genießt Euer Glück für gute Ablieferung von Grummel.", sourceObjectiveStatus = "unverified-source-field" }
quests[30694] = { id = 30694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit leichtem Schritt", description = "Meine Schüler haben mir erzählt, dass die Umgebung mit tödlichen Fallen verseucht ist, die zweifellos von den Saurok aufgestellt wurden. Stolpert man in eine dieser Fallen, hat man das Gesicht voller Stacheln.\n\nWie das Sprichwort sagt: \"Ist der Weg voller Gefahren - geht mit leichtem Schritt und lasst Obacht walten.\"\n\n<Koro gibt Euch einen langen Ast.>\n\nHier, das ist Obacht.\n\nSie sollte lang genug sein, um die Fallen aus sicherer Entfernung auslösen zu können.", sourceObjective = "Lasst \"Obacht\" walten, um 10 Stachelfallen der Flussklingen aus sicherer Entfernung auszulösen.", completion = "Jede Falle, die Ihr ausgelöst habt, steht für ein gerettetes Leben, ob von Pandaren, Bestien oder anderen. Niemand verdient einen ehrlosen Tod wie diesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30695] = { id = 30695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Weg", description = "Riesige Schlunde der Verzweiflung speien Sha aus den Pagoden zu beiden Seiten des Tempels aus. In der Zwischenzeit geht Eure improvisierte Ausbildung im Weg des Kranichs weiter.\n\n\"Diejenigen, die zerrissene Regenschirme reparieren, bleiben trockener als diejenigen, die auf Regen einschlagen.\"\n\nObwohl ich Einwände gegen diese spezielle Lektion erhebe - manchmal können Schläge gegen den Regen recht effektiv sein - bleibt die Bedeutung in diesem Fall wahr.\n\nSchaltet diese Schlunde der Verzweiflung aus und verschafft meinem Orden eine Chance, das Tempelgelände zurückzuerobern.", sourceObjective = "Tötet die Schlunde der Verzweiflung in der östlichen und auch der westlichen Pagode des Tempels des Roten Kranichs.", progress = "Koro berichtete über eine Pagode auf jeder Seite des Tempels. Suchen wir sie und löschen wir die Sha-Präsenz in beiden aus.", completion = "Koros Metaphern können ein wenig ermüdend werden, aber es ist fürwahr stets Weisheit in ihnen verborgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30698] = { id = 30698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederverwertung", description = "IHR DA! Nach jemandem wie Euch habe ich gesucht!\n\nIch brauche weitere Teile für meine Goblinangelbomben, aber ich habe mir das Bein verletzt und kann sie nicht selbst besorgen.\n\nSeht Ihr diese Schiffswracks in der Nähe? Ich wette, dort gibt es genau das, was ich brauche, wenn Ihr nur dorthin kommen und es rausfischen könnt. Nehmt mein Angelfloß und schaut, was Ihr finden könnt! Mein Kumpel hat auch versucht, mir zu helfen, es kann also sein, dass Ihr weitere Flöße in der Nähe des Wracks findet - die könnt Ihr auch gerne benutzen.", sourceObjective = "Nehmt das goblinische Angelfloß und fischt 15 verrostete Schiffswrackteile aus den treibenden Trümmern in der Nähe der Wracks.", progress = "Habt Ihr die Schiffswracks gefunden?", completion = "Da habt Ihr wohl eine Menge Teile gefunden. Eine neue Ladung Angelbomben kommt sofort! Danke, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[30699] = { id = 30699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Winterblüte", description = "Der Kampf gegen das Sha hört niemals auf – wir können diesen Ort nicht verlassen.\n\nAber ich mache mir Sorgen über das Ausbleiben von Verstärkung aus dem Kloster, nachdem wir doch schon vor Tagen darum gebeten haben.\n\nIhr habt Bewundernswertes geleistet, vielleicht könntet Ihr nach Winterblüte reisen. So heißt unser Basislager auf dem Weg zum Shado-Pan-Kloster. Sprecht dort mit Lin Stillstoß – er wird wissen, was vor sich geht. Um dorthin zu gelangen, müsst Ihr vom Dorf aus nach Norden reisen und der Straße durch das Shado-Li-Becken nach Winterblüte folgen.", sourceObjective = "Sprecht mit Lin Stillstoß in Winterblüte am Kun-Lai-Gipfel.", completion = "Shado-Meister Chong hat Euch also geschickt?\n\nJa, wir haben seine Bitte um Verstärkung erhalten.\n\nWir können aber keine schicken. Wir haben selbst gerade erst einen Kampf überstanden, und das Kloster ist vollkommen abgeriegelt.\n\nNicht einmal wir können Verstärkung bekommen, dabei liegen wir direkt unten am Hügel!", sourceObjectiveStatus = "unverified-source-field" }
quests[30700] = { id = 30700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnappklaue", description = "Eine gigantische, giftige Krabbe macht sich über die hiesigen Seeohrbestände her. Ihr müsst Euch für mich in den Narsonggraben begeben und sie ausschalten!", sourceObjective = "Tötet Schnappklaue in einer Höhle am Grund des Narsonggrabens und kehrt mit seiner Klaue als Beweis zurück.", progress = "Habt Ihr diesen lästigen Krabbler ausgeschaltet?", completion = "Das ist ja mal eine Klaue. Schnappklaue muss größer gewesen sein, als ich gedacht habe! Aber egal, Ihr habt Eure Aufgabe gut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[30701] = { id = 30701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwingzangensuppe", description = "Nichts schmeckt so gut wie Zwingzangensuppe. Das ist eine Krasarangspezialität!\n\nIch wollte mir gerade eine machen, als ich bemerkte, dass eine Hauptzutat fehlt: die Augen!\n\nIhr müsst die Zwingzangenfischer am Strand für mich töten und mir ihre Augen für die Suppe bringen!", sourceObjective = "Tötet Zwingzangenfischer am Strand und kehrt mit 16 Augen für eine leckere Suppe zurück.", progress = "Wie viele ihrer wachsamen, kleinen Augen habt Ihr bekommen?", completion = "Danke, {class}, das könnte meine bisher beste Suppe werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[30704] = { id = 30704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ho-zen im Nebel" }
quests[30705] = { id = 30705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Logbuch des Kapitäns" }
quests[30706] = { id = 30706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verärgerte Kritzeleien" }
quests[30710] = { id = 30710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trolle provozieren", description = "Wir haben sie erst einmal zurückschlagen können, aber ich bezweifle, dass wir auf Sicherheit hoffen dürfen, solange wir sie nicht vernichtend geschlagen haben.\n\nMein Mann, man mag ihn einen Feigling oder Narren nennen, möchte sie angeblich nicht provozieren. Ich aber lasse mich nicht einschüchtern.\n\nUnd darum werden wir sie erst recht provozieren, indem wir ihre Späher töten. Vielleicht können wir so ihren Anführer herauslocken und sogar vernichten.", sourceObjective = "Tötet 10 Pirscher der Zandalari und 5 Hexer der Zandalari.", sourceObjectiveStatus = "unverified-source-field" }
quests[30714] = { id = 30714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Anführer vernichten", description = "Und jetzt fürchten sie Euch.\n\nIhre Anführer, ein Klingenmeister und ein Magier, befinden sich tiefer in den Ruinen. Tötet sie.\nFügt ihnen Schmerzen zu. Tut es für uns.", sourceObjective = "Tötet den Klingenmeister der Zandalari und den Magier der Zandalari.", sourceObjectiveStatus = "unverified-source-field" }
quests[30715] = { id = 30715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine ungebrochene Linie", description = "Als wir uns nach ihrem ersten Angriff neu formiert hatten, fehlten uns drei Mann. Ihr könnt kämpfen, und wir müssen unsere Verteidigung für den Fall planen, dass diese verfluchten Yaungol wieder angreifen.\n\nWenn Ihr uns helfen wollt, gewährt unseren gefallenen Kameraden ihre letzten Riten und bergt ihre Rüstungen. Ihr werdet ihre Körper im Westen finden, in der Nähe des Tors.\n\nUnd versucht, diese Aasfresser von ihnen fernzuhalten.", sourceObjective = "Bettet Shado-Meister Zhiyao, Liu Tausendschlag und Shiya Scharfklinge zur letzten Ruhe.", progress = "Unsere Kameraden... ruhen sie in Frieden?", completion = "Gut. Ich werde dafür sorgen, dass die Rüstungen ihren Schülern zukommen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[30716] = { id = 30716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hoffnung hinterher", description = "Chi-Ji ist immer bei uns. Auch wenn er nicht hier in der Wiege ist, rennen Teile seines Geistes durch die Wälder und über die Strände der Insel, beobachten und prüfen uns.\n\nBeweist Eure Gewandtheit in den Augen von Chi-Ji, {name}. Sucht und fangt die Geister des Kranichs.", sourceObjective = "Berührt 3 Geister des Kranichs.", completion = "Chi-Ji lächelt auf Euch herab.", sourceObjectiveStatus = "unverified-source-field" }
quests[30717] = { id = 30717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaben des Großen Kranichs", description = "Die Kraniche von Krasarang sind eine Gabe von Chi-Ji. Sogar die Federn, die sie zurücklassen, sind eine Gabe an uns, an der wir uns erfreuen.\n\nWir verwenden diese Federn, um unsere Kleidung zu schmücken und Pfeile zu befiedern. Aber zuerst... müssen sie eingesammelt werden.", sourceObjective = "Besorgt 10 Gaben des Großen Kranichs.", progress = "Auch die kleinste, schwächste Feder ist Beweis genug dafür, dass Chi-Ji uns liebt.", completion = "Danke, {name}.\n\nKommt bald wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[30718] = { id = 30718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schüler von Chi-Ji", description = "Unser Orden ist stolz auf seine Vortrefflichkeit im Kampf. Wir verbessern diese Kampffertigkeiten, indem wir uns hier in Chi-Jis Wiege duellieren.\n\nBeweist Euch in den Augen des Roten Kranichs. Begebt Euch nach Süden ins Zentrum der Insel und duelliert Euch mit Euren Mitschülern.", sourceObjective = "Duelliert Euch mit 10 Schülern von Chi-Ji.", completion = "Mit jedem Kampf - Sieg oder Niederlage - verbessert Ihr Euch. Ihr werdet schneller, kühner, schlauer... besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[30723] = { id = 30723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre, auch im Tod", description = "Hmm... Wenn Shado-Meister Chong Euch vertraut hat, könnt Ihr uns vielleicht auch helfen.\n\nDie Yaungol sind unsere Feinde.\n\nDennoch müssen wir unter Beweis stellen, dass wir besser sind als sie. Wir werden ihnen im Tode noch Ehre erweisen.\n\nWie nach den meisten Schlachten versammeln sich die Aasfresser. Verringert ihre Anzahl, damit die Leichen unserer Feinde nicht entweiht werden. Sie befinden sich auf dem Schlachtfeld im Westen.", sourceObjective = "Tötet 12 Kun-Lai-Leichenhacker.", completion = "Gut. Nach dem, was sie getan haben, würde ich lebenden Yaungol keine Freundlichkeit entgegenbringen. Allerdings werde ich aber auch nicht dulden, dass ihre Leichname von Vögeln gefressen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[30724] = { id = 30724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die Mauer!", description = "Sie greifen schon wieder an!\n\n<Lin blickt in Richtung des Ochsentors>\n\nBogenschützen... Auf die Mauer!\n\nIhr müsst Euch dort hoch begeben. Meine Frau Suna ist gerade mit diesem törichten Lao-Chen dorthin aufgebrochen, um die Lage auszukundschaften. Vielleicht hätte er mehr Zeit mit der Vorbereitung der Verteidigungen als dem Bau dieses idiotischen Bieraufzugs verbringen sollen...\n\nAber das ist jetzt auch egal. Besorgt Euch westlich von hier einen Drachen von Len, dann begebt Euch dort hoch und findet meine Frau. Sie wird wissen, was zu tun ist.", sourceObjective = "Sprecht mit Drachenmeister Len in Winterblüte am Kun-Lai-Gipfel, um einen Drachen hoch zum Ochsentor zu nehmen. Sprecht mit Suna Stillstoß, wenn Ihr dort angekommen seid.", completion = "Nicht schlecht... Ihr seid ein ziemlich talentierter Drachenflieger! Gut, dass Ihr es hier hoch geschafft habt, ohne zu sterben.\n\nIhr werdet hier auch dringend benötigt. Lao-Chen hat einen Plan, an dem er gerade arbeitet, aber mit diesen Yaungol werden wir wohl kaum allein fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[30725] = { id = 30725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ellia Rabenmähne", description = "Wir organisieren regelmäßig Duelle, einer gegen einen, mit Schülern, die unserer Meinung nach gut zusammenpassen. Wir haben eine solche Schülerin für Euch gefunden, {name}.\n\nIhr Name ist Ellia Rabenmähne. Das wird auch ihr erstes Duell sein. Sie erwartet Euch am Pavillon etwas südlich von hier.", sourceObjective = "Besiegt Ellia Rabenmähne beim Angkhalpavillon.", completion = "Sehr gut!\n\nDas nächste Mal, wenn Ihr zurückkehrt, werdet Ihr einem neuen Herausforderer gegenüberstehen. Gewinnt weiterhin, und Eure Gunst in den Augen von Chi-Ji wird steigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30726] = { id = 30726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minh Do-Tan", description = "Euer nächster Herausforderer ist ein weiterer, relativ neuer Schüler. Er heißt Minh Do-Tan und hat seine letzten beiden Kämpfe gewonnen.\n\nEr erwartet Euch in der Nähe der Kranichstatue im Süden.", sourceObjective = "Besiegt Minh Do-Tan.", completion = "Gut gemacht, {name}. Ihr fangt an, Euch einen Namen zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30727] = { id = 30727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und schon wieder Ellia Rabenmähne", description = "Ellia Rabenmähne hat einen erneuten Kampf verlangt. Sie scheint Euch für ihren \"Rivalen\" zu halten.\n\nWir versuchen hier in Chi-Jis Wiege, Rivalitäten zu vermeiden, aber selten lehnen wir eine Forderung nach einem weiteren Kampf ab. Ihr findet Ellia in der Nähe des Podests der Hoffnung auf der Ostseite der Insel.", sourceObjective = "Besiegt Ellia Rabenmähne in der Nähe des Podests der Hoffnung.", completion = "Zwei Kämpfe, zwei Niederlagen. Verständlicherweise wird Ellia in der nächsten Zeit wohl keine weiteren Wiederholungskämpfe fordern.", sourceObjectiveStatus = "unverified-source-field" }
quests[30728] = { id = 30728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fat Long-Fat", description = "Du wurdest einem... besonderen Schüler zugeteilt. Sein Name ist Fat Long-Fat.\n\n<Thelonius wählt seine Worte sorgfältig.>\n\nFat Long-Fat... operiert außerhalb der normalen Kampfregeln. Er kämpft nicht jeden Tag, und wenn er es tut, wählt er seinen Konkurrenten. Heute hat er aus irgendeinem Grund... Euch ausgewählt.\n\nIhr findet ihn auf dem Angkhalpavillon.", sourceObjective = "Besiegt Fat Long-Fat oben auf dem Angkhalpavillon.", completion = "Natürlich habt Ihr gewonnen. Fat Long-Fat kämpft nicht, um zu gewinnen. Er kämpft... aus anderen Gründen.\n\nIch befürchte, ich habe schon zu viel zu diesem Thema gesagt. Von jetzt an... keine weiteren Fragen zu Fat Long-Fat.", sourceObjectiveStatus = "unverified-source-field" }
quests[30729] = { id = 30729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Julia Bates", description = "Wir heißen jeden in der Wiege willkommen, solange er die Ideologie des Roten Kranichs anerkennt und sich ihr verpflichtet. Eine unserer neuen, exotischeren Schülerinnen stammt aus den Menschenkönigreichen im Nordosten. Sie hört auf den ziemlich fremd klingenden Namen Julia Bates.\n\nSie ist Eure nächste Herausforderin. Ihr findet sie an der Westküste der Insel.", sourceObjective = "Besiegt Julia Bates.", completion = "Noch einen Kampf gewandt gewonnen. Ich erwarte unruhig Euren nächsten Kampf, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30730] = { id = 30730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der geschickte Izissha", description = "Jinyu meiden normalerweise unseren Orden, aber alle paar Jahre finden wir einen, der sich dem Weg des Kranichs verschreibt. Ein solcher Jinyu ist der geschickte Izissha.\n\nIzissha ist Euer nächster Herausforderer. Er erwartet Euch an der Südwestküste der Insel.", sourceObjective = "Besiegt den geschickten Izissha.", completion = "Ausgezeichnete Arbeit, {name}! Ihr gewinnt weiter an Gunst in den Augen von Chi-Ji.\n\nAn Euren nächsten Kampf werdet Ihr Euch sicher lange erinnern. Ihr kämpft nicht gegen einen Schüler. Stattdessen werdet Ihr einem Eurer Lehrer gegenüberstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30731] = { id = 30731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kuo-Na Stachelpfote", description = "Die meisten Duelle in der Wiege finden zwischen zwei Schülern statt. Zeigt ein Schüler äußerst große Fertigkeit, erhält er eine Gelegenheit, sich mit einem Lehrer zu duellieren, was aber nur selten vorkommt.\n\nHeute kämpft Ihr in einem Duell gegen Kuo-Na. Sie erwartet Euch am Podest der Hoffnung.", sourceObjective = "Besiegt Kuo-Na Stachelpfote.", completion = "Ihr seid weiterhin beeindruckend, {name}.\n\nKommt bald wieder. Eure Ausbildung ist noch nicht beendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[30732] = { id = 30732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache der Ellia Rabenmähne", description = "Eure \"Rivalin\" ist wieder aufgetaucht. Ellia Rabenmähne hat ihre Pflichten auf der Insel vernachlässigt und sich stattdessen auf persönliches Training konzentriert. Sie hat vor, Euch im Kampf zu schlagen.\n\n\"Ich werde {name} vernichten\", hat sie gesagt.\n\nIch habe ihrer Forderung nach einem Wiederholungskampf nachgegeben, aber ich werde sie gut im Auge behalten. Ihre Motive könnten sich in eine gefährliche Richtung verschieben.", sourceObjective = "Besiegt Ellia Rabenmähne bei der Balrissakuppel.", completion = "Ich werde Chi-Ji sofort um Rat zu Ellias Verhalten bitten. Sie bewegt sich auf dünnem Eis.", sourceObjectiveStatus = "unverified-source-field" }
quests[30733] = { id = 30733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tukka-Tuk", description = "Ihr macht Euch einen Namen, {name}. Ich habe eine Herausforderung von einem unserer geschickteren Wettbewerber erhalten. Er meint, Ihr seid nicht so stark, wie Ihr scheint.\n\nEr heißt Tukka-Tuk, ein Ho-zen. Wenn Ihr irgendwann schon einmal gegen Ho-zen gekämpft habt, dann wisst Ihr, dass ihr Kampfgeist ihre offensichtliche Unreife Lügen straft. Viel Glück.", sourceObjective = "Besiegt Tukka-Tuk.", completion = "Gut gemacht, wie üblich.\n\nIch bin sicher, ich werde Euch bald wiedersehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30734] = { id = 30734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurt Karette", description = "Normalerweise handelt es sich bei unseren Schülern um Abenteurer wie Euch oder um Mönche aus dem Tiankloster oder gelegentlich um Shado-Pan im Ruhestand. Sehr selten jedoch begrüßen wir Schüler, die noch überhaupt keine Kampferfahrung haben.\n\nKurt Karette ist solch ein Schüler. Er hat ein Duell mit Euch gefordert. Sucht ihn an der Westküste der Insel.", sourceObjective = "Besiegt Kurt Karette.", completion = "Es bleibt nur noch ein Schüler, der im Rang über Euch steht.\n\nIch habe so ein Gefühl, dass Ihr ihm gegenüberstehen werdet, wenn Ihr zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30735] = { id = 30735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mindel Sonnensang", description = "Unser höchstrangiger Schüler ist ein Außenseiter wie Ihr. Es ist sowohl seltsam als auch aufregend, in einer Zeit zu leben, in der so viele Fremde sich entschließen, dem Weg des Kranichs zu folgen.\n\nEuer Herausforderer heißt Mindel Sonnensang und er erwartet Euch im Angkhalpavillon.", sourceObjective = "Besiegt Mindel Sonnensang.", sourceObjectiveStatus = "unverified-source-field" }
quests[30736] = { id = 30736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yan Stachelpfote", description = "Ihr habt Kuo-Na Stachelpfote bereits besiegt. Aber Ihr seid noch nicht gegen ihren Bruder Yan angetreten.\n\nEr trifft sich mit Euch am Podest der Hoffnung, und er wird sich nicht zurückhalten. Sein Ruf als Lehrer steht auf dem Spiel.", sourceObjective = "Besiegt Yan Stachelpfote am Podest der Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[30737] = { id = 30737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und schon wieder Fat Long-Fat", description = "Fat Long-Fat hat einen weiteren Kampf mit Euch gefordert. Mir kommt das seltsam vor. Und besorgniserregend.\n\nEr erwartet Euch oben auf der Balrissakuppel.", sourceObjective = "Besiegt Fat Long-Fat oben auf der Balrissakuppel.", sourceObjectiveStatus = "unverified-source-field" }
quests[30738] = { id = 30738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thelonius", description = "Als wir uns das letzte Mal unterhalten haben, habe ich Euch versprochen, Euch das Geheimnis von Fat Long-Fat zu verraten. Ich habe immer noch vor, Euch dieses Geheimnis zu verraten... nachdem ich Euren Wert festgestellt habe.\n\nTrefft Euch mit mir an der Westküste, dann werden wir uns duellieren.", sourceObjective = "Besiegt Thelonius.", sourceObjectiveStatus = "unverified-source-field" }
quests[30739] = { id = 30739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ellia Rabenmähne: Erlösung", description = "Ellia Rabenmähne, Eure Rivalin, ist zurückgekehrt. Sie verlangt, dass Ihr Euch mit ihr oben auf dem Podest der Hoffnung trefft.\n\nIhr müsst verstehen, {name}... Ihr ist etwas Schreckliches zugestoßen. Sie hat sich verändert. Ihr werdet es selbst sehen, wenn Ihr am Podest ankommt.\n\nViel Glück, {name}.", sourceObjective = "Besiegt Ellia Rabenmähne oben auf dem Podest der Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[30740] = { id = 30740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion von Chi-Ji", description = "Euch wird immer ein Ehrenplatz in unserem Orden gebühren, trotzdem seid Ihr immer noch willkommen, an unseren Duellen teilzunehmen.\n\nEiner unserer aktuellen Champions erwartet Euch in der Balrissakuppel. Ich weiß, dass sie sich geehrt fühlen würden, wenn Ihr mit ihnen duellieren würdet.", sourceObjective = "Besiegt einen Champion von Chi-Ji.", sourceObjectiveStatus = "unverified-source-field" }
quests[30742] = { id = 30742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Rausch der Zägen", description = "Hab's vermusselt.\n\nSamen aus Kafa-Beeren zu schneiden, ist harte Arbeit! Hab' aber gesehen, wie Zägen die Beeren essen und die Samen sauber wieder zurückgeben. Nach einem Tag oder so.\n\nHab' alles den Zägen auf der Kotaspitze gegeben. Jetzt sind Zägen verrückt! Greifen alles an, was sich bewegt.\n\nKota war sicheres Gebiet für Grummel zum Kafa-Sammeln. Nicht mehr. Nicht mit den Zägen. Werdet Ihr helfen?", sourceObjective = "Besiegt 12 Kafa-berauschte Bergziegen auf der Kotaspitze.", completion = "Danke Euch. Lasst Euch dies eine Lehre sein: Füttert nie die Zägen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30743] = { id = 30743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gourmet-Kafa", description = "War gute Idee. Kafa-Beeren in Zäge rein, kommen sauber wieder aus.\n\nKafa'kota ist schon selten und Vermögen wert, aber Erfindung von mir - Kafa'zäge - ist GOURMET.\n\nAber das jetzt vorbei. Onkel Kühnbohn ist aufgeregt und Gipfel ist nicht sicher. Jetzt nur noch eins zu tun: Den Rest von Kafa'zäge sammeln und es nie wieder machen.\n\nIch bitte Euch nicht, es einzusammeln - keine schöne Aufgabe, nichts für Helden - markiert es einfach, damit wir es leichter finden, wenn der Berg wieder sicher ist.", sourceObjective = "Markiert 10 Kafa'zäge-\"Vorkommen\" auf der Kotaspitze.", completion = "Gut. Ich gehe rauf und ernte. Bald.\n\n<Cousin Zägenfell fängt an, sich lange Leinenstreifen um die Hände zu wickeln.>\n\nKann nicht glauben, dass ich dachte, es wäre eine gute Idee.", sourceObjectiveStatus = "unverified-source-field" }
quests[30744] = { id = 30744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edle Kota-Mischung", description = "Kotaspitze ist berühmt für Kafa-Büsche. So weit oben kann nichts anderes wachsen.\n\nGrummel verdienen gutes Geld mit edle Kafa'kota-Mischung. Aber jetzt ist gefährlich. Schuld hat mein Vetter. Hat die Tiere da oben mit Kafa gefüttert und verrückt gemacht.\n\nKafa'kota seltener als je zuvor: Zägen fressen Kafa'kota auf. Yetis bringen Kafa'kota in ihre Höhlen.\n\nBringt mir Beeren runter. Ich zahle gut.", sourceObjective = "Sammelt 100 Kafa'kota-Beeren auf der Kotaspitze. Ihr findet sie in den Büschen in den Bergen oder in den Yeti-Höhlen aufgehäuft.", sourceObjectiveStatus = "unverified-source-field" }
quests[30745] = { id = 30745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger braut sich zusammen", description = "Eine Menge Yetis in Kota, jepp. Normalerweise nicht gefährlich. Normalerweise essen nur Zägen.\n\nDann gegessen Zägen gefüllt mit Kafa...\n\n<Kühnbohn schaut Zägenfell bedrohlich an.>\n\nJetzt sind launisch, stinkig, schlafen viel, aber sind nie ausgeruht. Typische Kafasüchtige.\n\nKommen bald aus den Höhlen, ich bin sicher. Kommen und suchen nach mehr Kafa.\n\nDann wir alle haben Ärger.", sourceObjective = "Tötet 5 Kafa-berauschte Yetis in den Höhlen der Kotaspitze.", completion = "Geschafft!\n\nYetis sind schon alleine hart - kann mir nicht vorstellen, wie ein stinkiger Kafa-süchtiger Yeti sein muss. Ihr seid mutig. Oder habt Glück. Oder seid dumm.\n\nVielleicht alles drei.", sourceObjectiveStatus = "unverified-source-field" }
quests[30746] = { id = 30746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gerechter Handel", description = "<Das Gebrüll ertönt wieder, lauter und wilder, als alles, was Ihr bisher von Yetis gehört habt. Und wieder antwortet eine Grummelstimme...>\n\nIeep! Bitte, großer Kota Kon, vergebt Grummel. Lasst mich gehen, ich werde sofort eine Menge Kafa holen! Versprochen!\n\n<Die Bestie namens Kota Kon antwortet mit einem weiteren gehaltvollen Brüllen.>", sourceObjective = "Bringt das Bündel Kafa'kota-Beeren zum Versteck von Kota Kon in der Nähe des Gipfels der Kotaspitze.", progress = "Kota Kon will mehr Kafa, aber ich habe sie schon mit allem gefüttert, was ich habe! Dann habe ich es mit einer netten Verneigung probiert, aber sie ist nicht zufrieden!\n\n<Der erschreckte Grummel schluckt und lehnt sich für ein Flüstern zu Euch.>\n\nIch glaube, sie kann den Kafa riechen, den ich zum Frühstück getrunken habe...", completion = "Ihr habt Kafa mitgebracht?\n\nIhr...\n\nGroßartig...\n\nGlücksbringer...\n\nSchnell, geben wir ihn ihr! Vielleicht wird sie uns nicht als Imbiss fressen...", sourceObjectiveStatus = "unverified-source-field" }
quests[30747] = { id = 30747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Juteschleifer", description = "Na guuut... in Ordnung, sie hat niemanden gefressen. Das ist ein guter Anfang.\n\nSie will sicher mehr Kafa, aber wir müssen ihr bei der ganzen zusätzlichen Energie etwas zu tun geben...\n\nIch hab's! Der Jutepfad! Sie kann den ganzen Tag dort Ho-zen vermöbeln!\n\n<Buchsbaum wendet sich der gewaltigen Bestie zu.>\n\nWas meinst du, hübsches Mädchen? Willst du Ho-zen vermöbeln?!\n\nIch glaube schon. Hier, gebt ihr meine Notfallflasche Kafa. Sie mag Euch.", sourceObjective = "Gebt Kota Kon beim Basislager am Kota das Fläschchen Kafa, dann tötet 100 Ho-zen entlang des Jutepfads.", progress = "Lasst uns unser Glück nicht herausfordern... Wir haben ihr Ho-zen-Stampfi-Stampfi versprochen!", completion = "Puh! Das war GEWALT.\n\nIch bin nicht sicher, was ich erwartet habe...\n\nIch glaube, wir haben dank Euch gerade eine Beziehung mit dem Schrecken der Kotaspitze geknüpft, die beiden nutzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30750] = { id = 30750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mauerfall", description = "Die Yaungol hier auf der Mauer geben den anderen unten Feuerschutz. Ich weiß nicht, was Lao-Chen vorhat, aber ich will, dass Ihr diese Bogenschützen ausschaltet.\n\nEs gibt auch etwas Gutes zu berichten: Der Geist des Ochsen ist hier, um uns zu helfen. Wenn die Yaungol geschwächt sind, wird der Geist sie betäuben - Ihr könnt diesen Moment nutzen, um sie von der Mauer zu stoßen.\n\nDie Bogenschützen haben gleich hinter dieser Tür Position bezogen.", sourceObjective = "Tötet 12 Bogenschützenveteranen oder Feuerkrieger von Osul.", completion = "Ha! Und da fliegen sie. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[30751] = { id = 30751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schreckliches Opfer", description = "Ich habe eine Idee und... ich bin bereit, ein schreckliches Opfer zu bringen.\n\nSoweit ich das abschätzen kann, wird mein Gebräu für die Stärkung der Verteidiger und damit für die langfristige Sicherheit des Ochsentors benötigt...\n\nDie Sache ist zu schmerzhaft, um jetzt darüber zu sprechen. Aber ich bitte Euch, ein paar ihrer Ölfässer, mit denen sie ihre Pfeile entzünden, einzusammeln, während Ihr die Mauer verteidigt. Wir werden sie später brauchen.", sourceObjective = "Sammelt 6 Fässer mit Feueröl der Yaungol.", progress = "Habt Ihr das Öl?", completion = "Also gut. Ich werde jetzt unsere nächsten Schritte vorbereiten. Viel Glück, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[30752] = { id = 30752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unglaublich!", description = "Ich kann nicht glauben, dass die Wachen uns am Betreten des Klosters hindern werden, wenn sie den Ernst unserer Lage erst einmal verstehen.\n\nGeht zur Wache vor dem Kloster im Osten und verlangt Einlass. Ich werde Euch begleiten.", sourceObjective = "Sprecht mit dem Wächter des Shado-Pan-Klosters, um Zugang zum Shado-Pan-Kloster zu erlangen.", progress = "Unglaublich!", completion = "Nein... es ist viel schlimmer, als ich dachte. Das Kloster selbst ist befallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[30753] = { id = 30753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ritt auf dem Hai", description = "Dort, wo ich herkomme, besteht der einzige Weg, einen Hai zu töten, darin, ihn mit bloßen Händen zu erlegen!\n\nIch habe in der Nähe des Docks hier eine Menge Futter ins Wasser geworfen. Bald sollte es hier von Haien nur so wimmeln. Hüpft auf den ersten, den Ihr seht, und erledigt ihn!", sourceObjective = "Tötet einen rasenden Riffhai mit bloßen Händen.", progress = "Habt Ihr dem Hai gezeigt, wer der Boss ist?", completion = "Was für ein riesiger Hai, den Ihr da besiegt habt, {name}! Ich bin beeindruckt!", sourceObjectiveStatus = "unverified-source-field" }
quests[30754] = { id = 30754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heller Köder", description = "Bestimmte Fische werden nur von hellen Lichtern angezogen. Der Wald im Norden von hier beheimatet die hiesige Art Pandaren-Glühwürmchen, die Sonnenkriecher genannt wird.\n\nIhr solltet sie unten an Baumstümpfen finden können. Bringt eine Handvoll von ihnen her, damit ich sie als Köder verwenden kann!", sourceObjective = "Sammelt 7 Sonnenkriecher im Wald nördlich des Außenpostens der Angler.", progress = "Hattet Ihr Glück mit den Sonnenkriechern?", completion = "Die sollten wirklich reichen, {name}. Danke für die Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[30757] = { id = 30757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herr der Shado-Pan", description = "Ein Sha des reinen Hasses hat unseren Herrscher, Taran Zhu, in Besitz genommen. Das ganze Kloster ist verloren!\n\nIch bitte Euch: Ihr müsst einen Weg finden, ihn zu befreien. Zuletzt sah ich ihn, wie er im Hain der Fallenden Blüten meditierte.", sourceObjective = "Befreit Taran Zhu vom Sha des Hasses.", completion = "Ich danke Euch, {class}. Jetzt bin ich wieder frei von all dem Hass.\n\nVon nun an werdet Ihr für immer zu den Helden der Shado-Pan zählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30763] = { id = 30763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piranha!", description = "Einige Fische sind sehr schwierig zu fangen. Der Wolfspiranha fällt auf jeden Fall in diese Kategorie.\n\nEin Glück für mich, dass Ihr aufgetaucht seid! Prüft Eure Fähigkeiten im Fischen und bringt mir ein paar von denen vom Krasarang ein Stück nordwestlich von hier.", sourceObjective = "Fischt 5 Wolfspiranhas aus dem Krasarang in der Krasarangwildnis.", progress = "Schon Glück gehabt?", completion = "Wie ich sehe, habt Ihr noch alle Eure Finger. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[30765] = { id = 30765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre zurückgewinnen", description = "{name}, der Kriegshäuptling der Yaungol, Attilaqa der Hüne, hat Shado-Meister Zhen getötet. Er hat sein Banner.\n\nIhr müsst Attilaqa den Hünen töten und Zhens Ehre zurückgewinnen! Wenn Ihr es nicht macht, werde ich es tun.", sourceObjective = "Beschafft Zhens Banner.", sourceObjectiveStatus = "unverified-source-field" }
quests[30766] = { id = 30766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Historische Geschäfte", description = "<Ein Relikt löst sich von der Statue. Hm, dies könnte für die richtige Person von echtem Wert sein.>\n\n<Im Außenbereich der Ruinen hält sich ein Sammler auf. Vielleicht hat er ja Interesse, Euch solche Dinge abzukaufen?>", sourceObjective = "Sammelt 11 weitere Relikte der Mogu ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[30767] = { id = 30767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles riskieren", description = "Moment - was?! Wie kann er bloß so rücksichtslos sein? Das Schiff freisprengen zu wollen ist Wahnsinn! Es könnte das Ende von Shen-zin Su bedeuten... und damit unser aller Ende.\n\nIch weiß, dass wir nicht viel Zeit haben, aber wir müssen einen anderen Weg finden...", sourceObjective = "Entfernt den Stachel aus dem Fleisch Shen-zin Sus.", sourceObjectiveStatus = "unverified-source-field" }
quests[30768] = { id = 30768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Gatte...", description = "Lin...\n\nWas Ban, Lao-Chen oder selbst Taran Zhu sagen, ist mir egal. Ich gehe weiter nach Tonlong. Vielleicht kann ich Lin nicht selbst retten, aber ich werde nicht einfach herumsitzen und warten, bis alle anderen nachkommen.\n\nSobald Taran Zhu die Tore zu seinem kostbaren Kloster öffnet, werden wir Lin retten. In der Zwischenzeit werde ich den Weg voraus erkunden und dafür sorgen, dass es ihm gut geht.", sourceObjective = "Trefft Euch mit Suna Stillstoß am Außenposten Longying in der Tonlongsteppe.", completion = "Gut. Sieht so aus, als hätten die restlichen Shado-Pan beschlossen, dass die Zeit zum Aufholen gekommen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[30769] = { id = 30769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erster Angriff", description = "Jetzt, da wir etwas Zeit hatten, die Schwächen unserer Gegner auszuloten, wird es Zeit für uns, den Yaungol einen direkten Schlag zu versetzen.\n\nGeht und fordert die Scharfhörner von Osul auf der Mesa im Westen heraus.\n\nLasst sie wissen, dass wir hier sind und keine Angst vor ihren Drohungen haben.", sourceObjective = "Tötet 6 Scharfhörner von Osul.", completion = "Gut gemacht, {name}. Ich hoffe, Ihr habt diesen Kretins keine Gnade gezeigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30770] = { id = 30770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Flucht", description = "Jede Armee braucht eine Nachschublinie.\n\nIm feindlichen Lager im Westen gibt es eine große Tierherde, die der Yaungol-Armee als Hauptnahrungsquelle dient.\n\nZu unserem Glück sind die Yaks und Mushan hier in der Gegend ziemlich schreckhaft.\n\nSchleicht Euch an sie heran, versetzt den Tieren einen ordentlichen Klaps und wartet ab, was passiert.", sourceObjective = "Erschreckt 8 Langhaaryaks oder Steppenmushan.", completion = "Ohohoho! Ich konnte die Staubwolke, die die Biester hinterlassen haben, von hier oben sehen.\n\nDie Yaungol fragen sich vermutlich noch immer, was passiert ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[30771] = { id = 30771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pech gehabt", description = "Wenn der Osulstamm in den Krieg zieht, imprägnieren sie ihre Speere und Pfeile mit einem leicht entzündlichen, lang brennenden Pech.\n\nMit diesen schrecklichen Waffen vergießen sie nicht nur Blut, sondern zerstören auch die Häuser ihrer Feinde.\n\nIch möchte, dass Ihr etwas von diesem Pech sammelt, während Ihr Euch in ihrem Lager aufhaltet.\n\nDamit werden wir den Yaungol zeigen, wie leicht man sich verbrennen kann, wenn man mit dem Feuer spielt.", sourceObjective = "Sammelt 8 Einheiten Schwarzpech.", progress = "Den Yaungol reicht es nicht, ihre Feinde einfach zu besiegen. Nein, sie wollen sie vollständig vernichten.", completion = "Es riecht noch ganz frisch.\n\nGute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30772] = { id = 30772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rot sehen", description = "Vor uns befindet sich der Hauptstoß der Yaungol-Armee.\n\nDort bereitet sich ihre gewaltige Armee darauf vor, die Dörfer des Kun-Lai anzugreifen.\n\nWenn wir jetzt gegen die Yaungol von Osul vorstoßen, treffen wir sie direkt in ihrem Kern.\n\nDenkt daran: Mit jedem von ihnen, den wir niederstrecken, retten wir einen von uns zu Hause.", sourceObjective = "Tötet 8 Marodeure oder Feuerspucker von Osul.", completion = "Das sollte ihre Reihen ernsthaft ausdünnen.\n\nIch bezweifle, dass sie sich von diesen Verlusten erholen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[30773] = { id = 30773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brandstiftung", description = "Die Belagerungswaffen der Yaungol - diese Speerwerfer-Ballisten dort unten - reißen unsere Verteidigung im Außenposten Longying und am Kun-Lai-Gipfel in Stücke.\n\nDiese entsetzlichen Waffen müssen zerstört werden.\n\nNehmt diesen Sprengstoff. Ich habe ihn in das Pech getaucht, das Ihr gesammelt habt.\n\nWerft ihn auf die Ballisten, dann zahlen wir es den Yaungol mit gleicher Münze heim.", sourceObjective = "Benutzt Bans Sprengstoff, um 6 Ballisten von Osul zu zerstören.", progress = "Feuer ist eine grausame Waffe. Zum Glück zerstören wir nur Kriegsgerät damit.", completion = "Sehr gut, {class}.\n\nJetzt können sie sich nicht mehr hinter ihren Belagerungswaffen verstecken und haben keine andere Wahl, als sich uns zu stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30774] = { id = 30774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rettung der Waldläufer", description = "Ich habe eine sehr wichtige Aufgabe für Euch, {name}.\n\nIrgendwo in den Käfigen im Lager Osul sitzt mein Mann Lin. Er ist der Mittelpunkt meiner Welt.\n\nBitte findet ihn und bringt ihn mir zurück und rettet dabei so viele von unseren Shado-Pan-Genossen, wie Ihr könnt.\n\nDie Schlüssel zu den Käfigen solltet Ihr bei den Marodeuren von Osul finden.", sourceObjective = "Schließt Trockenholzkäfige auf, um 4 Longying-Waldläufer und Lin Stillstoß zu retten.", completion = "Es tut mir aufrichtig leid, dass Lin es nicht geschafft hat.\n\nSuna nimmt die Neuigkeiten recht schwer. Sie wird mir schon noch verzeihen.\n\nWas die restlichen Shado-Pan angeht, die Ihr gerettet habt, so bin ich sehr dankbar, dass sie heil und unversehrt zurück sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[30775] = { id = 30775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verbannung", description = "Was gibt es da noch zu sagen, <Fremder/Fremde>?\n\nIch bin gegen Jung Duk angetreten und habe verloren. Ich war so dumm und habe geglaubt, er würde fair kämpfen.\n\nJetzt haben sich meine eigenen Brüder gegen mich gewendet, und ich bin hier und spreche mit unseren Feinden.\n\nIch weiß, dass Ihr hier seid, um Osul-Blut zu sehen.\n\nIch habe nur eine Bitte: Findet die drei, die mich verraten haben.\n\nUrang, der mir das Gift zu trinken gegeben hat. Ku-Tong, der meinen Speer verbogen hat. Und Battat, dessen Dolch in meiner Seite landete, als mir der Sieg gewiss war.\n\nGewährt mir meine Bitte, damit ich in Frieden sterben kann.", sourceObjective = "Tötet Urang, Ku-Tong und Battat.", progress = "Wie konnten sie mich bloß verraten? Sie waren doch einst meine Brüder!\n\nWarum haben sie sich gegen mich gewendet? WARUM?\n\nIch hasse sie! Ich werde sie alle umbringen!", completion = "Zu wissen, dass diese Feiglinge durch Eure Hand den Tod erlitten haben, freut mich.\n\nVielleicht wird die brennende Flut in meinem Herzen jetzt verebben.", sourceObjectiveStatus = "unverified-source-field" }
quests[30776] = { id = 30776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jung Duk", description = "DAS. BEDEUTET. KRIEG.\n\nIch will die Köpfe aller, die mir Lin genommen haben. ALLER!\n\nAls Erstes knöpfen wir uns den Osul-Anführer Jung Duk vor.\n\nNehmt dieses Banner der Shado-Pan und hisst sie inmitten ihres Lagers.\n\nJung Duk wird keine andere Wahl haben, als sich Euch zu stellen.\n\nZeigt ihm keine Gnade, {name}.", sourceObjective = "Stellt das Shado-Pan-Banner auf dem zeremoniellen Haufen auf und tötet dann Jung Duk.", progress = "Jung Duks Vermächtnis ist im Blut der Unschuldigen geschrieben.", completion = "Jung Duk ist endlich tot.\n\nHunderte, vielleicht sogar Tausende, haben wegen seines gewalttätigen Wütens ihr Leben lassen müssen.\n\nAuch, wenn sie seinen Untergang nicht miterleben durften, sind sie Euch ob Euren Mutes zu Dank verpflichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[30777] = { id = 30777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Suna", description = "Ich bringe schlechte Nachrichten. Als ich zurückkam, war Suna bereits weg.\n\nDie anderen sagten, dass sie mit Sack und Pack die Straße gen Osten heruntergezogen ist und gemurmelt hat, sie werde Jagd auf den Quell der Yaungolaggression machen.\n\nIch kann nicht zulassen, dass sie sich allein in ein gefährliches Gebiet aufmacht.\n\nIch habe bereits einen Trupp Soldaten aufgestellt, um weiter nach Osten vorzustoßen.\n\nWir brechen bald auf. Schließt Euch der Karawane an, wenn Ihr mit den Shado-Pan reisen wollt. Ihr könnt uns auch dort treffen, wenn Ihr möchtet.", sourceObjective = "Sprecht mit Ban Bärenherz, wenn Ihr in Haderzwinge angekommen seid.", completion = "Nun, wir haben es geschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[30778] = { id = 30778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staub zu Staub", description = "Wenn wir hier unser Lager aufschlagen wollen, können wir diese Yaungolleichen hier nicht einfach so verwesen lassen.\n\nNehmt diese Fackel und steckt die Leichen der Dorfbewohner in Brand.\n\nDas Räucherwerk der Fackel sollte auch die Erde und Luft um sie herum reinigen.\n\nSelbst unsere Feinde verdienen es, würdig bestattet zu werden.", sourceObjective = "Benutzt die Fackel der Shado-Pan bei 20 Bewohnern von Bleichwind.", progress = "Der Gestank des Todes ist überwältigend.", completion = "Gute Arbeit, {name}.\n\nHoffentlich sind ihre Geister jetzt an einem besseren Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[30779] = { id = 30779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd auf Aasfresser", description = "Die verwesenden Leichen locken aasfressende Hyänen an.\n\nDiese wilden Kreaturen werden nach dem Fressen der Toten nicht nur Krankheiten verbreiten, sondern uns auch angreifen, sobald sie uns sehen.\n\nZieht los und rottet die Bestien aus. Das ist zwar bedauernswert, letztendlich aber am besten.", sourceObjective = "Tötet 8 Aschezahnhyänen.", completion = "Ich danke Euch, {name}. Das war eine unschöne Aufgabe, doch sie musste erledigt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[30780] = { id = 30780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totemische Forschung", description = "Als wir das Dorf betraten, fielen mir sofort die im Lager herumliegenden Yaungoltotems auf.\n\nIch vermute, dass hier finstere Mächte am Werk sind und dass die Totems der Schlüssel sind, um sie hervorzulocken.\n\nKönntet Ihr mir ein paar dieser Totems bringen? Ich würde sie gern genauer untersuchen.", sourceObjective = "Sammelt 9 Bleichwindtotems.", progress = "Ich glaube, die Totems könnten uns nützlich sein.", completion = "Ich hatte recht! Diese Totems wurden einst zum Speichern und Leiten gewaltiger magischer Energien benutzt.\n\nIch glaube, ich kann sie wieder genau dafür verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[30781] = { id = 30781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfüllt das Soll an Yaungol", description = "Ban hat mich gebeten, Untersuchungen im Dorf anzustellen, um zu ergründen, was hier vorgefallen ist.\n\nIch habe Rauch im Osten, im Westen, im Nordwesten und im Süden aufsteigen sehen.\n\nIch brauche jemanden, dem ich vertraue, um mir Rückendeckung zu geben.\n\nWas sagt Ihr? Wollt Ihr mich auf meiner ersten Spähmission unterstützen?", sourceObjective = "Bringt Xiao Tu zu den Rauchzeichen in der Nähe von Haderzwinge.", progress = "Etwas Furchtbares muss hier passiert sein.", completion = "Danke für Eure Hilfe, {name}.\n\nWir wissen zwar nicht genau, was dort passiert ist, aber offensichtlich hat irgendetwas die Yaungol gegeneinander aufgehetzt.\n\nDoch was hätte solche Macht?", sourceObjectiveStatus = "unverified-source-field" }
quests[30782] = { id = 30782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boshafte Geister", description = "Die Geister der gefallenen Dorfbewohner haben sich erhoben! Ich spüre den Hass, der von diesen Geistern ausströmt.\n\n{name}, wenn wir hier überleben wollen, müssen wir uns verteidigen. Nur so können wir zur Ruhe betten.", sourceObjective = "Tötet 10 boshafte Geister.", completion = "Gut gemacht. Wir können ihnen keine Vergeltung bringen, doch zumindest können wir ihrem Zorn ein Ende bereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[30783] = { id = 30783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hass steht uns gut", description = "Ich hätte schon vorher die Präsenz eines Sha vermuten sollen!\n\nWir sind in Sicherheit, solange wir uns innerhalb des Zauberschutzes des Totems der Harmonie befinden, aber viele von uns hatten es nicht so gut.\n\nSie saßen außerhalb des Lagers fest, als sich die Kräfte des Sha manifestierten und jetzt gehen sie aufeinander los!\n\nNehmt eins meiner Totems mit. Platziert das Totem in der Nähe von verrückt gewordenen Verbündeten, um sie zu läutern, aber seid vorsichtig.\n\nIhr könntet es mit jener Dunkelheit zu tun bekommen, die von ihnen Besitz ergriffen hat.", sourceObjective = "Benutzt das Totem der Harmonie, um 8 wahnsinnigen Shado-Pan-Waldläufern die Sha-Geister auszutreiben. Besiegt Manifestationen Sengenden Hasses, um Eure Verbündeten zu läutern.", completion = "Danke.\n\nDas Sha sucht sich die Schwachen und Verwundbaren als Opfer.\n\nWenn wir nicht achtgeben, werden selbst die Stärksten unter uns dem finsteren Einfluss des Sha anheimfallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30784] = { id = 30784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Punkt ohne Wiederkehr", description = "Einer von unseren Waldläufern meldet, Suna auf dem Hügel im Nordwesten gesehen zu haben.\n\nIch hatte die schlimmsten Befürchtungen, was sie in ihrem Kummer machen würde, und bin erleichtert, dass sie unversehrt ist.\n\nWürdet Ihr zu ihr gehen und mit ihr sprechen?\n\nNehmt dieses Totem mit. Es könnte Euch nützlich sein, wenn Ihr unterwegs in Gefahr geratet.", sourceObjective = "Sucht Suna Stillstoß.", progress = "Wenn ich die Vergangenheit ändern könnte, dann würde ich das machen. Wenn ich Lins Platz einnehmen könnte, dann würde ich das machen.\n\nSelbst in tausend Leben kann ich Sunas Verlust nicht wiedergutmachen oder ihr auch nur einen Bruchteil ihrer Trauer abnehmen.", completion = "Was? Sie war von dem Sha des Hasses besessen?\n\nNein. OH NEIN!\n\nWir hatten unsere Differenzen, doch sie war eine von uns. Heute haben die Shado-Pan eine geschätzte Schwester verloren.\n\nIhr Tod soll nicht umsonst gewesen sein. Ich werde erst ruhen, wenn ich das Sha des Hasses bezwungen habe!\n\nDas verspreche ich Euch, Suna!", sourceObjectiveStatus = "unverified-source-field" }
quests[30785] = { id = 30785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gao-Ran-Front", description = "Mit Eurer Hilfe haben wir die Geister dieses Orts bezwingen können.\n\nEndlich können sie in Frieden ruhen.\n\nUnsere Reise in dieses verfluchte Land hat jedoch gerade erst begonnen.\n\nIch habe noch einige wichtige Dinge hier zu regeln, doch bald werden wir ausschwärmen.\n\nIch brauche jemanden, der vorausgeht und Meister Taran Zhu ausrichtet, dass wir zu ihm stoßen werden.\n\nIhr findet ihn an der Gao-Ran-Front. Sagt ihm, was hier zutage getreten ist.", sourceObjective = "Sprecht mit Meister Taran Zhu an der Gao-Ran-Front in der Tonlongsteppe.", completion = "Dann ist die Nordexpedition gut gelaufen? Was gibt es Neues zu berichten?", sourceObjectiveStatus = "unverified-source-field" }
quests[30786] = { id = 30786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Speer in meiner Seite; die Seele in Ketten", description = "Mein Schicksal ist besiegelt. Die Yaungol haben mir diesen Speer in die Seite getrieben. Die Wunde wird mein Tod sein.\n\nDie Yaungol haben mich mit ihrer verqueren, verdorbenen Magie auf der Stelle festgesetzt. Diese Schmach schmerzt mir mehr als die Speerwunde.\n\nMeinem Tod kann ich nicht entrinnen. Doch mein Gefängnis... aus dem könnt Ihr mich womöglich befreien.", sourceObjective = "Tötet Dmong Naruuk, den Schamanen, der Orbiss als Geisel festhält.", progress = "Ich werde nicht sterben, bevor ich Rache geübt habe.", completion = "Ich bin frei.\n\nDie Yaungol müssen aufgehalten werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[30787] = { id = 30787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Fackeln", description = "Bis vor Kurzem kamen die Schamanen der Yaungol hierher, um gemeinsam mit uns zu arbeiten. Jetzt unterjochen sie mein Volk.\n\nWenn wir uns weigern, töten sie uns. Und wenn wir gehorchen... töten sie uns ebenfalls.\n\nDie Magie eines Nebelschamanen der Yaungol fließt durch seine Fackel. Nehmt ihm seine Fackel und ihm bleibt nichts mehr.", sourceObjective = "Besorgt 6 Nebelschamanenfackeln.", progress = "Mit diesen Fackeln kann ich Rache üben.\n\nIch bin dieser Wunde noch nicht erlegen. Ich kann mich immer noch rächen, ehe ich sterbe.\n\nMir bleibt noch Zeit.", completion = "Diese Fackel... früher haben die Yaungol sie benutzt, um mit mir, mit meinem Volk zu kommunizieren.\n\nJetzt machen sie uns mit ihnen zunichte.", sourceObjectiveStatus = "unverified-source-field" }
quests[30788] = { id = 30788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golgoss", description = "Der Anführer der Yaungol-Nebelschamanen heißt Jahesh. Er ist für seine Stärke bekannt.\n\nEs gibt einen unter den Meinen, der ebenfalls für seine Stärke bekannt ist. Sein Name ist Golgoss.\n\nGolgoss schlummert in den Nebeln der Sumpfbinsenhöhe. Helft mir, ihn zu beschwören, und er wird an meiner Seite unser Volk rächen.", sourceObjective = "Beschwört Golgoss, indem Ihr die Nebelschamanenfackeln im Torfklumpen auf der Sumpfbinsenhöhe platziert.", completion = "Golgoss spricht Eure Sprache kaum - höchstens ein paar Worte. Ich glaube, dass ich in dieser Hinsicht ziemlich einzigartig bin.\n\nEr dankt Euch für Eure Unterstützung.", sourceObjectiveStatus = "unverified-source-field" }
quests[30789] = { id = 30789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arconiss", description = "Wenn ich Jahesh, den Anführer der Nebelschamanen der Yaungol bekämpfen soll, brauche ich Arconiss an meiner Seite, denn seiner Grausamkeit kann keiner das Wasser reichen.\n\nEr ruht unter den Nebeln der Sumpfbinsenhöhe. Sucht seine Ruhestätte und benutzt dann diese Fackeln, um ihn aufzuwecken.", sourceObjective = "Beschwört Arconiss, indem Ihr die Fackeln des Nebelschamanen im Torfhügel auf der Sumpfbinsenhöhe aufstellt.", completion = "Mit Arconiss an meiner Seite werde ich kaum verlieren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[30790] = { id = 30790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golgoss' Hunger", description = "Golgoss' Stärke ist groß, doch bevor er sich ihrer bedienen kann, braucht er Nahrung.\n\nDie Knotdornbüsche in der Sumpfbinsenhöhe haben dicke, faserige Äste. Die sollten seinen Hunger stillen.", sourceObjective = "Sammelt 10 Knotranken.", progress = "Golgoss' Hunger ist groß.", completion = "Damit sind wir meinem Ziel einen Schritt näher.", sourceObjectiveStatus = "unverified-source-field" }
quests[30791] = { id = 30791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arconiss' Durst", description = "Arconiss kämpft mit einer Raserei, die ihresgleichen sucht, doch er hat so lange unter den Nebeln geruht, dass er geschwächt ist.\n\nIm Sumpf wimmelt es vor Nagetieren, deren Körper prall mit nahrhaftem Blut gefüllt sind. Kehrt mit genug Blut zurück, um Arconiss' Kampfgeist zu wecken.", sourceObjective = "Sammelt 4 Einheiten geronnenes Nagetierblut.", progress = "Unsere Vorbereitungen werden nicht mehr lange dauern.", completion = "Damit bin ich dem Erfolg meiner Mission einen Schritt näher.", sourceObjectiveStatus = "unverified-source-field" }
quests[30792] = { id = 30792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orbiss verblasst", description = "Ich wusste, dass der Tod kommen würde. Allerdings war mir nicht klar, dass es so schnell geschehen würde.\n\nIch muss Zeit gewinnen. Der Nebel der Sumpfbinsenhöhe ist warm und wohlriechend. Diese Art Nebel ist für mein Volk nahrhaft.\n\nSammelt den Nebel auf jede nur erdenkliche Art... in Gläsern, Phiolen, in Euren Taschen. Bringt ihn zu mir, damit ich mich etwas länger körperlich manifestieren kann.", sourceObjective = "Sammelt 8 Sprudelnebel, indem Ihr durch die Nebelgeysire auf der Sumpfbinsenhöhe lauft.", progress = "Ich brauche mehr Nebel. Ich verblasse...", completion = "Ich habe Euch doch gesagt, diese Wunde wird mein Tod sein. Ihr habt mir zwar etwas mehr Zeit verschafft, doch geht es bald mit mir zu Ende.", sourceObjectiveStatus = "unverified-source-field" }
quests[30793] = { id = 30793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gelegenheiten im Nebel", description = "Die Zeit ist reif für einen Angriff.\n\nGolgoss, Arconiss und ich werden nach Osten, zu Jaheshs Domäne, aufbrechen. Stoßt dort zu uns und bereitet Euch auf den Kampf vor.\n\nHeute stellen wir den Stolz unseres Volkes wieder her.", sourceObjective = "Erschlagt Jahesh von Osul.", completion = "Mein Name wird in Vergessenheit geraten, nicht jedoch meine Taten.\n\nUnd Eure auch nicht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30794] = { id = 30794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notfallversorgung", description = "Ich... bin am Leben... aber nur gerade so. Sie haben den Rest getötet. Meine Freunde... meine Familie...\n\nIch muss zum Dorf zurück... Aber ich habe nicht mehr lange, und ich kann mich nicht bewegen... Seid Ihr <ein Heiler/eine Heilerin>? Ich... habe einen Heiltrank in meiner Hütte... oder setzt Magie ein, wenn Ihr könnt.", sourceObjective = "Heilt den Weisen Liao, damit er wieder auf die Beine kommt.", completion = "Vielen Dank... Ich schätze... ich werde Euch um noch etwas bitten müssen, bevor ich ins Dorf zurückkehren kann. Ich kann die Leichen meiner Freunde und meiner Familie nicht hier zurücklassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30795] = { id = 30795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Verbindung bleiben", description = "Die Zunge von Ba-Shon sollte es uns ermöglichen, über große Entfernungen zu kommunizieren, {name}.\n\nWenn das Relikt so funktioniert, wie ich glaube, sollte ich in der Lage sein, hier zu bleiben und mit meinen Meditationen fortzufahren, während Ihr das Tal der Kaiser etwas ausspäht.\n\nMishi wird Euch bis an den Rand des Tals bringen, damit wir meine Theorie testen können. Mir wäre nicht wohl dabei, wenn Ihr in den Gräbern wärt und keine Möglichkeit hättet, mich zu kontaktieren. Das wäre schrecklich!", sourceObjective = "Benutzt die Zunge von Ba-Shon im Tal der Kaiser.", completion = "Sehr gut! Das Relikt funktioniert!\n\nEs scheint mehr im Tal der Kaiser vor sich zu gehen, als ich erwartet habe. Es ist wichtig, dass wir herausfinden, warum die Mogu die Gräber öffnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30796] = { id = 30796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles hat ein Ende", description = "Diese Geister müssen freigelassen worden sein, als die Grabmale geöffnet wurden...\n\nDer Tod war nicht das Ende für die Mogu. Stattdessen war der Tod nur ein kurzer Halt auf dem Weg zu einem neuen Körper. Geisterbinder haben üble Magie eingesetzt, um Geister von einer Hülle zur nächsten zu übertragen.\n\nDie Jahre, die sie in den Grabmalen eingeschlossen waren, haben sie verwirrt. Sie müssen vernichtet werden, bevor sich ihre Verwirrung in Zorn verwandelt oder, was noch schlimmer ist, sie eine neue Hülle finden.", sourceObjective = "Vernichtet 5 gequälte Geister.", completion = "Ihr habt ihnen einen großen Dienst erwiesen, {name}.\n\nZwischen der Welt der Lebenden und dem Jenseits festzustecken, ist ein grausames Schicksal.", sourceObjectiveStatus = "unverified-source-field" }
quests[30797] = { id = 30797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es hat fast gelebt", description = "Hier hat ein Ritual stattgefunden, und wie es scheint, war es nicht von Erfolg gekrönt.\n\nUnter den zurückgelassenen Gegenständen befindet sich ein offenes Buch. Die Sprache des Texts auf der Seite ist Euch fremd.\n\nEs könnte schwierig werden, das ganze Buch zu tragen, aber vielleicht reicht eine Seite. Wenn Ihr die Seite zu Lehrensucher Cho schaffen könnt, ist er vielleicht in der Lage, Euch zu sagen, was dort steht.", sourceObjective = "Reißt eine Seite aus dem offenen Buch, um sie Lehrensucher Cho zu bringen.", progress = "Was habt Ihr gefunden, {name}?", completion = "Der Text ist in der Tat seltsam, {name}...\n\nEr scheint in der Mengdynastie geschrieben worden zu sein, aber einige der Symbole sind falsch. Ich glaube nicht, dass die Mogu dies verfasst haben, obwohl es dem seltsam nahe kommt.\n\nIch werde einige Zeit brauchen, um es zu übersetzen. Bleibt in Bewegung und seht zu, ob Ihr noch etwas anderes finden könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30798] = { id = 30798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zertrümmerung des Schilds des Kaisers", description = "Die Mogu wurden zerstreut und waren jahrelang nur wenige. Ihr Vorhaben im Tal ergibt nun einen Sinn.\n\nBei diesen vielen rastlosen Geistern können sie mit den in den Gräbern liegenden Wächtern eine Armee aufbauen. Zusammen mit den Streitkräften der Zandalari wäre das verheerend!\n\nDas Grab der Geheimnisse beherbergt Elitekämpfer, die man den Schild des Kaisers nannte. Sie dürfen nicht wiedererweckt werden! Ihr findet das Grab auf der höchsten Erhebung im Südwesten.", sourceObjective = "Stoppt das geistbindende Ritual im Grab der Geheimnisse.", progress = "Wart Ihr schon beim Grab der Geheimnisse?", completion = "Die Mogu und die Zandalari haben vor, den Donnerkönig wiederzubeleben?!\n\nDas dürfen wir nicht zulassen, {name}! Der Donnerkönig wird mit seiner Rückkehr Zerstörung über dieses Land bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30799] = { id = 30799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grab der Schatten", description = "Die Artefakte, die Ihr auf dem Altar gefunden habt, bringen mich zu der Annahme, dass sie versucht haben, ein Geistbindungsritual durchzuführen.\n\nDie meisten Texte über Geistbindung waren im Grab der Schatten weggesperrt. Vielleicht finden wir dort die Antworten, die wir suchen.\n\nHaltet nach allem Ausschau, das uns helfen könnte. Ihr findet das Grab auf der ersten Erhebung vom Ritualaltar aus gesehen.", sourceObjective = "Sammelt ein Abpausbild der Tafel aus der Shendynastie, der Tafel der Waidynastie und der Tafel der Qiangdynastie im Grab der Schatten.", progress = "Habt Ihr im Grab der Schatten etwas gefunden?", completion = "Diese Tafeln erzählen die Geschichte des Bündnisses zwischen den Mogu und den Zandalari aus der Zeit des ersten Mogukaisers.\n\nWie es aussieht, haben sie ihr Bündnis wiederbelebt. Aber warum jetzt?", sourceObjectiveStatus = "unverified-source-field" }
quests[30800] = { id = 30800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihren Donnerkönig stehlen", description = "Unsere einzige Hoffnung besteht darin, die Überreste des Donnerkönigs vor ihnen zu finden. Er muss im Grab der Eroberer begraben sein.\n\nAn seine Überreste zu kommen wird nicht einfach sein, {name}. Das Grab wird zweifellos von Wächtern und anderen unangenehmen Überraschungen verteidigt werden, die Diebe fernhalten sollen.\n\nWenn Ihr erst einmal drin seid, müsst Ihr herausfinden, wo man seine Überreste nun wirklich abgelegt hat.", sourceObjective = "Findet das unterste Fragment von Lei Shens Tafel und stellt die Tafel des Donners wieder her.", progress = "Habt Ihr herausgefunden, wo die Überreste des Donnerkönigs versteckt liegen?", completion = "Wir haben Glück, dass sie Lei Shens Überreste nicht gefunden haben...noch nicht.\n\nDie Zandalari werden nicht aufgeben, bis sie haben, was sie wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30801] = { id = 30801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschichtsstunde", description = "Der Donnerkönig war ein grausamer Herrscher und mit den Zandalari an seiner Seite war er nicht aufzuhalten. Seine Rückkehr würde dieses Land mit Sicherheit in Aufruhr und Elend stürzen.\n\nIhr müsst seine Überreste aufspüren und sie in Sicherheit bringen. Die Schrifttafel des Donners sollte Euch Aufschluss darüber geben, wie man in sein Grabmal hineingelangt.", sourceObjective = "Lest die Schrifttafel des Donners im Grab der Eroberer.", completion = "Sie werden die Überreste an einen sicheren Ort schaffen müssen. Wir müssen sie verfolgen!", sourceObjectiveStatus = "unverified-source-field" }
quests[30802] = { id = 30802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmjäger", description = "Wir müssen herausfinden, wohin sie die Überreste des Donnerkönigs bringen würden. Es wird ihnen nicht möglich sein, ihn im Tal der Kaiser wiederzuerwecken. Sie müssen weiter entfernt und in Sicherheit sein.\n\nEs scheint, als ob es zudem eine weitere Herausforderung wäre, hier herauszukommen...\n\nKämpft Euch nach draußen durch und sucht nach Informationen darüber, wo sich die Überreste befinden.", sourceObjective = "Findet die durch Blut enthüllte Karte bei einem Krieger der Zandalari.", progress = "Konntet Ihr Informationen zu ihrem Aufenthaltsort finden?", completion = "Das ist dunkle Blutmagie der Zandalari. Wenn wir mit der Karte fertig sind, sollten wir sie verbrennen.\n\nLaut Karte sind sie an die Küste etwas außerhalb eines kleinen Fischerdorfs namens Zouchin gezogen. Die Dorfbewohner dort können uns vielleicht helfen, die Zandalari aufzuspüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[30804] = { id = 30804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Angstmeister", description = "Ich halte das nicht mehr aus. Meine Frau, gesegnet sei sie, steckte ihr Herz und ihre Seele in diese Ranch und machte sie zu dem, was sie heute ist.\n\nDiese Yaungol haben da einen Führer, der unglaublich arrogant und was noch alles ist. Ich werde Euch großzügig belohnen, wenn Ihr ihm dieses arrogante Grinsen aus seinem dreckigen, stinkenden, nichtsnutzigen Gesicht prügelt.", sourceObjective = "Tötet den Angstmeister.", completion = "Jahuu! Ich wusste, ein {race} wie Ihr ist zu etwas zu gebrauchen. Es muss einen befriedigenden \"Bums\" gegeben haben, als er auf dem Boden aufgeschlagen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[30805] = { id = 30805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechtigkeit", description = "Nachdem die Söldner uns ausgeraubt hatten, sind die meisten von ihnen verschwunden.\n\nAber einer von ihnen... nachdem die anderen uns alles genommen hatten... Er nahm sich den Rest von uns vor. Als Sport!\n\nLasst Gerechtigkeit für die Gefallenen walten. Vielleicht hebt die Nachricht von ihrem Tod meinen Geist genug, damit ich weitermachen kann.\n\nIhr findet sie westlich von hier.", sourceObjective = "Tötet Hauptmann Fleischreißer und 6 Schwarzmähnenbriganten.", completion = "Ahh... sie sind tot. Ich spüre schon, wie mein Geist belebt wird. Bald werde ich stark genug sein, um zum Dorf zurückzukehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[30806] = { id = 30806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Duft des Lebens", description = "Viele sind hier gestorben. Wir müssen sie auf passende Weise ehren, was bedeutet, die Zutaten für das Räucherwerk des Lebens zu sammeln.\n\nEs riecht nicht nur gut - es hat auch stärkende Eigenschaften und begünstigt sogar das Wachstum von Pflanzen. Vielleicht hilft ein Hauch der Zutaten auch mir wieder auf die Beine.\n\nIhr findet das Material bei den Kreaturen hier - nur nicht die Gewürze, die von den Söldnern gestohlen wurden, die das Dorf geplündert haben.", sourceObjective = "Sammelt einen schimmernden blauen Krabbenpanzer und 8 gestohlene Pandarengewürze.", progress = "Rieche ich da die Zutaten für das Räucherwerk des Lebens an Euch? Oder... habt Ihr vielleicht länger nicht mehr gebadet?", completion = "Wunderbar, wunderbar. Es wäre besser, wir müssten unsere Freunde nicht begraben, aber wenn wir es schon tun müssen, dann ist es gut, dass sie eine passende Zeremonie bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30807] = { id = 30807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bei den Fällen, für die Gefallenen", description = "Ich möchte meine Freunde nicht in namenlosen Gräbern zurücklassen und sie damit entehren.\n\nDoch haben wir noch nie so viele auf einmal begraben müssen, und ich bin nicht in der Verfassung, das Material zu sammeln.\n\nGeht bitte zu den Seen, die den Bergausläufer an der Straße nach Süden umfassen. Unter den Wasserfällen dort werdet Ihr Steine finden, die durch das fallende Wasser glänzend poliert worden sind. Sie werden geeignete Grabsteine abgeben.", sourceObjective = "Sammelt 3 vom Wasserfall geglättete Steine.", progress = "Die Steine - habt Ihr sie dabei?", completion = "Gut. Danke schön. Nach all dem kann ich mir nicht vorstellen, meine Kameraden mit weniger als einem ordentlichen Begräbnis zurückzulassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30808] = { id = 30808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Glück eines Grummel", description = "Die Yaungol haben unsere Glücksbringer gestohlen! Gemeine Reiter mit Speeren haben sie einer Karawane von Brüdern auf dem Jutepfad weggenommen.\n\nDas ist ein sehr großes Unglück. Wenn die Yaungol die Geheimnisse von den Glücksbringern entdecken, sind alle Grummel in großen Schwierigkeiten.\n\nHolt unsere Glücksbringer aus dem Streitlager Ruqin nördlich von hier zurück, dann zahlen wir Euch großen Reichtum.", sourceObjective = "Findet 8 gestohlene Glücksbringer.", progress = "Ein Glücksbringer bringt viel, viel Glück. Yaungol wissen nicht, wie sie Glücksbringer anwenden müssen... noch nicht.", completion = "Hurra! Unsere Glücksbringer. Vielen Dank und Glück an Freund von Grummel!", sourceObjectiveStatus = "unverified-source-field" }
quests[30814] = { id = 30814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Fuß in der Tür", description = "<Lord Taran fängt Euch in seinem stählernen Blick.>\n\n{class}, Ihr tragt das Mal so manch einer geschlagenen Schlacht.\n\nGut! Wir können mehr kampferprobte Leute wie Euch gebrauchen, um die Front zurückzuschlagen.\n\nWir konnten hier zwar Fuß fassen, doch die Yaungol sind darauf erpicht, uns zu vertreiben.\n\nWenn Ihr Euch beweisen wollt, geht den Hügel hinunter und zeigt diesen Yaungol, dass wir nicht klein beigeben werden.", sourceObjective = "Tötet 8 Stürmer von Osul.", progress = "Wir gewinnen langsam an Boden.", completion = "Gut. Ich sehe schon, Ihr seid fähig.\n\nIch hoffe, ich kann mich für das, was kommen mag, auf Eure Talente berufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30815] = { id = 30815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Tod", description = "Ich habe beschlossen, diesen Speer aus meiner Flanke zu entfernen.\n\nDabei brauche ich Eure Hilfe. Eure zupackenden Hände sind stärker als meine.", sourceObjective = "Zieht den Speer aus Orbiss.", completion = "Mit der Entfernung dieses Speers habe ich meinen eigenen Tod wahrhaftig garantiert.\n\nDas macht mir keine Angst.\n\nLieber sterbe ich, als die Waffe meines Feindes mit mir zu führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30816] = { id = 30816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachsehen", description = "Als die Trolle kamen, brachten sie ihre... Söldnerfreunde mit. Ich sah sie an uns vorbeiziehen, zum Anglerlager im Nordwesten. Mein Cousin, ein Heiler, lebt dort - könnt Ihr nach ihm sehen und Euch vergewissern, dass es ihm und seinem Dorf gut geht?", sourceObjective = "Seht nach dem Weisen Liao auf dem Zaochin-Strand am Kun-Lai-Gipfel.", completion = "Ah... Mein Cousin macht sich aus gutem Grund Sorgen... Es geht mir nicht gut...", sourceObjectiveStatus = "unverified-source-field" }
quests[30817] = { id = 30817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heilung von Shen-zin Su", description = "Das kommt von solcher Rücksichtslosigkeit. Wie konnte er nur annehmen, dass dieser Plan aufgehen würde?\n\nWie auch immer, wir haben jetzt keine Zeit für Schuldzuweisungen. Wir müssen handeln, um Shen-zin Su zu retten.\n\nFindet so viele Heiler, wie Ihr nur könnt! Befreit sie, entbindet sie von anderen Aufgaben - tut, was auch immer Ihr tun müsst, damit sie hierherkommen und diese Wunde heilen können.\n\nBeschützt sie um jeden Preis!", sourceObjective = "Rettet und beschützt die Heiler, bis Shen-zin Sus Wunde geheilt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[30818] = { id = 30818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Schicksal", description = "Ich bin froh und dankbar, dass der Plan aufgegangen ist, {name} - auch wenn es knapper kaum hätte werden können. Wenn Ihr nicht gewesen wärt, würden wir alle zusammen mit ganz Shen-zin Su zum Meeresgrund sinken. Ich glaube nicht, dass ich Ji diese Rücksichtslosigkeit jemals verzeihen können werde.\n\nEs wird noch genug Zeit zur Besinnung geben, aber wir müssen zuerst zum Tempel der Fünf Sonnenaufgänge zurückkehren. Wir müssen sie wissen lassen, dass Shen-zin Su gerettet wurde - und wir müssen über das Schicksal dieser neuen Verbündeten entscheiden.", sourceObjective = "Kehrt zum Tempel der Fünf Sonnenaufgänge zurück. Ein Karren wartet in der Nähe der Absturzstelle der Himmelsfeuer, um Euch dorthin zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30819] = { id = 30819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitung der Überreste", description = "Vielen Dank, <mein Freund/meine Freundin>. Nach dieser Tragödie ist es gut, dass das Glück uns hold war und Euch geschickt hat.\n\nIhr habt Gerechtigkeit für meine gefallenen Freunde walten lassen und die Materialien gesammelt, die für ihre Ehrung nötig waren. Ich werde ihre Leichname bergen, die Materialien für ihre Begräbnisse vorbereiten und Euch dann am Friedhof treffen.\n\nKehrt bitte in der Zwischenzeit zu meinem Cousin zurück und bittet ihn, die Dorfbewohner für das Begräbnis zu versammeln.", sourceObjective = "Kehrt zu Li Hai zurück und erzählt ihm vom Begräbnis.", completion = "Ich verstehe... es ist tragisch, was hier passiert ist. Wir werden zum Friedhof kommen, um sie zu ehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[30820] = { id = 30820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Begräbnis", description = "Wie gesagt, ich werde die Stadt versammeln - wir werden zum Begräbnis erscheinen.\n\nWir sind der Meinung, dass es nur recht ist, das Ihr als <derjenige, der/diejenige> die; so viel getan hat, um unsere Freunde zu ehren, das Räucherwerk des Lebens anzünden und ihre Geister in das Leben danach geleiten solltet.", sourceObjective = "Wohnt dem Begräbnis bei und entzündet das Räucherwerk des Lebens.", progress = "Ihr müsst das Räucherwerk entzünden, um die Toten zu ehren.", completion = "Gut. Lasst uns mit dem Begräbnis beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30821] = { id = 30821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Jutepfadmassaker", description = "So, jetzt ist es Zeit für Kota Kons \"Ausflug\".\n\nWir haben extra für sie zwei Kannen Kafa gekocht - jetzt ist sie startbereit!", sourceObjective = "Sprecht mit Kota Kon im Basislager am Kota, um sie reiten zu dürfen und 100 Ho-zen entlang des Jutepfades zu töten.", progress = "Kota Kon wartet auf Euch! Sie lässt sich nur von Euch reiten.", completion = "Ha, ha! Wir haben diese Affen selbst von hier noch schreien hören!\n\n<Buchsbaum wendet sich Kota Kon zu.>\n\nWas bist du nur für ein hübsches und braves Mädchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[30823] = { id = 30823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Rausch der Zägen", description = "Mein Vetter drüben beim Basislager am Kota hat es vermusselt. Er hat es schlimm vermusselt.\n\nEr war zu faul, um Samen von Hand aus Kafa-Beeren herauszuschneiden. Er hat festgestellt, dass Zägen die Beeren essen und die Samen zurückgeben... nach einem Tag oder so.\n\nEr hat alles, was er hatte, an die Zägen auf der Kotaspitze verfüttert, und jetzt sind sie verrückt! Sie greifen alles an, was sich bewegt.\n\nKota war sicheres Gebiet für Grummel zum Kafa-Sammeln. Nicht mehr. Nicht mit den Zägen. Werdet Ihr helfen?", sourceObjective = "Besiegt 12 Kafa-berauschte Bergziegen auf der Kotaspitze.", completion = "Danke für Eure Hilfe. Danke, dass Ihr meinen Fehler behoben habt, mein Freund. Lasst Euch dies eine Lehre sein: Füttert nie die Zägen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30824] = { id = 30824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gourmet-Kafa", description = "Das war eine verrückte Idee: Kafa-Beeren in Zäge, Samen kommen raus.\n\nKafa'kota ist schon selten und Vermögen wert, aber Erfindung von meinem Vetter - Kafa'zäge - ist GOURMET.\n\nAber das jetzt vorbei. Onkel Kühnbohn ist aufgeregt und Gipfel ist nicht sicher. Jetzt nur noch eins zu tun: Den Rest von Kafa'zäge sammeln und es nie wieder machen.\n\nIch bitte Euch nicht, es einzusammeln - keine schöne Aufgabe, nichts für Helden - markiert es einfach, damit wir es leichter finden, wenn der Berg wieder sicher ist.", sourceObjective = "Markiert 10 Kafa'zäge-\"Vorkommen\"\" auf der Kotaspitze.", completion = "Ich habe gehört, dass ein Abenteurer dort oben war und die Vorkommen markiert hat. Keine schöne Aufgabe für jemand mit Euren Fähigkeiten, aber ich weiß es zu schätzen.\n\nIch werde dort hoch gehen und... sie bald einsammeln.\n\n<Cousin Zägenfell fängt an, sich lange Leinenstreifen um die Hände zu wickeln.>\n\nKann nicht glauben, dass ich dachte, es wäre eine gute Idee.", sourceObjectiveStatus = "unverified-source-field" }
quests[30825] = { id = 30825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edle Kota-Mischung", description = "Kotaspitze ist berühmt für Kafa-Büsche. So weit oben kann nichts anderes wachsen.\n\nGrummel verdienen gutes Geld mit edle Kafa'kota-Mischung. Aber jetzt ist gefährlich. Schuld hat mein Vetter. Hat die Tiere da oben mit Kafa gefüttert und verrückt gemacht.\n\nKafa'kota seltener als je zuvor: Zägen fressen Kafa'kota auf. Yetis bringen Kafa'kota in ihre Höhlen.\n\nOnkel Kühnbohn bezahlt Euch gut für alle Beeren, die Ihr vom Kota holt.", sourceObjective = "Sammelt 100 Kafa'kota-Beeren auf der Kotaspitze. Ihr findet sie in den Büschen in den Bergen oder in den Yeti-Höhlen aufgehäuft.", sourceObjectiveStatus = "unverified-source-field" }
quests[30826] = { id = 30826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger braut sich zusammen", description = "Eine Menge Yetis in Kota, jepp. Normalerweise nicht gefährlich. Normalerweise essen nur Zägen.\n\nDann dummer Cousin Zägenfell drüben beim Basislager am Kota füttert Kafa an die Zägen und dann die Yeti fressen die Zägen.\n\nJetzt sind launisch, stinkig, schlafen viel, aber sind nie ausgeruht. Typische Kafasüchtige.\n\nKommen bald aus den Höhlen, ich bin sicher. Kommen und suchen nach mehr Kafa.\n\nDann wir alle haben Ärger.", sourceObjective = "Tötet 5 Kafa-berauschte Yetis in den Höhlen der Kotaspitze.", completion = "Ach, hallo! Humpen hat einen Yakboten geschickt, um uns zu sagen, dass Ihr uns bei unserem Yetiproblem helft.\n\nUnd Ihr seid nicht in kleine Stücke zerrissen! Yetis sind schon alleine hart - kann mir nicht vorstellen, wie ein stinkiger Kafa-süchtiger Yeti sein muss. Ihr seid mutig. Oder habt Glück. Oder seid dumm.\n\nVielleicht alles drei.", sourceObjectiveStatus = "unverified-source-field" }
quests[30827] = { id = 30827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten der Wahrheit", description = "Wenn ich mich nicht irre, hängt über diesem Ort eine anhaltende Finsternis.\n\nWas auch immer hier vorgefallen ist... es war jedenfalls kein natürliches Ereignis.\n\nNicht einmal die Yaungol sind brutal genug, um ihre eigenen Artgenossen auf diese Weise... abzuschlachten.\n\nIch werde mit den Totems, die Ihr mir gebracht habt, ein Läuterungsritual durchführen.\n\nIch brauche jemanden, der mir bei der Zeremonie hilft. Sagt Bescheid, wenn Ihr soweit seid.", sourceObjective = "Sprecht mit Yalia Weisenwisper, um die Zeremonie zu beginnen.\n\nAktiviert dann das Totem der Güte, das Totem der Gelassenheit und das Totem der Ruhe.", completion = "Wir blicken in das wahre Antlitz des Hasses!\n\nJetzt ergibt alles Sinn. Das ist das Werk des Sha.", sourceObjectiveStatus = "unverified-source-field" }
quests[30828] = { id = 30828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinigung des Weihers", description = "Es haben sich vor Kurzem im See Bereiche mit der trüben Substanz gebildet, die auch aus Mei herausgekommen ist.\n\nIch werde mit Euch dorthin reisen. Weist mir dann die Bereiche der Verderbnis, die ich reinigen soll.\n\nIhr müsst Euch um alles kümmern, was auch immer herauskommt, und mich schützen, solange ich das Ritual vollziehe.", sourceObjective = "Sucht Euch Lachen der Verderbnis am Tintenkiemenweiher und zeigt sie Wassersprecher Gorai, um ihn wissen zu lassen, dass Ihr bereit seid, ihn zu verteidigen, während er das Reinigungsritual vollzieht.", progress = "Ist der See gereinigt?", completion = "Der Weiher... Ich kann fühlen, wie die Verderbnis schwindet. Zumindest diese Verderbnis wird sich jetzt nicht mehr verbreiten.\n\nAber es gibt noch etwas, das wir tun müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30829] = { id = 30829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zunge von Ba-Shon", sourceObjective = "Unterstützt Lehrensucher Cho bei der Durchführung der Bindung von Ba-Shon.", progress = "Ich werde meine Essenz an die Zunge binden müssen, dann könnt Ihr sie verwenden könnt, um von überall aus mit mir zu sprechen.", completion = "Das muss ein sehr mächtiges Relikt sein, wenn Zuan es unbedingt zurückhaben will.\n\nIch schaudere bei dem Gedanken daran, was sie in den Gräbern noch finden könnten...", sourceObjectiveStatus = "unverified-source-field" }
quests[30834] = { id = 30834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusammenführung von Vater und Kind", description = "Sie haben überlebt? Mein Vater ist am Leben!\n\nIch dachte, wir würden alle hier in diesem schrecklichen Weiher durch die Hände dieser wahnsinnigen Jinyu sterben.\n\nIch werde selbst zurückfinden - trefft Euch mit mir beim Lager.", sourceObjective = "Kehrt zu Händler Shi und Wu-Peng an die südöstliche Küste von Tintenkiemenweiher am Kun-Lai-Gipfel zurück.", progress = "Mein Junge! Er ist am Leben!", completion = "Ihr habt ihn gefunden! Das ist alles, was ich Euch geben kann, aber indem Ihr meinen Sohn gefunden habt, habt Ihr es Euch mehr als verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[30855] = { id = 30855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall von Shai Hu", description = "Ich kann die Stimme des Weihers hören – er wurde gereinigt.\n\nAber dieses Kapitel in der Geschichte meines Volkes wird nie abgeschlossen sein – nicht, bis wir Shai Hu besiegt haben.\n\nEr hat sich auf die Insel in der Mitte des Weihers zurückgezogen und verderbt unsere heiligste aller Stätten.\n\nVorsicht – er ist stark. Aber nach allem, was wir getan haben, vertraue ich darauf, dass wir stärker sind.", sourceObjective = "Besiegt Shai Hu. Ihr findet ihn im Heiligtum des Wassersprechers, der Insel in der Mitte des Tintenkiemenweihers auf dem Kun-Lai-Gipfel.", completion = "Danke, {name}. Ihr habt sichergestellt, dass seine Verderbnis sich nicht weiter verbreitet und dass meine Leute - diejenigen, die nicht verdorben worden sind - weiterleben und ein neues Dorf gründen können. \n\nUnsere Geschichte wird weiterleben. Ihr habt mehr für uns getan, als wir uns je erhoffen hätten können.\n\nVielen Dank, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[30879] = { id = 30879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runde 1: Braumeisterin Chani", description = "Willkommen zu meinem Turnier der Champions, <Herausforderer/Herausforderin>! Heute stellen wir die Stärke der wagemutigsten Helden Pandarias auf die Probe.\n\nEure erste Gegnerin wartet beim östlichen Pavillon. Wenn Ihr sie besiegt, dürft Ihr mit der nächsten Runde fortfahren.\n\nKämpft im Namen der Stärke und Ehre.", sourceObjective = "Besiegt Braumeisterin Chani.", progress = "Ohne Widerstände gibt es keine Entwicklung.\n\nDie Notwendigkeit, sich zu verändern, beharrlich zu sein und zu improvisieren - das sind die Gründe, warum die Champions mich aufsuchen.", completion = "Gut gemacht, Herausforderer.", sourceObjectiveStatus = "unverified-source-field" }
quests[30880] = { id = 30880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runde 1: Die Straßenkämpferin", description = "Willkommen zu meinem Turnier der Champions, <Herausforderer/Herausforderin>! Heute stellen wir die Stärke der wagemutigsten Helden Pandarias auf die Probe.\n\nEure erste Gegnerin wartet beim östlichen Pavillon. Wenn Ihr sie besiegt, dürft Ihr mit der nächsten Runde fortfahren.\n\nKämpft im Namen der Stärke und Ehre.", sourceObjective = "Besiegt die Straßenkämpferin.", progress = "Ohne Widerstände gibt es keine Entwicklung.\n\nDie Notwendigkeit, sich zu verändern, beharrlich zu sein und zu improvisieren - das sind die Gründe, warum die Champions mich aufsuchen.", completion = "Gut gemacht, Herausforderer.", sourceObjectiveStatus = "unverified-source-field" }
quests[30881] = { id = 30881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runde 2: Der schlaue Ashyo & Ken-Ken", description = "Vielleicht kennt Ihr Eure nächsten Herausforderer schon. Als sie hier ankamen, haben sie sich fürchterlich gestritten. Also habe ich sie dazu verdonnert, Seite an Seite zu kämpfen.\n\nDas wird sie etwas über den Wert der Freundschaft lehren - und mich vielleicht ganz gut amüsieren.\n\nBegebt Euch in die nordöstliche Arena und stellt Euch dem Jinyu und dem Ho-zen.\n\nUnd zeigt keine Gnade. Die beiden sollen lernen, zusammen zu arbeiten.", sourceObjective = "Besiegt den schlauen Ashyo und Ken-Ken.", progress = "Stärke findet man in einem Verbündeten oder sich selbst.", completion = "Zu schade, dass die beiden ihre Lektion noch nicht gelernt haben. Aber egal. Eines Tages werden auch sie Weisheit erfahren.\n\nAber jetzt möchte ich Euch zunächst einmal zu Eurem Sieg gratulieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[30882] = { id = 30882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runde 2: Kang Dornstab", description = "Euer nächster Herausforderer ist ein Dornstab. Die Stärke liegt ihnen im Blut. Ich erinnere mich an ein Jahrhundert, in dem es ausschließlich Dornstab-Champions gab.\n\nAber nur keine Sorge, <kleiner/kleine:r> {race}.\n\nBegebt Euch einfach in die östliche Arena nördlich von hier und stellt Euch dem Herausforderer. Wir werden ja sehen, ob die Stärke angeboren ist oder erworben werden muss.", sourceObjective = "Besiegt Kang Dornstab.", progress = "Ich wurde ein Mal im Kampf von einem Dornstab besiegt. Aber zu meiner Verteidigung muss ich sagen, dass er mich mit einem Wollknäuel ablenkte.", completion = "Ah. Die Dornstab-Familie hält den Championtitel schon seit Generationen in ihrem Besitz. Und ich bin mir sicher, dass auch dieser Kandidat sich früher oder später den Titel sichern wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[30883] = { id = 30883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runde 3: Der Ringer", description = "Euer nächster Herausforderer ist einer meiner Lieblingskämpfer. Er bezieht seine Stärke aus purer Gewalt und wilder Entschlossenheit.\n\nUnd er trägt eine Maske.\n\nWenn Ihr bereit seid, wartet er in der Westlichen Arena auf Euch. Viel Glück.", sourceObjective = "Besiegt den Ringer.", progress = "Manchmal verleihen auch äußere Dinge Stärke.", completion = "Gut gekämpft, Herausforderer. Das war wirklich ein harter Gegner.", sourceObjectiveStatus = "unverified-source-field" }
quests[30884] = { id = 30884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter der Schlachtenfront", description = "Diese Schlachtenfront war schon während meiner Abwesenheit am Kun-Lai viel zu lange unterbesetzt und unzureichend versorgt. Wir müssen die Dinge hier ins Lot bringen, bevor wir die Spur des Sha des Hasses verfolgen können.\n\nTaoshi ist meine beste Kämpferin. Ich habe sie in den Norden entsandt, um Gerüchten auf den Grund zu gehen, denen zufolge es einige Mantis geschafft haben, die Schlachtenfront zu durchbrechen. Jemand muss ihr da draußen helfen, etwaige Löcher in unserer Verteidigung zu stopfen.\n\nWenn an den Berichten über Euch etwas dran ist, kann ich Euch die Sache wohl anvertrauen, was, {class}?", sourceObjective = "Sucht Taoshi bei der Feuchterdengrube auf.", completion = "Ihr seht fähig aus. Taran weiß, dass er mir nur die Besten schicken soll. Das gefällt mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[30885] = { id = 30885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runde 3: Meister Don-Don", description = "Euer nächster Herausforderer hat seine Stärke am Strand gefunden. Genauer gesagt in einer Kiste mit der Aufschrift \"Dynamit\".\n\nDamit beweist er, dass gefundene Stärke genauso tödlich sein kann wie persönliche Stärke.\n\nWenn Ihr bereit seid, wartet Meister Don-Don in der Westlichen Arena auf Euch.", sourceObjective = "Besiegt Meister Don-Don.", progress = "Manchmal verleihen auch äußere Dinge Stärke.", completion = "Gut gekämpft, Herausforderer. Das war wirklich ein harter Gegner.", sourceObjectiveStatus = "unverified-source-field" }
quests[30886] = { id = 30886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Example Pandaren Race Quest" }
quests[30887] = { id = 30887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwillkommene Eindringlinge", description = "Das dort unten sind Späher der Mantis. Die Gao-Ran-Front soll sie von der östlichen Tonlongsteppe fernhalten. Wenn wir sie in den Norden der Barrikade durchlassen, müssen wir womöglich unsere Präsenz hier aufgeben.\n\nBeseitigen wir sie. Ich komme mit Euch.", sourceObjective = "Tötet 12 Tiefenspäher der Krik'thik mit Taoshis Hilfe.", completion = "Hier kommen sie durch, am östlichen Pass.", sourceObjectiveStatus = "unverified-source-field" }
quests[30888] = { id = 30888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchbruch der Verteidigung", description = "Normalerweise reicht es, wenn ein paar Späher diesen Pass im Auge behalten. Der Großteil dieses Gebiets ist in Sichtweite des Walls; Bogenschützen würden also sämtliche Mantistruppen vernichten, die hier den Durchbruch wagen würden. Nur haben die meisten Bogenschützen bereits alle Hände voll mit den Angreifern am Tor zu tun.\n\nNehmt dieses Leuchtfeuer - damit werdet Ihr die Mantis, die sich am östlichen Pass an unseren unterbesetzten Wachposten vorbeischleichen, leichter aufspüren. Tötet alle, die Ihr findet. Wir können nicht zulassen, dass sie eine Fährte legen, die die Mantisschwärme weiter in die Steppen lotst.", sourceObjective = "Setzt das Leuchtfeuer der Shado-Pan als Hilfsmittel beim Töten von 10 Fährtenlegern der Krik'thik.", completion = "Es kommen mehr durch, als ich dachte. Es kann sein, dass ich noch eine Weile hierbleiben muss, um aufzuräumen.\n\nDoch Ihr habt mehr als Euren Teil beigetragen, {class}. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[30889] = { id = 30889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen stellen", description = "Freut mich, Euch zu sehen, {class}. Wir haben überall entlang des Passes Fallen aufgestellt, um Mantis zu fangen, die durchzuschlüpfen versuchen. Es sind aber so viele, dass die meisten Fallen bereits ausgelöst wurden.\n\nTaoshi meinte, Ihr könntet vielleicht einige davon neu stellen, während Ihr dort draußen seid. Könnt Ihr helfen?", sourceObjective = "Ladet 8 Shado-Pan-Stachelfallen neu.", completion = "Wir könnten im Lager gut noch ein paar fähige Männer wie Euch brauchen. Vielen Dank für Eure Hilfe, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30890] = { id = 30890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ruhelose Wache", description = "Ich habe gehört, dass unsere Späher am Flachsteigpass seit mehr als 2 Tagen durchgehend im Einsatz sind. Kein Wunder, dass Mantis durchschlüpfen können. Selbst den engagiertesten Spähern unterlaufen bei solchen Schichten Fehler.\n\nIch will, dass Ihr Euch da hinausbegebt und den Spähern den Befehl überbringt, unverzüglich zur Schlachtenfront zurückzukehren, um sich auszuruhen und Verpflegung zu fassen. Ich werde eine neue Schicht einsetzen lassen.", sourceObjective = "Überbringt Späher Wei-Chin, Späherin Long, Späherin Ying und Späher Jai-gan den Rückkehrbefehl.", progress = "Die gesamte Schlachtenfront ist völlig überarbeitet. Wir brauchen hier draußen mehr Männer.", completion = "Vielen Dank. Die neuen Späher werden in Kürze ihre Posten einnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30891] = { id = 30891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilung für die Truppen", description = "Ein neues Gesicht! Freut mich, Euch kennenzulernen. Ich heiße Septi. Ich sorge dafür, dass die Shado-Pan weiterkämpfen können.\n\nDie Mantis verfügen über ein Gift, das sich durch die Haut frisst und das Blut infiziert. Unbehandelt führt das zu einem langsamen, qualvollen Tod.\n\nIch brauche Pollen von Zitronenveilchen. Der nächste Ort, an dem Ihr welche findet, ist in der Umgebung der Feuchterdengrube im Norden der Schlachtenfront. Falls Ihr sowieso in diese Richtung unterwegs sein solltet, könntet Ihr mir welche mitbringen?", sourceObjective = "Sammelt 10 Zitronenveilchen.", progress = "Wenn man sie richtig zusammenmischt, tragen die Pollen dieser Blumen das Gift ab, ohne dem Körper andere bleibende Schäden zuzufügen.", completion = "Fabelhaft. Und in gutem Zustand!\n\nDanke für Eure Güte, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30892] = { id = 30892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wieder auf den Beinen", description = "{name}, ich könnte Eure Hilfe gebrauchen. Wegen ihrer langen Schichten kämpfen unsere Krieger unten an der Südfront der Schlachtenfront bis zur Erschöpfung, und viele von ihnen haben das Gift der Mantis zu spüren bekommen.\n\nWir brauchen mehr Leute, die sich um die Verwundeten kümmern. Ich habe mit den Kräutern, die Ihr mir gebracht habt, ein paar Verbände vorbereitet, wenn Ihr aber Heilfertigkeiten besitzt, könnten sich diese als noch wirksamer erweisen.\n\nBitte {name}, geht und sorgt dafür, dass unsere Männer wieder auf die Beine kommen, damit sie hierher in Sicherheit zurückkehren können.", sourceObjective = "Heilt 8 verletzte Gao-Ran-Schwarzwachen.", completion = "So manch ein Krieger verdankt Euch sein Leben. Seid Euch meiner tiefsten Anerkennung gewiss, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30893] = { id = 30893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der unendliche Schwarm", description = "Die Männer von Gao-Ran unten an der südlichen Front brauchen Hilfe. Wenn Ihr den Shado-Pan zur Seite stehen wollt, dann solltet Ihr ihnen helfen.", sourceObjective = "Tötet 12 angreifende Krik'thik an der Gao-Ran-Front.", completion = "Die Männer der Schlachtenfront fangen an, Euch zu respektieren. Ihr wisst offenbar, wie man kämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[30894] = { id = 30894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stöbern in Überresten", description = "Ich habe eine weitere Aufgabe für Euch, {name}, allerdings eine trostlose. Ich muss diesem Mantisgift auf den Grund gehen, dafür brauche ich aber Informationen direkt von der Quelle.\n\nKönntet Ihr mir ein paar Mantisbeine vom südlichen Schlachtfeld zurückbringen, damit ich ihre intakten Giftdrüsen genauer untersuchen kann?", sourceObjective = "Besorgt 20 Krik'thik-Beine.", progress = "Ich hoffe, ein anhaltendes Gegenmittel für das Mantisgift zu finden, damit die Männer nicht mehr davon vergiftet werden. Die Herstellung könnte etwas dauern.", completion = "Die sind sehr gut erhalten! Danke, {name}!\n\nEs ist mir gelungen, etwas von ihrem Gift in eine Form zu destillieren, die wir leicht verabreichen können. Ich habe sogar Methoden entwickelt, wie man es in das Wirken von Zaubern einweben kann. Möchtet Ihr es gern ausprobieren?", sourceObjectiveStatus = "unverified-source-field" }
quests[30895] = { id = 30895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Provisorische Munition", description = "Ich habe noch einen Auftrag für Euch.\n\nDen Drachenkanonen, auf die wir angewiesen sind, um die dichteren Schwärme der Mantis abzuwehren, geht die Munition aus. Die Kanoniere des Lagers haben einen provisorischen Sprengstoff entwickelt, der aus den Globussamen auf der westlichen Seite des Kamms hergestellt wird.\n\nSie haben vor einigen Stunden ein paar Initianden ausgesandt, um welche holen zu gehen, aber haben seitdem nichts mehr von ihnen gehört. Jetzt hätte ich gerne, dass jemand Fähigeres dafür sorgt, dass die Sache erledigt wird.\n\nSeid Ihr <der Mann/die Frau> dafür?", sourceObjective = "Sammelt 16 explosive Schreckenskugeln in den Bernmarschen.", progress = "Schneller als ich erwartet hätte. Bringt Ihr die Samen?", completion = "Gut, ein {class}, auf den man sich verlassen kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[30896] = { id = 30896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diebe und Unruhestifter", description = "Ich kann die kleinen Biester beim besten Willen nicht erwischen.\n\nTötet alle, die Ihr in die Hände bekommt. Und passt auf Eure Wertgegenstände auf, sie klauen nämlich alles, was nicht niet- und nagelfest ist.", sourceObjective = "Tötet 10 aufgeregte Nesselhäute.", progress = "Ich habe Pflanzen seit meinem Auftrag in Halbhügel nicht mehr so sehr gehasst.", completion = "Ihr seid wohl etwas schneller als ich. Danke jedenfalls.\n\nIch werde ein paar Kugeln zu sammeln versuchen und sie ins Lager zurückbringen, solange ich noch die Chance habe, mein Gesicht zu wahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[30897] = { id = 30897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In falschen Händen", description = "Hört zu... ähm... es ist mir wirklich peinlich. Aber ich habe mein Schwert für gerade mal EINE SEKUNDE abgesetzt, um ein paar Kugeln zu sammeln, und schon tauchte so ein fetter Waldgeist aus dem Nichts auf und schnappte es sich, um damit in der Schlucht im Westen zu verschwinden.\n\nOhne kann ich nicht zurück zum Lager. Seine Waffe zu verlieren ist Garantie dafür, von den Shado-Pan hinausgeworfen zu werden. Sie ist ihnen heilig.\n\nBitte, könnt Ihr diesen dicken Waldgeist aufspüren und mein Schwert zurückholen? Es würde mir so viel bedeuten.", sourceObjective = "Bergt Initiand Xaos Schwert.", progress = "Meine Mama hat mich schon davor gewarnt...", completion = "Ihr... Ihr seid die Rettung! Im Ernst.\n\nVielen, vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[30898] = { id = 30898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausdünnen des Schwarms", description = "Die Mantis haben zugenommen, als Ihr zur Kluft aufgebrochen seid. Setzen wir also diese Kugeln, die Ihr gesammelt habt, zu unserem Vorteil ein.\n\nGeht runter zur Schlachtenfront und bemannt eine der Kanonen. Lasst niemanden durch.", sourceObjective = "Benutzt eine Drachenschleuder, um 50 schwärmende Mantis zu töten.", progress = "Ich kann mich nicht erinnern, schon einmal so dichte Schwärme gesehen zu haben. Zu meinen Lebzeiten scheint es das nicht gegeben zu haben.", completion = "Wir sind noch nicht fertig...", sourceObjectiveStatus = "unverified-source-field" }
quests[30899] = { id = 30899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In besten Händen", description = "{name}, nehmt diese Armbrustbolzen und bringt sie zu Falkenmeister Nurong an der Weitblickwarte im Südwesten.\n\nNurong wird unter den Wukao als unfehlbarer Schütze gefeiert. Seinen Bemühungen soll es zu verdanken sein, dass die Linien hier all die Monate standgehalten haben. Ich hoffe, dass Ihr mit ihm zusammenarbeiten könnt, um das selbst zu beurteilen. Vielleicht ist er der erste Shado-Pan, den wir für die Jagd gebrauchen können.", sourceObjective = "Bringt das Armbrustbolzenbündel der Shado-Pan zu Falkenmeister Nurong.", progress = "Eine weitere Welle fliegender Angreifer bricht herein. Macht Euch bereit.", completion = "Auf der anderen Seite der Schlucht scheint sich einiges zu tun... Da braut sich etwas ganz Großes zusammen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30900] = { id = 30900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißel der Schreckensöde", description = "Das Ding ist ja riesig!\n\nFür so etwas sind die Shado-Pan, die die Schlachtenfront halten, nicht ausgebildet... Gehen wir hinunter und setzen es selbst außer Gefecht.", sourceObjective = "Bezwingt Norvakess, die Geißel der Schreckensöde.", completion = "Ihr da. Ihr kommt mit mir.\n\nIch habe noch nie jemanden getroffen, der sich auf dem Schlachtfeld so wie Ihr verhalten hat. Ich brauche jemand Starkes wie Euch an meiner Seite, {class}, wenn wir uns dem Sha des Hasses entgegenstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30901] = { id = 30901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entlang der Südfront", description = "Ich werde mit Taoshi gen Westen ziehen, um die Stärksten, die ich finden kann, um mich zu scharen und den Kampf zum Sha des Hasses zu tragen.\n\nIch möchte, dass Ihr mich begleitet.", sourceObjective = "Reitet mit Taran Zhu und Taoshi zum Dämmerlichtstumpf.", completion = "Sehen wir zu, dass die Sache geregelt wird, damit wir zur Brücke hinunterkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30902] = { id = 30902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runde 4: Meister Windpelz", description = "Gut gemacht, <Herausforderer/Herausforderin>. Ihr habt die letzte Runde erreicht.\n\nEuer letzter Gegner ist ein mächtiger Herrscher über die Winde. Er hat sein Volk über viele Jahre beschützt und sich mehr als ein Mal als wahrer Champion bewiesen.\n\nWenn Ihr bereit seid, wartet Meister Windpelz in der Hauptarena auf Euch.\n\nIch wünsche Euch viel Glück, <Herausforderer/Herausforderin>...", sourceObjective = "Besiegt Meister Windpelz.", progress = "Die Stärke von Meister Windpelz liegt in der Luft und den Winden, die ihn umwehen. Er herrscht über die mächtigen Kräfte der Elemente.", completion = "Ich gratuliere Euch, Champion! Heute ist Euer Ehrentag.", sourceObjectiveStatus = "unverified-source-field" }
quests[30907] = { id = 30907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runde 4: Drei gegen einen", description = "Und jetzt zur letzten Runde. Ich habe dazu gleich drei Herausforderer für Euch ausgewählt. Das könnte unfair erscheinen... aber nur für einen Schwächling. Und Ihr seid doch kein Schwächling, oder?\n\nBegebt Euch in die große Arena im Haupttempel und stellt Euch diesen drei Herausforderern. Zeigt, dass Ihr über mehr Kraft verfügt als die drei zusammen!\n\nViel Glück, <Herausforderer/Herausforderin>!", sourceObjective = "Besiegt Hackiss, Heiliss und Tankiss.", progress = "Einige beziehen Stärke aus der Anzahl. Bei richtiger Anwendung kann ich dies respektieren.", completion = "Fabelhaft! Was für eine Schlacht!\n\nIhr habt Euch als Turnier-Champion des heutigen Tages erwiesen. Gut gemacht!\n\nBitte kommt auch in Zukunft wieder, um Eure außergewöhnliche Stärke zu demonstrieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[30910] = { id = 30910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grünstein", description = "Bitte helft uns!\n\nWir haben einige Abenteurer bezahlt, um die ganzen Elementargeister zu verjagen, und nun sind sie wieder da und wollen sich rächen!", sourceObjective = "Rettet alle Dorfbewohner.", sourceObjectiveStatus = "unverified-source-field" }
quests[30918] = { id = 30918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huis Rache", description = "Es ist mir etwas peinlich, aber um Grünsteins willen... dürften wir Euch wohl bitten, Euch in unserem Namen jetzt dem Rachsüchtigen Hui entgegenzustellen...?", sourceObjective = "Besiegt den Rachsüchtigen Hui.", sourceObjectiveStatus = "unverified-source-field" }
quests[30921] = { id = 30921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Motive der Mantis", description = "{class}. Ihr könntet uns nützlich sein.\n\nDie Shado-Pan möchten wissen, weshalb die Mantis so ungestüm angreifen. Wir haben unsere Vermutungen, sind uns allerdings nicht sicher. Außerdem sollen die Mantis nicht herausfinden, dass sie von uns untersucht werden.\n\nUnd hier kommt Ihr ins Spiel.\n\nIch möchte, dass Ihr die Mantis von Kri'vess im Norden tötet. Ich werde mich hinter Euch im Schatten versteckt halten und ihre Leichname auf Hinweise untersuchen.", sourceObjective = "Erschlagt Mantis in Kri'vess, damit Tai Ho ihre Leichname auf Hinweise untersuchen kann.", completion = "Die vielen Yakhaare am Körper dieses Mantis deuten auf eins hin... er ist vom Niuzaotempel gekommen. Wir setzen unsere Reise Richtung Westen fort, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30922] = { id = 30922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Natürliches Antiseptikum", description = "Die Shado-Pan sind selten, elitär und ziemlich teuer in der Ausbildung und daher nur schwer zu ersetzen. Wir können uns nicht leisten, dass auch nur einer von ihnen einer vergifteten Waffe oder einem infizierten Schnitt zum Opfer fällt. Deshalb möchte ich, dass Ihr mir... etwas besorgt.\n\nLasst es mich klar und deutlich aussprechen. Der Urin der Mushan ist ein großartiges, natürliches Antiseptikum. Zum Glück erzeugen sie eine Menge davon... wir brauchen nämlich in der Regel viel.", sourceObjective = "Sammelt 5 volle Mushanblasen.", progress = "Stimmt schon, das ist eine schmutzige Arbeit.\n\nAber bei Weitem nicht so schmutzig wie Gräber ausheben.", completion = "Eure schmutzige Arbeit hat heute möglicherweise das eine oder andere Leben gerettet, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30923] = { id = 30923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Rückschlag für die Mantis", description = "Mit jedem Tag vergrößern die Mantis die Munitionsvorräte, die sie gegen ihre Feinde einsetzen wollen, weiter. Wir können sie nicht aufhalten, Ihr und ich... aber einen Rückschlag können wir ihnen doch verpassen.\n\n<Tai Ho gibt Euch etwas Sprengstoff.>\n\nIch muss mich bedeckt halten. Wärt Ihr so gut?", sourceObjective = "Benutzt Schwarzpulverfässer, um die Krik'thik-Waffen und -Vorräte in Kri'vess in die Luft zu sprengen.", completion = "Wir stehen in Eurer Schuld, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30924] = { id = 30924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niuzaos Weisheit", description = "Niuzao der Schwarze Ochse ruht sich im Tempel im Westen aus. Er weiß vielleicht, warum die Mantis angreifen.\n\nEr weiß vielleicht sogar viel mehr als das.\n\nIch werde am Niuzaotempel zu Euch stoßen, {class}.", sourceObjective = "Sprecht mit Ogo dem Jüngeren am Niuzaotempel in der Tonlongsteppe.", completion = "Euer Shado-Pan-Genosse hat sich mit mir unterhalten. Ja, Niuzao weiß, weshalb die Mantis angreifen. Er ist aber nicht bereit, es Euch zu erzählen.\n\nNoch nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[30925] = { id = 30925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niuzaos Preis", description = "Niuzao ist der Besitzer einer Statuette, die er über alles schätzt: eine kleine Ikone nach seinem Ebenbild, gemeißelt von einem seiner vor langer Zeit gefallenen Wächter. Diese Statuette wurde vor Kurzem von den Sra'thik-Mantis gestohlen und in ihr Lager nördlich von hier gebracht.\n\nBringt die Statuette zurück. Dann geben wir Euch - und Eurem Shado-Pan-Genossen - die Antworten, die Ihr begehrt.", sourceObjective = "Tötet die Mantis des Übergriffs der Sra'thik, damit Tai Ho ihre Leichen nach Teilen von Niuzaos Statuette durchsuchen kann.", completion = "Niuzao wird sich freuen.\n\nTrotz seiner Körpergröße ist unser Schutzpatron ein anmutiges und mitfühlendes Geschöpf. Diese Figur war ihm viel wert... so, wie ihm jeder einzelne seiner Anhänger viel wert ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[30926] = { id = 30926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die schreckliche Wahrheit", description = "Schweren Herzens bestätige ich Eure Vermutungen. Die Mantis stehen tatsächlich unter der Herrschaft des Sha der Angst.\n\nEs war UNSERE Pflicht, diese Kreatur unter unserem Tempel festzuhalten. Unglücklicherweise ließ unsere Wachsamkeit nach, unsere Verteidigung brach zusammen und das Sha konnte entkommen. Es ist jetzt bei den Mantis.\n\nÜberzeugt Euch selbst. Die Mantis haben sich zur westlichen Seite unserer Insel durchgewühlt.", sourceObjective = "Untersucht die Niuzaokatakomben und erlegt den Schreckensschatten, der in ihrem Inneren haust.", completion = "Lasst mich eins klarstellen: Diese Kreatur war nicht das Sha der Angst, sondern nichts weiter als ein Schatten... ein Bruchteil der wahren Macht des Sha.\n\nNein, das Sha der Angst ist jetzt bei den Mantis. Die Ältesten meines Ordens müssen unverzüglich davon in Kenntnis gesetzt werden.\n\nDen Rest werde ich übernehmen. Vielen Dank für Eure Hilfe, {race}. Einmal mehr erweist sich Euresgleichen als Gewinn für Pandaria.", sourceObjectiveStatus = "unverified-source-field" }
quests[30927] = { id = 30927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dass sie in Frieden ruhen mögen", description = "Ich habe es schon gehört. Unser Geheimnis ist also gelüftet.\n\nAls ich erfuhr, dass die Mantis sich unter unserem Tempel vergraben hatten, reagierte ich vorschnell. Ich entsandte Dutzende von Wächtern, damit sie verteidigen, was sie können, aber sie waren unvorbereitet. Sie wurden von Angst übermannt und kehrten nie wieder.\n\nEin Pandaren verdient es, die Erde umarmend zu sterben, so wie er es im Schlaf tut... nicht auf dem Rücken, den Blick starr vor Angst. Bitte, {name}. Gewährt ihnen den Frieden, den sie verdienen.", sourceObjective = "Gewährt 10 Angsterfüllten Schildwachen Frieden, indem Ihr ihre Augen schließt und sie auf den Bauch dreht.", completion = "Danke, {class}.\n\n\n\nWäre ich nur dabei gewesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30928] = { id = 30928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spur der Angst", description = "Jetzt kennt Ihr das Geheimnis von Niuzao. Wir sind nicht nur die Wächter dieses Tempels... wir waren die Wächter des Sha der Angst, das darunter begraben lag.\n\nDas Sha selbst mag entkommen sein... doch es hat Spuren hinterlassen. Wenn Ihr Euch wirklich in die Katakomben hinunterwagen wollt, solltet Ihr diese Spuren beseitigen, bevor auch sie entkommen und noch größere Probleme verursachen, als wir sie ohnehin schon haben.", sourceObjective = "Tötet 12 Schrecklinge in den Niuzaokatakomben.", completion = "Wir haben schon die Mantis, die Mogu und die Yaungol, die uns das Leben schwer machen. Dieses Problem mit dem Sha muss im Keim erstickt werden, bevor wir überrumpelt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[30929] = { id = 30929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbrauchbares Yak", description = "Kann man hier unbrauchbare Yaks eintauschen?\n\nKann mir hier wohl jemand weiterhelfen?", sourceObjective = "Helft Blausattel, Ersatz für sein unbrauchbares Yak zu bekommen.", progress = "Dieses Yak ist kein gutes Yak. Ganz und gar nicht", completion = "Ich glaube, unsere Argumente sind überzeugend genug. Jetzt MÜSSEN sie mein Yak ersetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30930] = { id = 30930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Qual der Yakwahl", description = "Ich finde einfach kein einziges gutes Yak hier. ALLE Yaks sind unbrauchbar!\n\nDie einen stinken zu sehr, andere sind zu kampflustig oder einfach zu verängstigt.\n\nIhr seht mir wie ein Glückspilz aus, {race}. Hier, nehmt ein Lasso. Seht zu, ob Ihr ein gutes Yak für mich finden könnt.", sourceObjective = "Fangt mit dem Yaklasso wilde Tonlongyaks ein und kämpft dann gegen sie, um herauszufinden, ob sie für Blausattel geeignet sind.", progress = "Na, seht Ihr? Habe ich es nicht gesagt? Keine brauchbaren Yaks.", completion = "Nun sieh mal einer an! Ein gutes Yak!\n\nIch sag Euch was, {name}. Ich nehme dieses GUTE Yak und Ihr macht mit dem völlig unbrauchbaren hier, was Ihr wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30931] = { id = 30931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Armbrust meines Vaters", description = "Ich kam hierher, um meinen Vater im Tempel zu besuchen. Gleich nach meiner Ankunft erblickte ich das grässlichste Wesen, das ich je zu Gesicht bekommen habe.\n\nEs war ein Mantis, der mit der Armbrust meines Vaters direkt an mir vorbeilief.\n\nMeinem Vater ist etwas zugestoßen! Wir müssen herausfinden, was... doch vorher brauchen wir seine Armbrust. Ich habe gesehen, wie er nach Westen gegangen ist, hinter den Tempel.", sourceObjective = "Besorgt Ku-Yaos Armbrust.", progress = "Habt... Ihr sie gefunden?", completion = "Ja, das ist Vaters Armbrust.\n\nGehen wir zum Tempel hinüber. Dort werden sie wissen, was...\n\n<Ku-Mos Stimme versagt.>\n\n...was ihm zugestoßen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[30932] = { id = 30932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Fußstapfen des Vaters", description = "Ja, der Vater des Jungen - Späher Ku-Yao - ist verschwunden. Er könnte an vielen verschiedenen Orten sein... Dieser Tage mangelt es uns nicht an Feinden.\n\nEs steht Euch frei, Euch nach Belieben umzusehen. Ihr könntet damit beginnen, nach seinem Yak zu suchen oder indem Ihr Späher Yalo fragt, was er weiß.", sourceObjective = "Findet das Futon des Vaters, den Schild des Vaters, Ha-Cha und Späher Yalo.", completion = "Kein Schild, keine Armbrust, kein Yak… Vater ist etwas Schlimmes zugestoßen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30933] = { id = 30933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach meinem Vater", description = "Ich habe überall gesucht... aber ich kann meinen Vater nicht finden. Ich WEISS, dass er noch am Leben ist. Er braucht bloß seine Armbrust... dann ist alles in Ordnung.\n\nIch habe gehört, dass Ihr von den Shado-Pan manchmal auf Sra'vess gegen die Mantis kämpft. Ich habe keine Möglichkeit, da hinzukommen. Wenn Ihr da hingeht, könntet Ihr nach meinem Vater sehen?", sourceObjective = "Sucht nach Späher Ku-Yao.", completion = "<Ku-Mo scheint Euch nicht wahrzunehmen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[30935] = { id = 30935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geschichte des Fischers", description = "Die Dorfbewohner von Zouchin kennen die Küste besser als sonst jemand am Kun-Lai-Gipfel. Wenn sich die Zandalari auf einer der Inseln verstecken, werden sie es wissen.\n\nMishi bringt Euch bis zum Pfad der Eroberer. Ich gehe voraus, um mit den Dorfältesten zu sprechen.\n\nFolgt dem Pfad bis zur Flüsterwolkenhöhe. Shin Flüsterwolke wird Euch helfen, das Dorf zu erreichen.", sourceObjective = "Sprecht mit Mishi, um zum Pfad der Eroberer zu reisen. Von dort aus sucht Shin Flüsterwolke bei der Flüsterwolkenhöhe auf.", completion = "Wir müssen herausfinden, wo die Zandalari die Überreste des Donnerkönigs versteckt haben. Die Ältesten haben beschlossen, uns dabei zu helfen.\n\nSie stellen allerdings einige Bedingungen...", sourceObjectiveStatus = "unverified-source-field" }
quests[30942] = { id = 30942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich will kämpfen!", description = "Pscht! Sprecht nicht so laut! Mein Vater könnte Euch hören.\n\n<Shomi zeigt auf Stahlbieger Doshu.>\n\nMein Vater ist nicht bei Trost! Er ist der Meinung, ich solle üben, wie man Tee ausschenkt, dabei wird unser Dorf angegriffen. Es ist lächerlich! Ich habe ebenso viel Mut wie jeder Mann. Ich weiß nur nicht, wie man kämpft...noch nicht.\n\nDa kommt Ihr ins Spiel. Lasst mich mit Euch ziehen! Ich lerne schnell und werde nicht im Weg sein, versprochen!\n\nBitteeeee!\n\nWenn wir getrennt werden, treffe ich Euch im Dorf wieder.", sourceObjective = "Tötet 4 Scharmützler der Amani, 4 Verhexer der Gurubashi und 3 Frostweber der Drakkari in der Provinz Zouchin.", progress = "Ich werde meinem Vater beweisen, dass er mich unterschätzt hat!", completion = "Ich sagte Euch ja, dass ich schnell lerne! Ich werde zurück in mein Dorf eilen und andere ausbilden. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30943] = { id = 30943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ganz. Vorsichtig.", description = "Ich habe die Zahlen dieser Eindringlinge gesehen. Das wird kein einfacher Sieg. Eine Sache fällt mir jedoch ein, mit der wir uns einen Vorteil verschaffen können.\n\nUm das Dorf herum wächst eine Pflanze, mit der man eine ziemlich explosive Flüssigkeit herstellen kann. Wenn Ihr genügend sammeln könnt, kann ich damit beginnen, die Mixtur herzustellen.\n\nDie Pflanze, nach der Ihr sucht, heißt passenderweise Zunderblüte. Geht vorsichtig damit um.", sourceObjective = "Bringt dem Ältesten Shu 50 Zunderblüten.", progress = "Habt Ihr eine angemessene Anzahl Zunderblüten gefunden?", completion = "Die sind perfekt! Jetzt würde ich mir an Eurer Stelle ein paar Mal die Hände waschen, {class}.\n\nIch würde auch offene Flammen für einige Tage meiden...", sourceObjectiveStatus = "unverified-source-field" }
quests[30944] = { id = 30944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Man braucht ein Dorf", description = "Unsere Dorfbewohner bewachen Zouchin seit dem ersten Angriff. Sie sind erschöpft und viele von ihnen sind verletzt.\n\nWenn die Zandalari erneut angreifen, können wir es uns nicht erlauben, dass unsere Verteidiger während ihrer Wache einschlafen. Löst sie ab, sodass sie sich erholen und ihre Familien sehen können.\n\nSie sind rund ums Dorf stationiert.", sourceObjective = "Löst die erschöpften Verteidiger von ihren Wachtposten ab.", completion = "Sehr gut, {class}! Jetzt, da die Dorfbewohner erholt sind, haben wir vielleicht eine Chance gegen die Zandalari.", sourceObjectiveStatus = "unverified-source-field" }
quests[30945] = { id = 30945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was Euer ist, ist mein", description = "Die Ältesten möchten also, dass wir die Verteidigung übernehmen? Wir sind keine Mönche, {class}; wir brauchen Waffen, damit wir im Kampf eine Chance haben!\n\nErbeutet für mich ein paar der Waffen dieser Barbaren. Ich sollte sie einschmelzen und zu etwas Passenderem für unsere Dorfbewohner verarbeiten können.\n\nBringt mir so viele Ihr tragen könnt und ich kümmere mich um den Rest.", sourceObjective = "Holt 6 gestohlene Waffen von den Eindringlingen der Zandalari zurück.", progress = "Wir brauchen mehr als nur Glück, um das zu überstehen. Ich hoffe, dass Ihr etwas Brauchbares gefunden habt.", completion = "Die sind ja besser als erhofft! Ich kann für jede ihrer Klingen vier Speere herstellen.\n\nMacht Euch keine Sorgen. Die Dorfbewohner werden bewaffnet sein, wenn es soweit ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[30946] = { id = 30946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enthüllungen", description = "Der Gefangene befindet sich im oberen Stockwerk, {name}. Es wird nicht einfach sein, Informationen aus ihm herauszubekommen, aber selbst das kleinste Detail über ihren Aufenthaltsort ist hilfreich.\n\nDie Ältesten haben bereits begonnen, ihn zu befragen. Mit ihrer Hilfe sollten wir unseren nächsten Schritt planen können.\n\nSprecht mit dem Gefangenen und findet heraus, ob er nützliche Informationen für uns hat.", sourceObjective = "Sprecht mit dem zandalarischen Gefangenen.", progress = "Was hatte der Gefangene zu sagen?", completion = "Wir dürfen das nicht als Niederlage betrachten, {name}, der Prophet Khar'zul muss ausgeschaltet werden.\n\nJeder Unterstützer des Donnerkönigs, den wir aus dem Weg räumen, bringt uns dem Sieg einen Schritt näher.", sourceObjectiveStatus = "unverified-source-field" }
quests[30952] = { id = 30952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die endlose Belagerung", description = "Die Mantis setzen ihre Angriffe auf uns fort. Mal sind es mehr, mal weniger, doch sie hören nie auf.\n\nDas tut nichts zur Sache. Das Yak ist der Inbegriff der Ausdauer. Wir werden uns ihnen nicht beugen. Wir werden seine Heimat auf ewig verteidigen.\n\nWerdet Ihr uns helfen?", sourceObjective = "Besiegt 12 Angreifer der Sra'thik im Niuzaotempel.", completion = "Ihr kämpft, als wärt Ihr einer von uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[30953] = { id = 30953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefallene Bewacher", description = "Unsere Bewacher können tagelang ohne Unterbrechung kämpfen, doch auch ihre Belastbarkeit hat Grenzen. Seit der Mantisschwarm aufgetaucht ist, haben sich schon zu viele von ihnen übernommen.\n\nBitte helft ihnen, so gut Ihr könnt. Wenn Ihr sie nicht selbst heilen könnt, verabreicht ihnen etwas hiervon. Ein Schluck nahrhafte Yakmilch wird ihnen die Kraft geben, die sie brauchen.", sourceObjective = "Heilt 8 verwundete Niuzaobewacher, bis jeder mindestens 50% Gesundheit erreicht hat. Ihr könnt dabei die Yakmilchflaschen oder Eure eigenen Heilfähigkeiten einsetzen.", completion = "In Zeiten wie diesen müssen wir in die Macht und den Schutz Niuzaos vertrauen. Wenn sich die Lage verschlimmert, wird er uns beschützen.\n\nDas tut er immer.", sourceObjectiveStatus = "unverified-source-field" }
quests[30954] = { id = 30954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge ist eine Klinge", description = "Dies ist nicht der Zeitpunkt, um an Traditionen festzuhalten. Die schwieligen Hände unserer Steinmetze bluten und zittern. Unsere Schmiede können Waffen nicht so schnell herstellen, wie unsere Schildwachen sie verschleißen.\n\nJetzt gilt es, mit Bedacht zu kämpfen.\n\nViele der Mantis tragen Waffen, die bei ihrem Tod einfach auf dem Schlachtfeld liegen bleiben. Es wäre doch eine Schande, das nicht auszunutzen.", sourceObjective = "Nehmt 10 Sra'thik-Waffen an Euch.", progress = "Unsere Männer sind es gewohnt, mit Kolben und Keulen zu kämpfen. Leider haben wir nicht die Zeit, alte Bräuche zu pflegen.", completion = "Ich werde dafür sorgen, dass sie ordnungsgemäß verteilt werden und außerdem sicherstellen, dass unsere Schmiede sich etwas erholen können. Niuzao weiß, sie verdienen es.", sourceObjectiveStatus = "unverified-source-field" }
quests[30955] = { id = 30955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tribut zollen", description = "Unser Schutzpatron Niuzao ist ein Berg auf Rädern... ungemein schwer zu bewegen und noch schwerer aufzuhalten. Was ich damit sagen will: Wenn wir ihn erst in Bewegung bringen, werden die Mantis alle Mühe haben, ihn wieder zu stoppen.\n\nAm einfachsten bringt man ihn dazu, sich zu bewegen, indem man ihm Essen vorsetzt. Zum Glück haben wir massenhaft Essen in unserem Tempel... selbst zu Kriegszeiten.\n\nIch werde Euch einen von meinen Kraftprotzen mitgeben, um die Last zu tragen.", sourceObjective = "Besorgt 6 Lebensmittelvorräte von Niuzao. Euer Niuzaokraftprotz wird die Lebensmittel für Euch tragen.", progress = "Bitte, Niuzao... es ist Zeit zum Kämpfen...", completion = "Er wird aufstehen. Bald. Vielleicht nicht mehr heute, aber bald.\n\nUnd dann...\n\n<Auf Paoshas Gesicht macht sich ein Lächeln breit.>", sourceObjectiveStatus = "unverified-source-field" }
quests[30956] = { id = 30956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Belagerung wird stärker", description = "Der Mantisschwarm von heute gehört zu den schlimmsten Dingen, die ich je gesehen habe. Ein Glück, dass wir Niuzao für die Schlacht haben.\n\nHelft ihm, {class}. Kehrt in den Hof zurück und helft bei der Verteidigung unseres Tempels.", sourceObjective = "Bezwingt 25 Angreifer der Sra'thik im Niuzaotempel.", completion = "Seht ihn Euch an, {class}.\n\nNiuzao ist unaufhaltbar. Nur Niuzao kann Niuzao stoppen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30957] = { id = 30957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der überwältigende Schwarm", description = "Ich kommandiere die Schildwachen von Niuzao. Jeder Verteidiger dort draußen kann es selbst mit dem Mantisschwarm aufnehmen.\n\nMit den Kunchong ist das allerdings eine andere Sache.\n\nSie sind riesig, brutal und zweifelsfrei die größte Bedrohung für das Leben meiner Schildwachen. Niuzao selbst ist der Einzige, der eine Chance gegen sie hat. Niuzao... und Ihr vielleicht.", sourceObjective = "Bezwingt 4 Kunchong der Sra'thik.", progress = "Seid standhaft, {race}. Die Kunchong würden sich gegen Euch durchsetzen.", completion = "Wenn Ihr unsere Rüstung anlegt, kann man Euch von den anderen Schildwachen dort draußen nicht mehr unterscheiden.\n\nViel Glück im Kampf, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30958] = { id = 30958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Schatten der Schlacht", description = "Niuzaos Erscheinen auf dem Schlachtfeld ist ein wahrer Segen... und nicht nur in einer Hinsicht.\n\nWegen der Ablenkung, die er geschaffen hat, konnten unsere Steinmetze sich an den Wiederaufbau unserer verfallenden Wälle machen. Sie könnten Eure Hilfe gebrauchen.\n\nWerft ihnen die lose herumliegenden Steine zu, die Ihr findet. Und beeilt Euch! Niuzao wird nicht ewig wüten.", sourceObjective = "Werft 10 Lose Steine zu den Niuzaosteinmetzen hinauf.", progress = "Ich lege Euch ans Herz, Euch zu sputen. Niuzaos Ablenkungsmanöver wird nicht ewig andauern.", completion = "Diese Wälle scheinen langsam wieder Formen anzunehmen. Schon bald wird der Tempel wieder errichtet sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[30959] = { id = 30959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwere Geschütze", description = "Die Mantis haben den Tempel jetzt mit ihren teuflischen Kriegswagen umringt. Je schneller wir diese Dinger loswerden, umso besser. Ihr könntet sie mit Euren eigenen Waffen und Zaubern zerstören, das hier wird aber schneller gehen.\n\n<Ogo überreicht Euch ein paar kleine Fässer mit schnell zusammengepacktem Sprengstoff.>\n\nNehmt Euch vor Gegenschlägen von Mantis in Acht, die sich bei der Explosion noch in ihren Kriegswagen aufhalten. Ich würde mich so weit wie möglich von diesen Dingern fernhalten.", sourceObjective = "Zerstört 3 Kriegswagen der Sra'thik.", completion = "Schön, Ihr seid heil wieder zurück.\n\nHoffentlich bekommen wir in Zukunft mehr von Euch zu sehen, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30960] = { id = 30960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr vom Pass", description = "Ich muss hier am Pass noch etwas aufräumen - es kommen noch immer Mantis durch. Euch zur Verfügung zu haben, ist praktisch, und ich weiß, dass es Taran nicht gefallen würde, wenn ich Euch noch länger mit solch einfacher Arbeit betraue.\n\nTaran ist vermutlich noch mit Gao-Ran im Hauptlager. Meldet Euch dort. Ich komme etwas später nach.", sourceObjective = "Meldet Euch bei Taran Zhu bei der Gao-Ran-Blockade.", completion = "Willkommen zurück. Ich habe von den Durchbrüchen am Pass im Osten gehört. Klingt, als hätte ich die richtigen Leute beauftragt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30961] = { id = 30961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retter der Tintenkiemen", description = "Ich werde nun gehen und zu meinen Angehörigen zurückkehren. Besucht uns bitte an der Südwestecke des Weihers, damit wir Euch danken können.", sourceObjective = "Sprecht mit Wassersprecher Gorai an der Südwestecke des Jinyuweihers.", sourceObjectiveStatus = "unverified-source-field" }
quests[30963] = { id = 30963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feldrüstungsschmied", description = "Die Shado-Pan kämpfen. Deshalb werden ihre Rüstungen oft zerschnitten, zerkratzt, zerrissen und verbrannt. Meine Aufgabe ist es, sie zu reparieren.\n\nIch bin kein Rüstungsschmied, aber solange das Loch nicht zu groß ist, kann ich ein kaputtes Kettenrüstungsstück reparieren.\n\nAm liebsten verwende ich Panzerfragmente von Schildkröten, die in den Feldern im Nordosten leben. Besorgt mir welche, damit ich mehr Shado-Pan gerüstet und am Leben erhalten kann.", sourceObjective = "Sammelt 120 Fragmente eines Rankbisspanzers.", progress = "Ich weigere mich, auch nur einen von uns wegen einer kaputten Rüstung fallen zu sehen.", completion = "Ausgezeichnet. Ich werde die Rüstung heute Abend reparieren, wenn die meisten zurück sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[30964] = { id = 30964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verbesserter Verband", description = "Ein trockener Verband hat wenig Nutzen, außer dass er die Wunde frei von Ungeziefer hält. In einigen Lagern ist dies das Beste, worauf man hoffen kann.\n\nAber nicht in meinem.\n\nIch ziehe es vor, eine Paste aus all den lindernden Kräutern zu mischen, derer ich habhaft werden kann, um diese zwischen den Verbänden aufzutragen. Die wirksamsten Kräuter, die ich finden konnte, sind die Mao-Weiden auf den Feldern im Nordosten. Wenn Ihr welche antrefft, bringt sie doch her.", sourceObjective = "Sammelt 11 Mao-Weiden.", progress = "Alles gut gelaufen da draußen, {name}?", completion = "Das sollte reichen.\n\nDie Shado-Pan sind dankbar für Euren Beitrag, {name}.", sourceObjectiveStatus = "unverified-source-field" }
